def update(self, block_data):
    if len(block_data) % 16 != 0:
        raise AssertionError("Block data length must be a multiple of 16")

    result = self.ghash_c.ghash(
        self._last_y,
        c_uint8_ptr(block_data),
        c_size_t(len(block_data)),
        self._last_y,
        self._exp_key.get()
    )

    if result:
        raise ValueError(f"Error {result} while updating GHASH")

    return self

def miller_rabin_test(candidate, iterations, randfunc=None):
    """Perform a Miller-Rabin primality test on an integer."""

    if not isinstance(candidate, Integer):
        candidate = Integer(candidate)

    if candidate in (1, 2, 3, 5):
        return PROBABLY_PRIME

    if candidate.is_even():
        return COMPOSITE

    one = Integer(1)
    minus_one = Integer(candidate - 1)

    if randfunc is None:
        randfunc = Random.new().read

    m, a = Integer(minus_one), 0
    while m.is_even():
        m >>= 1
        a += 1

    for _ in iter_range(iterations):
        base = Integer.random_range(min_inclusive=2, max_inclusive=candidate - 2, randfunc=randfunc)
        while base in (one, minus_one):
            base = Integer.random_range(min_inclusive=2, max_inclusive=candidate - 2, randfunc=randfunc)

        z = pow(base, m, candidate)
        if z in (one, minus_one):
            continue

        for _ in iter_range(1, a):
            z = pow(z, 2, candidate)
            if z == minus_one:
                break
            if z == one:
                return COMPOSITE
        else:
            return COMPOSITE

    return PROBABLY_PRIME

def __init__(self, data=None):
    self._initialize_state()
    self._is_squeezing = False
    self._padding = 0x1F

    if data:
        self.update(data)

def _initialize_state(self):
    state = VoidPointer()
    result = _raw_keccak_lib.keccak_init(state.address_of(), c_size_t(64), c_ubyte(24))
    if result:
        raise ValueError(f"Error {result} while instantiating SHAKE256")
    self._state = SmartPointer(state.get(), _raw_keccak_lib.keccak_destroy)

def get_bit(self, n):
    if self._value < 0:
        raise ValueError("no bit representation for negative values")

    try:
        shift_amount = n._value
    except AttributeError:
        shift_amount = n

    if shift_amount < 0:
        raise ValueError("negative bit count")

    try:
        result = (self._value >> shift_amount) & 1
    except OverflowError:
        result = 0

    return bool(result)

