def import_private_key(self, key_hex, kem_id):
    key_bin = unhexlify(key_hex)
    ecc_curves = {
        0x0010: 'p256',
        0x0011: 'p384',
        0x0012: 'p521'
    }
    if kem_id in ecc_curves:
        return ECC.construct(curve=ecc_curves[kem_id], d=int.from_bytes(key_bin, byteorder="big"))
    dh_methods = {
        0x0020: DH.import_x25519_private_key,
        0x0021: DH.import_x448_private_key
    }
    if kem_id in dh_methods:
        return dh_methods[kem_id](key_bin)

def size_in_bits(self):
    if self._value < 0:
        raise ValueError("Conversion only valid for non-negative numbers")
    return 1 if self._value == 0 else self._value.bit_length()

def __init__(self, data, truncate):
    self._truncate = truncate
    oid_digest_map = {
        None: ("2.16.840.1.101.3.4.2.3", 64),
        "224": ("2.16.840.1.101.3.4.2.5", 28),
        "256": ("2.16.840.1.101.3.4.2.6", 32)
    }

    if truncate not in oid_digest_map:
        raise ValueError("Incorrect truncation length. It must be '224' or '256'.")

    self.oid, self.digest_size = oid_digest_map[truncate]

    state = VoidPointer()
    result = _raw_sha512_lib.SHA512_init(state.address_of(), c_size_t(self.digest_size))
    if result:
        raise ValueError(f"Error {result} while instantiating SHA-512")

    self._state = SmartPointer(state.get(), _raw_sha512_lib.SHA512_destroy)
    if data:
        self.update(data)

def generate_cipher(self, module, key_size, params):
    params_dict = dict(x.split("=") for x in params.split(" ")) if params else {}

    key_multiplier = 2 if params_dict.get('ks') == "x2" else 1
    key = rng(key_multiplier * key_size)
    gen_tuple = [key]

    mode = params_dict.get("mode")
    if mode:
        mode_value = getattr(module, mode, None)
        if mode_value is None:
            raise ModeNotAvailable()
        gen_tuple.append(mode_value)

    iv_length = params_dict.get("iv") or params_dict.get("nonce")
    if iv_length:
        iv_length = module.block_size if iv_length == "bs" else int(iv_length)
        iv = rng(iv_length)
        gen_tuple.append(iv)

    if params_dict.get("little_endian"):
        le = params_dict["little_endian"] == "True"
        gen_tuple.pop()  # Remove iv from parameters
        ctr = Crypto.Util.Counter.new(
            module.block_size * 8,
            initial_value=bytes_to_long(iv),
            little_endian=le,
            allow_wraparound=True
        )
        return module.new(*gen_tuple, counter=ctr)

    return module.new(*gen_tuple)

def sign(self, msg_hash):
    """Compute the DSA/ECDSA signature of a message.

    Args:
      msg_hash (hash object):
        The hash that was carried out over the message.
        The object belongs to the :mod:`Crypto.Hash` package.
        Under mode ``'fips-186-3'``, the hash must be a FIPS
        approved secure hash (SHA-2 or SHA-3).

    :return: The signature as ``bytes``
    :raise ValueError: if the hash algorithm is incompatible to the (EC)DSA key
    :raise TypeError: if the (EC)DSA key has no private half
    """

    self._validate_key_and_hash(msg_hash)

    nonce = self._compute_nonce(msg_hash)
    z = Integer.from_bytes(msg_hash.digest()[:self._order_bytes])
    sig_pair = self._key._sign(z, nonce)

    return self._encode_signature(sig_pair)

def _validate_key_and_hash(self, msg_hash):
    if not self._key.has_private():
        raise TypeError("Private key is needed to sign")
    if not self._valid_hash(msg_hash):
        raise ValueError("Hash is not sufficiently strong")

def _encode_signature(self, sig_pair):
    if self._encoding == 'binary':
        return b"".join(long_to_bytes(x, self._order_bytes) for x in sig_pair)
    return DerSequence(sig_pair).encode()

def runTest(self):
    for data, custom, digest, text, module in self.test_data:
        hd1 = module.new(custom=custom, digest_bytes=len(digest))
        hd2 = module.new(custom=custom, digest_bytes=len(digest))

        self._update_and_assert(hd1, data, digest, text)
        self._update_and_assert(hd2, data, digest, text, single_update=True)

def _update_and_assert(self, hasher, data, expected_digest, message, single_update=False):
    if single_update:
        hasher.update(*data)
    else:
        for string in data:
            hasher.update(string)
    self.assertEqual(hasher.digest(), expected_digest, msg=message)

def test_mix(self):
    p1 = ECC.generate(curve='P-256').pointQ
    p2 = ECC.generate(curve='P-384').pointQ

    def assert_value_error(operation):
        try:
            operation()
            assert False
        except ValueError as e:
            assert "not on the same curve" in str(e)

    assert_value_error(lambda: p1 + p2)
    assert_value_error(lambda: p1.__iadd__(p2))

    class OtherKeyType:
        pass

    self.assertFalse(p1 == OtherKeyType())
    self.assertTrue(p1 != OtherKeyType())

