def __mul__(self, term):
    if not isinstance(term, IntegerGMP):
        try:
            term = IntegerGMP(term)
        except NotImplementedError:
            return NotImplemented
    result = IntegerGMP(0)
    _gmp.mpz_mul(result._mpz_p, self._mpz_p, term._mpz_p)
    return result

def __irshift__(self, pos):
    try:
        self._value >>= int(pos)
    except OverflowError:
        return 0 if self._value >= 0 else -1
    return self

def _create_base_cipher(dict_parameters):
    """This method instantiates and returns a handle to a low-level base cipher.
    It will absorb named parameters in the process."""

    key_in = dict_parameters.pop("key", None)
    if key_in is None:
        raise TypeError("Missing 'key' parameter")

    key = adjust_key_parity(bstr(key_in))

    cipher = VoidPointer()
    result = _raw_des3_lib.DES3_start_operation(
        key, c_size_t(len(key)), cipher.address_of()
    )
    if result:
        raise ValueError(f"Error {result:X} while instantiating the TDES cipher")

    return SmartPointer(cipher.get(), _raw_des3_lib.DES3_stop_operation)

