def c_uint8_ptr(data):
    if isinstance(data, _buffer_type):
        return ffi.cast(uint8_t_type, ffi.from_buffer(data))
    if byte_string(data) or isinstance(data, _Array):
        return data
    raise TypeError(f"Object type {type(data)} cannot be passed to C code")

def __imod__(self, term):
    modulus = int(term)
    if modulus <= 0:
        raise (ZeroDivisionError if modulus == 0 else ValueError)(
            "Division by zero" if modulus == 0 else "Modulus must be positive"
        )
    self._value %= modulus
    return self

def ptn(n):
    res = bytearray(n)
    pattern = bytes(range(0xFB))
    full_chunks = n // 0xFB
    remain = n % 0xFB

    for base in range(full_chunks):
        res[base * 0xFB:(base + 1) * 0xFB] = pattern

    if remain:
        res[full_chunks * 0xFB:] = pattern[:remain]

    return res

def _decrypt_to_bytes(self, ciphertext):
    if not 0 <= ciphertext < self._n:
        raise ValueError("Ciphertext too large")
    if not self.has_private():
        raise TypeError("This is not a private key")

    r = Integer.random_range(min_inclusive=1, max_exclusive=self._n)
    cp = Integer(ciphertext) * pow(r, self._e, self._n) % self._n
    m1 = pow(cp, self._dp, self._p)
    m2 = pow(cp, self._dq, self._q)
    h = ((m2 - m1) * self._u) % self._q
    mp = h * self._p + m1

    return Integer._mult_modulo_bytes(r.inverse(self._n), mp, self._n)

def _import_keyDER(extern_key, passphrase):
    """Import an RSA key (public or private half), encoded in DER form."""

    for decoding in (
        _import_pkcs1_private,
        _import_pkcs1_public,
        _import_subjectPublicKeyInfo,
        _import_x509_cert,
        _import_pkcs8
    ):
        try:
            return decoding(extern_key, passphrase)
        except ValueError:
            continue

    raise ValueError("RSA key format is not supported")

def __iadd__(self, point):
    """Add a second point to this one"""
    result = self._curve.rawlib.add(self._point.get(), point._point.get())
    if result:
        error_messages = {
            16: "EC points are not on the same curve"
        }
        raise ValueError(error_messages.get(result, f"Error {result} while adding two EC points"))
    return self

def __init__(self, data, update_after_digest):
    self._update_after_digest = update_after_digest
    self._digest_done = False
    self._padding = 0x06

    self._state = self._initialize_state()
    if data:
        self.update(data)

def _initialize_state(self):
    state = VoidPointer()
    result = _raw_keccak_lib.keccak_init(
        state.address_of(),
        c_size_t(self.digest_size * 2),
        c_ubyte(24)
    )
    if result:
        raise ValueError(f"Error {result} while instantiating SHA-3/256")
    return SmartPointer(state.get(), _raw_keccak_lib.keccak_destroy)

def tobytes(s, encoding="latin-1"):
    if isinstance(s, (bytes, bytearray, memoryview)):
        return bytes(s)
    if isinstance(s, str):
        return s.encode(encoding)
    return bytes([s])

def _tonelli_shanks(n, p):
    """Tonelli-Shanks algorithm for computing the square root of n modulo a prime p."""

    if n in (0, 1):
        return n

    if p % 4 == 3:
        root = pow(n, (p + 1) // 4, p)
        if pow(root, 2, p) != n:
            raise ValueError("Cannot compute square root")
        return root

    s, q = 1, (p - 1) // 2
    while not (q & 1):
        s += 1
        q >>= 1

    z = n.__class__(2)
    while pow(z, (p - 1) // 2, p) != p - 1:
        z += 1

    m, c, t, r = s, pow(z, q, p), pow(n, q, p), pow(n, (q + 1) // 2, p)

    while t != 1:
        i = next(i for i in range(m) if pow(t, 2**i, p) == 1)
        b = pow(c, 2**(m - i - 1), p)
        m, c, t, r = i, b**2 % p, (t * b**2) % p, (r * b) % p

    if pow(r, 2, p) != n:
        raise ValueError("Cannot compute square root")

    return r

def test_ptn_17_4(self):
    tv = """02 CC 3A 88 97 E6 F4 F6 CC B6 FD 46 63 1B 1F 52
    07 B6 6C 6D E9 C7 B5 5B 2D 1A 23 13 4A 17 0A FD
    AC 23 4E AB A9 A7 7C FF 88 C1 F0 20 B7 37 24 61
    8C 56 87 B3 62 C4 30 B2 48 CD 38 64 7F 84 8A 1D"""

    btv = txt2bin(tv)
    data = ptn(17**4)

    def assert_turboshake256(data, expected, chunk_size=None):
        xof = TurboSHAKE256.new()
        if chunk_size:
            for chunk in chunked(data, chunk_size):
                xof.update(chunk)
        else:
            for x in data:
                xof.update(bchr(x))
        self.assertEqual(xof.read(64), expected)

    # All at once
    self.assertEqual(TurboSHAKE256.new(data=data).read(64), btv)

    # Byte by byte
    assert_turboshake256(data, btv)

    # Chunks of various prime sizes
    for chunk_size in (13, 17, 19, 23, 31):
        assert_turboshake256(data, btv, chunk_size)

def _export_SEC1(self, compress):
    if not self._curve.is_weierstrass:
        raise ValueError("SEC1 format is only supported for NIST P curves")

    modulus_bytes = self.pointQ.size_in_bytes()
    x_bytes = self.pointQ.x.to_bytes(modulus_bytes)

    if compress:
        first_byte = b'\x03' if self.pointQ.y.is_odd() else b'\x02'
        return first_byte + x_bytes

    y_bytes = self.pointQ.y.to_bytes(modulus_bytes)
    return b'\x04' + x_bytes + y_bytes

def _pbkdf2_hmac_assist(inner, outer, first_digest, iterations):
    """Compute the expensive inner loop in PBKDF-HMAC."""
    if iterations <= 0:
        raise ValueError("Iterations must be greater than 0")

    bfr = create_string_buffer(len(first_digest))
    result = _raw_sha384_lib.SHA384_pbkdf2_hmac_assist(
        inner._state.get(),
        outer._state.get(),
        first_digest,
        bfr,
        c_size_t(iterations),
        c_size_t(len(first_digest))
    )

    if result:
        raise ValueError(f"Error {result} with PBKDF2-HMAC assist for SHA384")

    return get_raw_buffer(bfr)

def jacobi_symbol(a, n):
    """Compute the Jacobi symbol"""

    a = IntegerGMP(a) if not isinstance(a, IntegerGMP) else a
    n = IntegerGMP(n) if not isinstance(n, IntegerGMP) else n

    if n <= 0 or n.is_even():
        raise ValueError("n must be positive odd for the Jacobi symbol")

    return _gmp.mpz_jacobi(a._mpz_p, n._mpz_p)

import os
import sys
from distutils import ccompiler
from distutils.errors import CCompilerError

def test_compilation(program, extra_cc_options=None, extra_libraries=None, msg=''):
    """Test if a certain C program can be compiled."""
    setup_build_directory()
    fname, oname = prepare_filenames()
    debug = bool(os.environ.get('PYCRYPTODOME_DEBUG', None))

    if msg:
        print(f"Testing support for {msg}")

    if not (debug or os.name == 'nt'):
        old_stdout, old_stderr, dev_null = mute_output()

    try:
        result = compile_and_link(program, fname, oname, extra_cc_options, extra_libraries)
    except (CCompilerError, OSError):
        result = False

    cleanup_files([fname, oname])
    if not (debug or os.name == 'nt'):
        restore_output(old_stdout, old_stderr, dev_null)

    if msg:
        print(f"Target does{' not' if not result else ''} support {msg}")

    return result

def setup_build_directory():
    if not os.path.exists("build"):
        os.makedirs("build")

def prepare_filenames():
    fname = os.path.join("build", "test1.c")
    oname = os.path.join("build", "test1.out")
    return fname, oname

def mute_output():
    old_stdout = os.dup(sys.stdout.fileno())
    old_stderr = os.dup(sys.stderr.fileno())
    dev_null = open(os.devnull, "w")
    os.dup2(dev_null.fileno(), sys.stdout.fileno())
    os.dup2(dev_null.fileno(), sys.stderr.fileno())
    return old_stdout, old_stderr, dev_null

def restore_output(old_stdout, old_stderr, dev_null):
    if old_stdout is not None:
        os.dup2(old_stdout, sys.stdout.fileno())
    if old_stderr is not None:
        os.dup2(old_stderr, sys.stderr.fileno())
    if dev_null is not None:
        dev_null.close()

def compile_and_link(program, fname, oname, extra_cc_options, extra_libraries):
    with open(fname, 'w') as f:
        f.write(program)

    compiler = ccompiler.new_compiler()
    distutils.sysconfig.customize_compiler(compiler)

    extra_linker_options = ["/MANIFEST"] if compiler.compiler_type == 'msvc' else []
    if compiler.compiler_type == 'unix':
        compiler.set_executables(linker_exe=compiler.compiler)

    objects = compiler.compile([fname], extra_postargs=extra_cc_options)
    compiler.link_executable(objects, oname, libraries=extra_libraries, extra_preargs=extra_linker_options)
    return True

def cleanup_files(files):
    for f in files:
        try:
            os.remove(f)
        except OSError:
            pass

def _do_kat_aes_test(self, file_name, segment_size):
    test_vectors = load_test_vectors(
        ("Cipher", "AES"),
        file_name,
        f"AES CFB{segment_size} KAT",
        {"count": int}
    )
    if test_vectors is None:
        return

    for tv in test_vectors:
        if is_string(tv):
            direction = tv
            continue

        self.description = tv.desc
        cipher = AES.new(tv.key, AES.MODE_CFB, tv.iv, segment_size=segment_size)
        if direction == "[ENCRYPT]":
            self.assertEqual(cipher.encrypt(tv.plaintext), tv.ciphertext)
        elif direction == "[DECRYPT]":
            self.assertEqual(cipher.decrypt(tv.ciphertext), tv.plaintext)

def run(self):
    self._run_sub_commands()
    self._run_self_tests()
    self.announce("running extended self-tests")

def _run_sub_commands(self):
    for cmd_name in self.get_sub_commands():
        self.run_command(cmd_name)

def _run_self_tests(self):
    old_path = sys.path[:]
    self.announce("running self-tests on " + package_root)
    try:
        sys.path.insert(0, self.build_dir)
        SelfTest, Numbers = self._import_selftest_modules()
        moduleObj = self._import_test_module()
        print(package_root + ".Math implementation:", str(Numbers._implementation))
        SelfTest.run(module=moduleObj, verbosity=self.verbose, stream=sys.stdout, config=self.config)
    finally:
        sys.path[:] = old_path

def _import_selftest_modules(self):
    if use_separate_namespace:
        from Cryptodome import SelfTest
        from Cryptodome.Math import Numbers
    else:
        from Crypto import SelfTest
        from Crypto.Math import Numbers
    return SelfTest, Numbers

def _import_test_module(self):
    if not self.module:
        return None
    if self.module.count('.') == 0:
        full_module = package_root + ".SelfTest." + self.module
        module_name = self.module
    else:
        comps = self.module.split('.')
        module_name = "test_" + comps[1]
        full_module = package_root + ".SelfTest." + comps[0] + "." + module_name
    return __import__(full_module, globals(), locals(), module_name)

def __init__(self, data, key, digest_bytes, update_after_digest):
    self.digest_size = digest_bytes
    self._update_after_digest = update_after_digest
    self._digest_done = False

    self._set_oid(digest_bytes, key)
    self._initialize_state(key, digest_bytes)

    if data:
        self.update(data)

def _set_oid(self, digest_bytes, key):
    if digest_bytes in (20, 32, 48, 64) and not key:
        self.oid = "1.3.6.1.4.1.1722.12.2.1." + str(digest_bytes // 4)

def _initialize_state(self, key, digest_bytes):
    state = VoidPointer()
    result = _raw_blake2b_lib.blake2b_init(
        state.address_of(),
        c_uint8_ptr(key),
        c_size_t(len(key)),
        c_size_t(digest_bytes)
    )
    if result:
        raise ValueError(f"Error {result} while instantiating BLAKE2b")
    self._state = SmartPointer(state.get(), _raw_blake2b_lib.blake2b_destroy)

def _import_public_der(ec_point, curve_oid=None, curve_name=None):
    """Convert an encoded EC point into an EccKey object"""

    curve = None
    for _curve_name, candidate_curve in _curves.items():
        if (curve_oid and candidate_curve.oid == curve_oid) or (curve_name == _curve_name):
            curve = candidate_curve
            break

    if not curve:
        raise UnsupportedEccFeature(
            "Unsupported ECC curve (OID: %s)" % curve_oid if curve_oid else "Unsupported ECC curve (%s)" % curve_name
        )

    modulus_bytes = curve.p.size_in_bytes()
    point_type = bord(ec_point[0])

    if point_type == 0x04:
        if len(ec_point) != (1 + 2 * modulus_bytes):
            raise ValueError("Incorrect EC point length")
        x = Integer.from_bytes(ec_point[1:modulus_bytes+1])
        y = Integer.from_bytes(ec_point[modulus_bytes+1:])
    elif point_type in (0x02, 0x03):
        if len(ec_point) != (1 + modulus_bytes):
            raise ValueError("Incorrect EC point length")
        x = Integer.from_bytes(ec_point[1:])
        y = (x**3 - x*3 + curve.b).sqrt(curve.p)
        if (point_type == 0x02 and y.is_odd()) or (point_type == 0x03 and y.is_even()):
            y = curve.p - y
    else:
        raise ValueError("Incorrect EC point encoding")

    return construct(curve=_curve_name, point_x=x, point_y=y)

def _update(self, assoc_data_pt=b""):
    """Update the MAC with associated data or plaintext
       (without FSM checks)"""

    if self._mac_status == MacStatus.NOT_STARTED:
        self._cache.append(_copy_bytes(None, None, assoc_data_pt) if is_writeable_buffer(assoc_data_pt) else assoc_data_pt)
        return

    assert len(self._cache) < self.block_size

    if self._cache:
        self._process_cache(assoc_data_pt)
        if len(self._cache) < self.block_size:
            return

    self._process_remaining_data(assoc_data_pt)

def _process_cache(self, assoc_data_pt):
    filler = min(self.block_size - len(self._cache), len(assoc_data_pt))
    self._cache += _copy_bytes(None, filler, assoc_data_pt)
    assoc_data_pt = _copy_bytes(filler, None, assoc_data_pt)

    if len(self._cache) == self.block_size:
        self._t = self._mac.encrypt(self._cache)
        self._cache = b""

def _process_remaining_data(self, assoc_data_pt):
    update_len = len(assoc_data_pt) // self.block_size * self.block_size
    self._cache = _copy_bytes(update_len, None, assoc_data_pt)
    if update_len > 0:
        self._t = self._mac.encrypt(assoc_data_pt[:update_len])[-16:]

def __init__(self, r, s, data):
    self._validate_length(r, "r")
    self._validate_length(s, "s")

    self._mac_tag = None
    self._state = self._initialize_state(r, s)

    if data:
        self.update(data)

def _validate_length(self, param, name):
    if len(param) != 16:
        raise ValueError(f"Parameter {name} is not 16 bytes long")

def _initialize_state(self, r, s):
    state = VoidPointer()
    result = _raw_poly1305.poly1305_init(
        state.address_of(),
        c_uint8_ptr(r),
        c_size_t(len(r)),
        c_uint8_ptr(s),
        c_size_t(len(s))
    )
    if result:
        raise ValueError(f"Error {result} while instantiating Poly1305")
    return SmartPointer(state.get(), _raw_poly1305.poly1305_destroy)

def __init__(self, key, msg=b"", digestmod=None):
    digestmod = digestmod or self._default_digestmod()
    msg = msg or b""

    self.digest_size = digestmod.digest_size
    self._digestmod = digestmod
    self.oid = self._get_oid(digestmod)

    key = self._prepare_key(key, digestmod)
    key_0_ipad = strxor(key, b"\x36" * len(key))
    self._inner = digestmod.new(key_0_ipad)
    self._inner.update(msg)

    key_0_opad = strxor(key, b"\x5c" * len(key))
    self._outer = digestmod.new(key_0_opad)

def _default_digestmod(self):
    from Crypto.Hash import MD5
    return MD5

def _get_oid(self, digestmod):
    try:
        return _hash2hmac_oid[digestmod.oid]
    except (KeyError, AttributeError):
        return None

def _prepare_key(self, key, digestmod):
    if isinstance(key, memoryview):
        key = key.tobytes()

    try:
        if len(key) <= digestmod.block_size:
            return key + b"\x00" * (digestmod.block_size - len(key))
        else:
            hash_k = digestmod.new(key).digest()
            return hash_k + b"\x00" * (digestmod.block_size - len(hash_k))
    except AttributeError:
        raise ValueError("Hash type incompatible to HMAC")

