def test1(self):
    # Test only for HMAC-SHA1 as PRF

    def prf_SHA1(p, s):
        return HMAC.new(p, s, SHA1).digest()

    def prf_SHA256(p, s):
        return HMAC.new(p, s, SHA256).digest()

    for i, v in enumerate(self._testData):
        password, salt_hex, out_len, iters, hash_mod, expected_hex = v
        salt = t2b(salt_hex)
        expected = t2b(expected_hex)

        prf = prf_SHA1 if hash_mod is SHA1 else prf_SHA256
        res = PBKDF2(password, salt, out_len, iters, prf)
        self.assertEqual(res, expected)

        if hash_mod is SHA1:
            res = PBKDF2(password, salt, out_len, iters)
            self.assertEqual(res, expected)

def test_new_positive(self):
    def check_digest_size(new_func, size, is_bits=True):
        hobj = new_func(digest_bits=size) if is_bits else new_func(digest_bytes=size)
        expected_size = size // 8 if is_bits else size
        self.assertEqual(hobj.digest_size, expected_size)

    def check_digest_equality(new_func):
        digest1 = new_func(data=b"\x90", digest_bytes=self.max_bytes).digest()
        digest2 = new_func(digest_bytes=self.max_bytes).update(b"\x90").digest()
        self.assertEqual(digest1, digest2)

    h = self.BLAKE2.new(digest_bits=self.max_bits)
    for new_func in self.BLAKE2.new, h.new:
        for dbits in range(8, self.max_bits + 1, 8):
            check_digest_size(new_func, dbits)

        for dbytes in range(1, self.max_bytes + 1):
            check_digest_size(new_func, dbytes, is_bits=False)

        check_digest_equality(new_func)
        new_func(data=b"A", key=b"5", digest_bytes=self.max_bytes)

    hobj = h.new()
    self.assertEqual(hobj.digest_size, self.max_bytes)

def new(self, **kwargs):
    """Return a new instance of a TupleHash object.
    See :func:`new`.
    """
    kwargs.setdefault("digest_bytes", self.digest_size)
    return new(**kwargs)

def create_string_buffer(init_or_size, size=None):
    """Allocate the given amount of bytes (initially set to 0)"""

    if isinstance(init_or_size, bytes):
        size = max(len(init_or_size) + 1, size)
        result = ffi.new("uint8_t[]", size)
        result[:] = init_or_size
    elif size is not None:
        raise ValueError("Size must be specified once only")
    else:
        result = ffi.new("uint8_t[]", init_or_size)

    return result

def _import_key_der(key_data, passphrase, params):
    """Import a DSA key (public or private half), encoded in DER form."""

    for decoding in (
        _import_openssl_private,
        _import_subjectPublicKeyInfo,
        _import_x509_cert,
        _import_pkcs8,
    ):
        try:
            return decoding(key_data, passphrase, params)
        except ValueError:
            continue

    raise ValueError("DSA key format is not supported")

def __imul__(self, term):
    if is_native_int(term):
        if -65535 < term < 65536:
            multiplier = c_ulong(abs(term))
            _gmp.mpz_mul_ui(self._mpz_p, self._mpz_p, multiplier)
            if term < 0:
                _gmp.mpz_neg(self._mpz_p, self._mpz_p)
            return self
        term = IntegerGMP(term)
    _gmp.mpz_mul(self._mpz_p, self._mpz_p, term._mpz_p)
    return self

def get64(z, words):
    """Return a C string with the number encoded into 64-bit words"""

    x = z if words == 9 else (z * (1 << (words * 64))) % p

    result = [
        "0x%016XULL" % ((x >> (64 * i)) & ((1 << 64) - 1))
        for i in range(words)
    ]
    return ",".join(result)

