def load_pycryptodome_raw_lib(name, cdecl):
    """Load a shared library and return a handle to it.

    @name,  the name of the library expressed as a PyCryptodome module,
            for instance Crypto.Cipher._raw_cbc.

    @cdecl, the C function declarations.
    """
    dir_comps, basename = name.rsplit(".", 1)
    attempts = []

    for ext in extension_suffixes:
        filename = basename + ext
        full_name = pycryptodome_filename(dir_comps.split("."), filename)

        if os.path.isfile(full_name):
            try:
                return load_lib(full_name, cdecl)
            except OSError as exp:
                attempts.append(f"Cannot load '{filename}': {exp}")
        else:
            attempts.append(f"Not found '{filename}'")

    raise OSError(f"Cannot load native module '{name}': {', '.join(attempts)}")

def __init__(self, data, update_after_digest):
    self._update_after_digest = update_after_digest
    self._digest_done = False
    self._padding = 0x06

    self._state = self._initialize_state()
    if data:
        self.update(data)

def _initialize_state(self):
    state = VoidPointer()
    result = _raw_keccak_lib.keccak_init(
        state.address_of(),
        c_size_t(self.digest_size * 2),
        c_ubyte(24)
    )
    if result:
        raise ValueError(f"Error {result} while instantiating SHA-3/512")
    return SmartPointer(state.get(), _raw_keccak_lib.keccak_destroy)

def __eq__(self, other):
    if self.has_private() != other.has_private():
        return False
    if self.n == other.n and self.e == other.e:
        return not self.has_private() or self.d == other.d
    return False

def _decodeFromStream(self, s, strict):
    """Decode a complete DER SEQUENCE from a file."""

    self._seq = []

    # Fill up self.payload
    DerObject._decodeFromStream(self, s, strict)

    # Add one item at a time to self.seq, by scanning self.payload
    p = BytesIO_EOF(self.payload)
    while p.remaining_data() > 0:
        p.set_bookmark()

        der = DerObject()
        der._decodeFromStream(p, strict)

        # Parse INTEGERs differently
        if der._tag_octet == 0x02:
            derInt = DerInteger()
            data = p.data_since_bookmark()
            derInt.decode(data, strict=strict)
            self._seq.append(derInt.value)
        else:
            self._seq.append(p.data_since_bookmark())

    if self._nr_elements is not None:
        if isinstance(self._nr_elements, int):
            ok = len(self._seq) == self._nr_elements
        else:
            ok = len(self._seq) in self._nr_elements

        if not ok:
            raise ValueError("Unexpected number of members (%d) in the sequence" % len(self._seq))

def new(**kwargs):
    """Create a new hash object."""

    def validate_digest_params(digest_bytes, digest_bits):
        if None not in (digest_bytes, digest_bits):
            raise TypeError("Only one digest parameter must be provided")
        if digest_bytes is None and digest_bits is None:
            return 64
        if digest_bytes is not None:
            if not (1 <= digest_bytes <= 64):
                raise ValueError("'digest_bytes' not in range 1..64")
            return digest_bytes
        if not (8 <= digest_bits <= 512) or (digest_bits % 8):
            raise ValueError("'digest_bits' not in range 8..512, with steps of 8")
        return digest_bits // 8

    data = kwargs.pop("data", None)
    update_after_digest = kwargs.pop("update_after_digest", False)
    digest_bytes = validate_digest_params(kwargs.pop("digest_bytes", None), kwargs.pop("digest_bits", None))
    key = kwargs.pop("key", b"")

    if len(key) > 64:
        raise ValueError("BLAKE2b key cannot exceed 64 bytes")
    if kwargs:
        raise TypeError("Unknown parameters: " + str(kwargs))

    return BLAKE2b_Hash(data, key, digest_bytes, update_after_digest)

def _compute_ecdh(key_priv, key_pub):
    pointP = key_pub.pointQ * key_priv.d
    if pointP.is_point_at_infinity():
        raise ValueError("Invalid ECDH point")

    curve_to_bytes_length = {
        "Curve25519": 32,
        "Curve448": 56
    }

    byte_length = curve_to_bytes_length.get(key_priv.curve, pointP.size_in_bytes())
    z = bytearray(pointP.x.to_bytes(byte_length, byteorder='little')) if key_priv.curve in curve_to_bytes_length else long_to_bytes(pointP.x, byte_length)

    return z

def test_verify(self, tv):
    self._id = f"Wycheproof RSA PSS Test #{tv.id} ({tv.comment})"
    hashed_msg = tv.hash_module.new(tv.msg)
    signer = pss.new(tv.key, mask_func=tv.mgf, salt_bytes=tv.sLen)

    try:
        signer.verify(hashed_msg, tv.sig)
    except ValueError:
        if not tv.warning:
            assert not tv.valid
    else:
        assert tv.valid
        self.warn(tv)

