def _build_impl(lib, postfix):
    from collections import namedtuple

    funcs = ("ghash", "ghash_expand", "ghash_destroy")
    GHASH_Imp = namedtuple('_GHash_Imp', funcs)

    imp_funcs = [getattr(lib, f"{func}_{postfix}", None) for func in funcs]

