def multiply_accumulate(self, a, b):
    """Increment the number by the product of a and b."""

    if not isinstance(a, IntegerGMP):
        a = IntegerGMP(a)

    if is_native_int(b):
        if 0 < b < 65536:
            _gmp.mpz_addmul_ui(self._mpz_p, a._mpz_p, c_ulong(b))
        elif -65535 < b < 0:
            _gmp.mpz_submul_ui(self._mpz_p, a._mpz_p, c_ulong(-b))
        else:
            b = IntegerGMP(b)
            _gmp.mpz_addmul(self._mpz_p, a._mpz_p, b._mpz_p)
    else:
        _gmp.mpz_addmul(self._mpz_p, a._mpz_p, b._mpz_p)

    return self

def _bcrypt_encode(data):
    s = "./ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789"

    bits = b"".join(bstr(bin(bord(c))[2:].zfill(8)) for c in data)
    result = [
        s[int(bits[idx:idx+6], 2)] for idx in range(0, len(bits) - 6, 6)
    ]

    last_bits = bits[len(bits) - len(bits) % 6:]
    if last_bits:
        idx = int(last_bits, 2) << (6 - len(last_bits))
        result.append(s[idx])

    return tobytes("".join(result))

def test_valid_full_path(self):
    def verify_path(cipher, data, ct=None, mac=None):
        cipher.update(data)
        if ct is not None:
            cipher.decrypt(ct)
            cipher.verify(mac)
        else:
            ct = cipher.encrypt(data)
            mac = cipher.digest()
        return ct, mac

    for assoc_len in (None, len(self.data)):
        for msg_len in (None, len(self.data)):
            cipher = AES.new(self.key_128, AES.MODE_CCM, nonce=self.nonce_96, assoc_len=assoc_len, msg_len=msg_len)
            ct, mac = verify_path(cipher, self.data)

            cipher = AES.new(self.key_128, AES.MODE_CCM, nonce=self.nonce_96, assoc_len=assoc_len, msg_len=msg_len)
            verify_path(cipher, self.data, ct, mac)

def _do_tdes_test(self, file_name):
    test_vectors = load_test_vectors(
        ("Cipher", "TDES"),
        file_name,
        "TDES CBC KAT",
        {"count": lambda x: int(x)}
    )
    if test_vectors is None:
        return

    direction = None
    for tv in test_vectors:
        if is_string(tv):
            direction = tv
            continue

        self.description = tv.desc
        cipher = self._create_cipher(tv)

        if direction == "[ENCRYPT]":
            self.assertEqual(cipher.encrypt(tv.plaintext), tv.ciphertext)
        elif direction == "[DECRYPT]":
            self.assertEqual(cipher.decrypt(tv.ciphertext), tv.plaintext)

def _create_cipher(self, tv):
    if hasattr(tv, "keys"):
        return DES.new(tv.keys, self.des_mode, tv.iv)
    key = tv.key1 + tv.key2 + (tv.key3 if tv.key1 != tv.key3 else "")
    return DES3.new(key, self.des3_mode, tv.iv)

def ceil_div(n, d):
    """Return ceil(n/d), that is, the smallest integer r such that r*d >= n"""
    if d <= 0 or n < 0:
        raise ValueError("Non positive values or division by zero")
    r, q = divmod(n, d)
    return r + (q != 0)

def monty_pow(base, exp, modulus):
    max_len = len(long_to_bytes(max(base, exp, modulus)))
    base_b, exp_b, modulus_b = (long_to_bytes(x, max_len) for x in (base, exp, modulus))

    out = create_string_buffer(max_len)
    error = _raw_montgomery.monty_pow(out, base_b, exp_b, modulus_b, c_size_t(max_len), c_ulonglong(32))

    if error:
        if error == 17:
            raise ExceptionModulus()
        raise ValueError(f"monty_pow failed with error: {error}")

    return bytes_to_long(get_raw_buffer(out))

def construct(tup):
    r"""Construct an ElGamal key from a tuple of valid ElGamal components."""

    if len(tup) not in [3, 4]:
        raise ValueError('argument for construct() wrong length')

    obj = ElGamalKey()
    for i, value in enumerate(tup):
        setattr(obj, obj._keydata[i], Integer(value))

    if not is_valid_elgamal_key(obj, len(tup) == 4):
        raise ValueError("Invalid ElGamal key components")

    return obj

def is_valid_elgamal_key(obj, has_private_key):
    if test_probable_prime(obj.p) == COMPOSITE:
        return False
    if not (1 < obj.g < obj.p):
        return False
    if pow(obj.g, obj.p - 1, obj.p) != 1:
        return False
    if not (1 <= obj.y < obj.p):
        return False
    if has_private_key:
        if not (1 < obj.x < obj.p):
            return False
        if pow(obj.g, obj.x, obj.p) != obj.y:
            return False
    return True

def __init__(self, data, custom, capacity, function):
    state = VoidPointer()
    prefix = None

    if custom or function:
        prefix_unpad = _encode_str(function) + _encode_str(custom)
        prefix = _bytepad(prefix_unpad, (1600 - capacity) // 8)
        self._padding = 0x04
    else:
        self._padding = 0x1F  # for SHAKE

    result = _raw_keccak_lib.keccak_init(state.address_of(),
                                         c_size_t(capacity // 8),
                                         c_ubyte(24))
    if result:
        raise ValueError(f"Error {result} while instantiating cSHAKE")

    self._state = SmartPointer(state.get(), _raw_keccak_lib.keccak_destroy)
    self._is_squeezing = False

    if prefix:
        self.update(prefix)

    if data:
        self.update(data)

def _new(self):
    params = self.extra_params.copy()
    key = a2b_hex(self.key)

    old_style = [self.mode] if self.mode is not None else []
    if self.iv is not None:
        old_style.append(a2b_hex(self.iv))

    return self.module.new(key, *old_style, **params)

def test_random_range(self):
    func = IntegerNative.random_range

    def assert_in_range(min_val, max_val, inclusive=True):
        for _ in range(200):
            a = func(min_inclusive=min_val, max_inclusive=max_val) if inclusive else func(min_inclusive=min_val, max_exclusive=max_val)
            self.assertTrue(min_val <= a <= max_val if inclusive else min_val <= a < max_val)

    assert_in_range(1, 15, inclusive=True)
    assert_in_range(1, 15, inclusive=False)

    self.assertRaises(ValueError, func, min_inclusive=1, max_inclusive=2, max_exclusive=3)
    self.assertRaises(ValueError, func, max_inclusive=2, max_exclusive=3)

