def _load_tests(self, test_vector_file):
    test_vectors = []
    with open(test_vector_file, "rt") as test_vector_fd:
        for line_number, line in enumerate(test_vector_fd):
            line = line.strip()
            if not line or line.startswith("#"):
                continue
            res = re.match(r"digest\(([0-9]+)\): ([0-9A-Fa-f]*)", line)
            if res:
                key_size = int(res.group(1))
                result = unhexlify(tobytes(res.group(2)))
                test_vectors.append((key_size, result))
            else:
                raise ValueError(f"Incorrect test vector format (line {line_number})")
    return test_vectors

def _import_pkcs8(encoded, passphrase):
    from Crypto.IO import PKCS8

    algo_oid, private_key, params = PKCS8.unwrap(encoded, passphrase)

    nist_p_oids = {
        "1.2.840.10045.2.1",  # id-ecPublicKey (unrestricted)
        "1.3.132.1.12",       # id-ecDH
        "1.3.132.1.13"        # id-ecMQV
    }
    eddsa_oids = {
        "1.3.101.112": "Ed25519",  # id-Ed25519
        "1.3.101.113": "Ed448",    # id-Ed448
    }
    xdh_oids = {
        "1.3.101.110": "Curve25519",  # id-X25519
        "1.3.101.111": "Curve448",    # id-X448
    }

    def handle_nist_p_oids():
        curve_oid = DerObjectId().decode(params).value
        return _import_rfc5915_der(private_key, passphrase, curve_oid)

    def handle_eddsa_oids():
        if params is not None:
            raise ValueError("EdDSA ECC private key must not have parameters")
        seed = DerOctetString().decode(private_key).payload
        return construct(curve=eddsa_oids[algo_oid], seed=seed)

    def handle_xdh_oids():
        curve_name = xdh_oids[algo_oid]
        if params is not None:
            raise ValueError(f"{curve_name} ECC private key must not have parameters")
        seed = DerOctetString().decode(private_key).payload
        return construct(curve=curve_name, seed=seed)

    if algo_oid in nist_p_oids:
        return handle_nist_p_oids()
    elif algo_oid in eddsa_oids:
        return handle_eddsa_oids()
    elif algo_oid in xdh_oids:
        return handle_xdh_oids()
    else:
        raise UnsupportedEccFeature(f"Unsupported ECC purpose (OID: {algo_oid})")

def make_stream_tests(module, module_name, test_data):
    def build_params(row):
        params = {}
        if len(row) == 3:
            params['plaintext'], params['ciphertext'], params['key'] = row
        elif len(row) == 4:
            params['plaintext'], params['ciphertext'], params['key'], params['description'] = row
        elif len(row) == 5:
            params['plaintext'], params['ciphertext'], params['key'], params['description'], extra_params = row
            params.update(extra_params)
        else:
            raise AssertionError(f"Unsupported tuple size {len(row)}")
        return params

    def build_description(params, index):
        p2 = params.copy()
        p_key = _extract(p2, 'key')
        p_plaintext = _extract(p2, 'plaintext')
        p_ciphertext = _extract(p2, 'ciphertext')
        p_description = _extract(p2, 'description', None)

        if p_description is not None:
            description = p_description
        elif not p2:
            description = f"p={p_plaintext}, k={p_key}"
        else:
            description = f"p={p_plaintext}, k={p_key}, {p2!r}"
        return f"{module_name} #{index + 1}: {description}"

    tests = []
    extra_tests_added = False
    for i, row in enumerate(test_data):
        params = build_params(row)
        params['description'] = build_description(params, i)
        params['module_name'] = module_name

        if not extra_tests_added:
            tests.extend([
                ByteArrayTest(module, params),
                MemoryviewTest(module, params)
            ])
            extra_tests_added = True

        tests.extend([
            CipherSelfTest(module, params),
            CipherStreamingSelfTest(module, params)
        ])
    return tests

def construct(tup, consistency_check=True):
    """Construct a DSA key from a tuple of valid DSA components."""

    key_dict = dict(zip(('y', 'g', 'p', 'q', 'x'), map(Integer, tup)))
    key = DsaKey(key_dict)

    if consistency_check and not is_valid_dsa_key(key):
        raise ValueError("Invalid DSA key components")

    return key

def is_valid_dsa_key(key):
    """Check if the DSA key components are valid."""
    if test_probable_prime(key.p) == COMPOSITE or test_probable_prime(key.q) == COMPOSITE:
        return False
    if (key.p - 1) % key.q != 0 or not (1 < key.g < key.p) or pow(key.g, key.q, key.p) != 1:
        return False
    if not (0 < key.y < key.p):
        return False
    if hasattr(key, 'x'):
        if not (0 < key.x < key.q) or pow(key.g, key.x, key.p) != key.y:
            return False
    return True

def test_valid_multiple_digest_or_verify(self):
    def perform_digest_test(cipher):
        first_mac = cipher.digest()
        for _ in range(4):
            self.assertEqual(first_mac, cipher.digest())
        return first_mac

    def perform_verify_test(cipher, mac):
        for _ in range(5):
            cipher.verify(mac)

    cipher = ChaCha20_Poly1305.new(key=self.key_256, nonce=self.nonce_96)
    cipher.update(self.data_128)
    first_mac = perform_digest_test(cipher)

    cipher = ChaCha20_Poly1305.new(key=self.key_256, nonce=self.nonce_96)
    cipher.update(self.data_128)
    perform_verify_test(cipher, first_mac)

def _decodeLen(self, s):
    """Decode DER length octets from a file."""
    length = s.read_byte()

    if length <= 127:
        return length

    encoded_length = s.read(length & 0x7F)
    if bord(encoded_length[0]) == 0:
        raise ValueError("Invalid DER: length has leading zero")

    length = bytes_to_long(encoded_length)
    if length <= 127:
        raise ValueError("Invalid DER: length in long form but smaller than 128")

    return length

def _right_encode(x):
    """Right encode function as defined in NIST SP 800-185"""
    assert 0 <= x < (1 << 2040)
    num = (x.bit_length() + 7) // 8 or 1
    return long_to_bytes(x) + bchr(num)

