def _try_import_tests(module_name, test_name, base_class):
    try:
        module = __import__(module_name, fromlist=[''])
        class TestClass(base_class):
            def setUp(self):
                self.Integer = getattr(module, module_name.split('.')[-1])
        return list_test_cases(TestClass)
    except (ImportError, OSError) as e:
        _handle_import_error(test_name, e)
        return []

def _handle_import_error(test_name, error):
    if sys.platform == "win32" and test_name == 'GMP':
        sys.stdout.write("Skipping GMP tests on Windows\n")
    else:
        sys.stdout.write(f"Skipping {test_name} tests ({error})\n")

def inverse(u, v):
    """The inverse of :data:`u` *mod* :data:`v`."""
    if v <= 0:
        raise ValueError("Modulus must be a positive integer")
    return pow(u, -1, v)

def __eq__(self, other):
    return (
        isinstance(other, EccKey) and
        other.has_private() == self.has_private() and
        other.pointQ == self.pointQ
    )

def fail_if_divisible_by(self, small_prime):
    """Raise an exception if the small prime is a divisor."""

    def is_divisible(mpz_value, divisor):
        return _gmp.mpz_divisible_ui_p(mpz_value, c_ulong(divisor)) if is_native_int(divisor) else _gmp.mpz_divisible_p(mpz_value, divisor._mpz_p)

    if is_native_int(small_prime) and 0 < small_prime < 65536:
        if is_divisible(self._mpz_p, small_prime):
            raise ValueError("The value is composite")
    else:
        small_prime = IntegerGMP(small_prime)
        if is_divisible(self._mpz_p, small_prime):
            raise ValueError("The value is composite")

def _create_base_cipher(dict_parameters):
    """This method instantiates and returns a smart pointer to
    a low-level base cipher. It will absorb named parameters in
    the process."""

    key = dict_parameters.pop("key", None)
    if key is None:
        raise TypeError("Missing 'key' parameter")

    if len(key) not in key_size:
        raise ValueError(f"Incorrect Blowfish key length ({len(key)} bytes)")

    void_p = VoidPointer()
    result = _raw_blowfish_lib.Blowfish_start_operation(
        c_uint8_ptr(key), c_size_t(len(key)), void_p.address_of()
    )
    if result:
        raise ValueError(f"Error {result:X} while instantiating the Blowfish cipher")

    return SmartPointer(void_p.get(), _raw_blowfish_lib.Blowfish_stop_operation)

def test_encrypt(self, tv):
    self._id = f"Wycheproof Encrypt EAX Test #{tv.id}"

    if not self._initialize_cipher(tv):
        return

    ct, tag = self._encrypt_and_digest(tv)
    if tv.valid:
        self._validate_encryption(tv, ct, tag)

def _initialize_cipher(self, tv):
    try:
        self.cipher = AES.new(tv.key, AES.MODE_EAX, tv.iv, mac_len=tv.tag_size)
        return True
    except ValueError as e:
        assert len(tv.iv) == 0 and "Nonce cannot be empty" in str(e)
        return False

def _encrypt_and_digest(self, tv):
    self.cipher.update(tv.aad)
    return self.cipher.encrypt_and_digest(tv.msg)

def _validate_encryption(self, tv, ct, tag):
    self.assertEqual(ct, tv.ct)
    self.assertEqual(tag, tv.tag)
    self.warn(tv)

def W(cipher: ModuleType, plaintext: Union[bytes, bytearray]) -> bytes:
    S = [plaintext[i:i+8] for i in range(0, len(plaintext), 8)]
    A, R = bytes(S[0]), deque(S[1:])
    s = 6 * (len(S) - 1)

    for t in range(1, s + 1):
        t_64 = struct.pack('>Q', t)
        ct = cipher.encrypt(A + R.popleft())
        A = strxor(ct[:8], t_64)
        R.append(ct[8:])

    return A + b''.join(R)

def _import_rfc5915_der(encoded, passphrase, curve_oid=None):
    ec_private_key = DerSequence().decode(encoded, nr_elements=(2, 3, 4))
    if ec_private_key[0] != 1:
        raise ValueError("Incorrect ECC private key version")

    scalar_bytes = DerOctetString().decode(ec_private_key[1]).payload
    next_element = 2

    curve_oid = _decode_parameters(ec_private_key, next_element, curve_oid)
    curve_name, curve = _find_curve(curve_oid)

    modulus_bytes = curve.p.size_in_bytes()
    if len(scalar_bytes) != modulus_bytes:
        raise ValueError("Private key is too small")

    point_x, point_y = _decode_public_key(ec_private_key, next_element, curve_oid)

    d = Integer.from_bytes(scalar_bytes)
    return construct(curve=curve_name, d=d, point_x=point_x, point_y=point_y)

def _decode_parameters(ec_private_key, next_element, curve_oid):
    if next_element < len(ec_private_key):
        try:
            parameters = DerObjectId(explicit=0).decode(ec_private_key[next_element]).value
            if curve_oid is not None and parameters != curve_oid:
                raise ValueError("Curve mismatch")
            return parameters
        except ValueError:
            pass
    if curve_oid is None:
        raise ValueError("No curve found")
    return curve_oid

def _find_curve(curve_oid):
    for curve_name, curve in _curves.items():
        if curve.oid == curve_oid:
            return curve_name, curve
    raise UnsupportedEccFeature("Unsupported ECC curve (OID: %s)" % curve_oid)

def _decode_public_key(ec_private_key, next_element, curve_oid):
    if next_element < len(ec_private_key):
        try:
            public_key_enc = DerBitString(explicit=1).decode(ec_private_key[next_element]).value
            public_key = _import_public_der(public_key_enc, curve_oid=curve_oid)
            return public_key.pointQ.x, public_key.pointQ.y
        except ValueError:
            pass
    return None, None

def _get_cell_value(self, cell) -> Scalar | NaTType:
    from odf.namespaces import OFFICENS

    cell_str = str(cell)
    if cell_str == "#N/A":
        return np.nan

    cell_type = cell.attributes.get((OFFICENS, "value-type"))
    if cell_type is None:
        return self.empty_value

    cell_value = cell.attributes.get((OFFICENS, "value"))
    if cell_type == "boolean":
        return cell_str == "TRUE"
    elif cell_type == "float":
        cell_value = float(cell_value)
        return int(cell_value) if int(cell_value) == cell_value else cell_value
    elif cell_type in {"percentage", "currency"}:
        return float(cell_value)
    elif cell_type == "string":
        return self._get_cell_string_value(cell)
    elif cell_type == "date":
        return pd.Timestamp(cell.attributes.get((OFFICENS, "date-value")))
    elif cell_type == "time":
        return cast("Scalar", pd.Timestamp(cell_str).time())
    else:
        self.close()
        raise ValueError(f"Unrecognized type {cell_type}")

def _take_new_index(
    obj: DataFrame | Series,
    indexer: npt.NDArray[np.intp],
    new_index: Index,
) -> DataFrame | Series:
    if isinstance(obj, ABCSeries):
        return obj._constructor(
            algos.take_nd(obj._values, indexer), index=new_index, name=obj.name
        )
    if isinstance(obj, ABCDataFrame):
        new_mgr = obj._mgr.reindex_indexer(new_axis=new_index, indexer=indexer, axis=1)
        return obj._constructor_from_mgr(new_mgr, axes=new_mgr.axes)
    raise ValueError("'obj' should be either a Series or a DataFrame")

def construct_from_string(cls, string: str) -> Self:
    if not isinstance(string, str):
        raise TypeError(f"'construct_from_string' expects a string, got {type(string)}")

    if not isinstance(cls.name, str):
        raise TypeError(
            f"Cannot construct a '{cls.__name__}' from a string because it "
            "does not define a string 'name' attribute. ExtensionDtype "
            "subclasses must set a class-level `name`."
        )

    if string != cls.name:
        raise TypeError(f"Cannot construct a '{cls.__name__}' from '{string}'")

    return cls()

def replace_regex(
    values: ArrayLike, rx: re.Pattern, value, mask: npt.NDArray[np.bool_] | None
) -> None:
    """
    Parameters
    ----------
    values : ArrayLike
        Object dtype.
    rx : re.Pattern
    value : Any
    mask : np.ndarray[bool], optional

    Notes
    -----
    Alters values in-place.
    """

    def re_replacer(s):
        if not is_re(rx) or not isinstance(s, str):
            return s
        if isna(value) or not isinstance(value, str):
            return value if rx.search(s) is not None else s
        return rx.sub(value, s)

    f = np.vectorize(re_replacer, otypes=[np.object_])

    if mask is None:
        values[:] = f(values)
    else:
        if values.ndim != mask.ndim:
            mask = np.broadcast_to(mask, values.shape)
        values[mask] = f(values[mask])

def _select_font_family(self, font_names: Sequence[str]) -> int | None:
    for name in font_names:
        family = self.FAMILY_MAP.get(name)
        if family:
            return family
    return None

def get_sheet_data(
    self, sheet: CalamineSheet, file_rows_needed: int | None = None
) -> list[list[Scalar | NaTType | time]]:
    def _convert_cell(value: _CellValue) -> Scalar | NaTType | time:
        if isinstance(value, float) and value.is_integer():
            return int(value)
        if isinstance(value, (datetime, timedelta, time)):
            return value
        if isinstance(value, date):
            return datetime(value.year, value.month, value.day)
        return value

    rows: list[list[_CellValue]] = sheet.to_python(
        skip_empty_area=False, nrows=file_rows_needed
    )
    return [[_convert_cell(cell) for cell in row] for row in rows]

def _is_uniform_join_units(join_units: list[JoinUnit]) -> bool:
    """
    Check if the join units consist of blocks of uniform type that can
    be concatenated using Block.concat_same_type instead of the generic
    _concatenate_join_units (which uses `concat_compat`).

    """
    first_block = join_units[0].block

    if first_block.dtype.kind == "V":
        return False

    def is_same_type(ju: JoinUnit) -> bool:
        return type(ju.block) is type(first_block)

    def is_dtype_compatible(ju: JoinUnit) -> bool:
        return (
            ju.block.dtype == first_block.dtype
            or ju.block.dtype.kind in "iub"
        )

    def is_na_compatible(ju: JoinUnit) -> bool:
        return not ju.is_na or ju.block.is_extension

    return (
        all(is_same_type(ju) for ju in join_units)
        and all(is_dtype_compatible(ju) for ju in join_units)
        and all(is_na_compatible(ju) for ju in join_units)
    )

def available_cpu_count() -> int | None:
    """
    Number of CPUs the process may actually use, or None if unconstrained.
    """
    limits = []

    def add_affinity_limit():
        if hasattr(os, "sched_getaffinity"):
            try:
                limits.append(len(os.sched_getaffinity(0)))
            except OSError:
                pass

    def add_cgroup_quota_limit():
        quota = _cgroup_cpu_quota()
        if quota is not None:
            limits.append(max(1, int(quota)))

    add_affinity_limit()
    add_cgroup_quota_limit()

    return min(limits) if limits else None

def _validate(self) -> None:
    super()._validate()

    if self._is_rolling_on_datetimelike_index():
        self._validate_datetimelike_monotonic()
        self._set_win_freq_i8()
        self._validate_min_periods()
        self._validate_step()
    elif isinstance(self.window, BaseIndexer):
        pass
    elif not is_integer(self.window) or self.window < 0:
        raise ValueError("window must be an integer 0 or greater")

def _is_rolling_on_datetimelike_index(self) -> bool:
    return (
        self.obj.empty
        or isinstance(self._on, (DatetimeIndex, TimedeltaIndex, PeriodIndex))
        or (isinstance(self._on.dtype, ArrowDtype) and self._on.dtype.kind in "mM")
    ) and isinstance(self.window, (str, BaseOffset, timedelta))

def _set_win_freq_i8(self) -> None:
    try:
        freq = to_offset(self.window)
    except (TypeError, ValueError) as err:
        raise ValueError(
            f"passed window {self.window} is not "
            "compatible with a datetimelike index"
        ) from err

    if isinstance(self._on, PeriodIndex):
        self._win_freq_i8 = freq.nanos / (self._on.freq.nanos / self._on.freq.n)
    else:
        unit = self._get_unit()
        self._win_freq_i8 = Timedelta(freq.nanos).as_unit(unit)._value

def _get_unit(self) -> str:
    try:
        return cast("TimeUnit", dtype_to_unit(self._on.dtype))
    except TypeError:
        return "ns"

def _validate_min_periods(self) -> None:
    if self.min_periods is None:
        self.min_periods = 1

def _validate_step(self) -> None:
    if self.step is not None:
        raise NotImplementedError(
            "step is not supported with frequency windows"
        )

def _initialize_columns(self, cols: Iterable[Hashable] | None) -> npt.NDArray[np.object_]:
    if self.has_mi_columns and cols is not None:
        raise TypeError("cannot specify cols with a MultiIndex on the columns")

    if cols is not None:
        cols = cols._get_values_for_csv(**self._number_format) if isinstance(cols, ABCIndex) else list(cols)
        self.obj = self.obj.loc[:, cols]

    return self.obj.columns._get_values_for_csv(**self._number_format)

def allows_duplicate_labels(self, value: bool) -> None:
    if self._obj() is None:
        raise ValueError("This flag's object has been deleted.")

    self._allows_duplicate_labels = bool(value)

    if not self._allows_duplicate_labels:
        for ax in self._obj().axes:
            ax._maybe_check_unique()

def asfreq(
    obj: NDFrameT,
    freq,
    method=None,
    how=None,
    normalize: bool = False,
    fill_value=None,
) -> NDFrameT:
    """
    Utility frequency conversion method for Series/DataFrame.

    See :meth:`pandas.NDFrame.asfreq` for full documentation.
    """
    if isinstance(obj.index, PeriodIndex):
        return _asfreq_period_index(obj, freq, how)

    if len(obj.index) == 0:
        return _asfreq_empty_index(obj, freq)

    return _asfreq_datetime_index(obj, freq, method, normalize, fill_value)


def _asfreq_period_index(obj, freq, how):
    if how is None:
        how = "E"
    if isinstance(freq, BaseOffset) and hasattr(freq, "_period_dtype_code"):
        freq = PeriodDtype(freq)._freqstr
    new_obj = obj.copy()
    new_obj.index = obj.index.asfreq(freq, how=how)
    return new_obj


def _asfreq_empty_index(obj, freq):
    new_obj = obj.copy()
    new_obj.index = _asfreq_compat(obj.index, freq)
    return new_obj


def _asfreq_datetime_index(obj, freq, method, normalize, fill_value):
    unit: TimeUnit = "ns"
    if isinstance(obj.index, DatetimeIndex):
        unit = obj.index.unit
    dti = date_range(obj.index.min(), obj.index.max(), freq=freq, unit=unit)
    dti.name = obj.index.name
    new_obj = obj.reindex(dti, method=method, fill_value=fill_value)
    if normalize:
        new_obj.index = new_obj.index.normalize()
    return new_obj

def _parse_latex_table_wrapping(table_styles: CSSStyles, caption: str | None) -> bool:
    """
    Indicate whether LaTeX {tabular} should be wrapped with a {table} environment.

    Parses the `table_styles` and detects any selectors which must be included outside
    of {tabular}, i.e. indicating that wrapping must occur, and therefore return True,
    or if a caption exists and requires similar.
    """
    IGNORED_WRAPPERS = {"toprule", "midrule", "bottomrule", "column_format"}

    if caption is not None:
        return True

    if table_styles is None:
        return False

    return any(d["selector"] not in IGNORED_WRAPPERS for d in table_styles)

def agg(self) -> DataFrame | Series | None:
    """
    Provide an implementation for the aggregators.

    Returns
    -------
    Result of aggregation, or None if agg cannot be performed by
    this method.
    """
    func = self.func

    if isinstance(func, str):
        return self.apply_str()

    if is_dict_like(func):
        return self.agg_dict_like()

    if is_list_like(func):
        return self.agg_list_like()

    return None

def _reduce(
    self,
    name: str,
    *,
    skipna: bool = True,
    keepdims: bool = False,
    axis: AxisInt | None = 0,
    **kwargs,
):
    nv.validate_minmax_axis(axis, self.ndim)

    if self.dtype.na_value is np.nan and name in ["any", "all"]:
        arr = self._get_boolean_array(skipna)
        result = ArrowExtensionArray(arr)._reduce(
            name, skipna=skipna, keepdims=keepdims, **kwargs
        )
        return self._handle_keepdims(result, keepdims)

    if name in ("count", "min", "max", "sum", "argmin", "argmax"):
        result = self._reduce_calc(name, skipna=skipna, keepdims=keepdims, **kwargs)
        return self._process_result(name, result)

    raise TypeError(f"Cannot perform reduction '{name}' with string dtype")

def _get_boolean_array(self, skipna):
    if not skipna:
        nas = pc.is_null(self._pa_array)
        return pc.or_kleene(nas, pc.not_equal(self._pa_array, ""))
    return pc.not_equal(self._pa_array, "")

def _handle_keepdims(self, result, keepdims):
    if keepdims:
        return result.astype(np.bool_)
    return result

def _process_result(self, name, result):
    if name in ("argmin", "argmax") and isinstance(result, pa.Array):
        return self._convert_int_result(result)
    if isinstance(result, pa.Array):
        return type(self)(result, dtype=self.dtype)
    return result

def _agg_py_fallback(self, how: str, values: ArrayLike, ndim: int, alt: Callable) -> ArrayLike:
    """
    Fallback to pure-python aggregation if _cython_operation raises
    NotImplementedError.
    """
    assert alt is not None

    ser = self._create_series(values)
    res_values = self._aggregate_series(ser, how, alt)
    res_values = self._adjust_result_dtype(res_values, ser.dtype)

    return ensure_block_shape(res_values, ndim=ndim)

def _create_series(self, values: ArrayLike) -> Series:
    if values.ndim == 1:
        return Series(values, copy=False)
    df = DataFrame(values.T, dtype=values.dtype)
    assert df.shape[1] == 1
    return df.iloc[:, 0]

def _aggregate_series(self, ser: Series, how: str, alt: Callable) -> ArrayLike:
    try:
        return self._grouper.agg_series(ser, alt)
    except Exception as err:
        msg = f"agg function failed [how->{how},dtype->{ser.dtype}]"
        raise type(err)(msg) from err

def _adjust_result_dtype(self, res_values: ArrayLike, dtype) -> ArrayLike:
    if dtype == object:
        return res_values.astype(object, copy=False)
    elif is_string_dtype(dtype):
        string_array_cls = dtype.construct_array_type()  # type: ignore[union-attr]
        return string_array_cls._from_sequence(res_values, dtype=dtype)
    return res_values

def _get_validity_buffer(self) -> tuple[Buffer, Any] | None:
    """
    Return the buffer containing the mask values indicating missing data and
    the buffer's associated dtype.
    Raises NoBufferPresent if null representation is not a bit or byte mask.
    """
    null, invalid = self.describe_null

    if isinstance(self._col.dtype, ArrowDtype):
        return self._get_arrow_dtype_buffer()

    if isinstance(self._col.dtype, BaseMaskedDtype):
        return self._get_base_masked_dtype_buffer()

    if self.dtype[0] == DtypeKind.STRING:
        return self._get_string_dtype_buffer(invalid)

    raise self._no_validity_buffer_exception(null)

def _get_arrow_dtype_buffer(self) -> tuple[Buffer, Any] | None:
    arr = self._col.array._pa_array.chunks[0]  # type: ignore[attr-defined]
    dtype = (DtypeKind.BOOL, 1, ArrowCTypes.BOOL, Endianness.NATIVE)
    if arr.buffers()[0] is None:
        return None
    buffer = PandasBufferPyarrow(arr.buffers()[0], length=len(arr))
    return buffer, dtype

def _get_base_masked_dtype_buffer(self) -> tuple[Buffer, Any]:
    mask = self._col.array._mask  # type: ignore[attr-defined]
    buffer = PandasBuffer(mask)
    dtype = (DtypeKind.BOOL, 8, ArrowCTypes.BOOL, Endianness.NATIVE)
    return buffer, dtype

def _get_string_dtype_buffer(self, invalid: Any) -> tuple[Buffer, Any]:
    buf = self._col.to_numpy()
    valid = invalid == 0
    mask = np.array([valid if isinstance(obj, str) else not valid for obj in buf], dtype=np.bool_)
    buffer = PandasBuffer(mask)
    dtype = (DtypeKind.BOOL, 8, ArrowCTypes.BOOL, Endianness.NATIVE)
    return buffer, dtype

def _no_validity_buffer_exception(self, null: Any) -> NoBufferPresent:
    try:
        msg = f"{_NO_VALIDITY_BUFFER[null]} so does not have a separate mask"
    except KeyError as err:
        raise NotImplementedError("See self.describe_null") from err
    raise NoBufferPresent(msg)

def _from_sequence(cls, scalars, *, dtype: Dtype | None = None, copy: bool = False) -> Self:
    dtype = _determine_dtype(dtype)
    na_value = dtype.na_value

    if isinstance(scalars, BaseMaskedArray):
        result = _handle_masked_array(scalars, na_value, copy)
    else:
        result = _handle_non_masked_array(scalars, na_value, copy)

    new_string_array = cls.__new__(cls)
    NDArrayBacked.__init__(new_string_array, result, dtype)
    return new_string_array

def _determine_dtype(dtype):
    if dtype and not (isinstance(dtype, str) and dtype == "string"):
        dtype = pandas_dtype(dtype)
        assert isinstance(dtype, StringDtype) and dtype.storage == "python"
    elif using_string_dtype():
        dtype = StringDtype(storage="python", na_value=np.nan)
    else:
        dtype = StringDtype(storage="python")
    return dtype

def _handle_masked_array(scalars, na_value, copy):
    na_values = scalars._mask
    result = scalars._data
    result = lib.ensure_string_array(result, copy=copy, convert_na_value=False, skipna=False)
    result[na_values] = na_value
    return result

def _handle_non_masked_array(scalars, na_value, copy):
    if lib.is_pyarrow_array(scalars):
        scalars = np.array(scalars)
    return lib.ensure_string_array(scalars, na_value=na_value, copy=copy)

def _set_value(self, label, value, takeable: bool = False) -> None:
    """
    Quickly set single value at passed label.

    If label is not contained, a new object is created with the label
    placed at the end of the result index.

    Parameters
    ----------
    label : object
        Partial indexing with MultiIndex not allowed.
    value : object
        Scalar value.
    takeable : interpret the index as indexers, default False
    """
    if takeable:
        loc = label
    else:
        loc = self._get_location(label)
        if loc is None:
            self.loc[label] = value
            return

    self._set_values(loc, value)

def _get_location(self, label):
    try:
        return self.index.get_loc(label)
    except KeyError:
        return None
    except InvalidIndexError as ii_err:
        raise InvalidIndexError(
            ".at-based indexing can only have scalar indexers; use .loc instead"
        ) from ii_err

def _not_in(x, y):
    """
    Compute the vectorized membership of ``x not in y`` if possible,
    otherwise use Python.
    """
    try:
        return ~x.isin(y)
    except AttributeError:
        if is_list_like(x):
            try:
                return ~y.isin(x)
            except AttributeError:
                return x not in y
        return x not in y

def _unstack_frame(
    obj: DataFrame, level, fill_value=None, sort: bool = True
) -> DataFrame:
    assert isinstance(obj.index, MultiIndex)  # checked by caller
    unstacker = _Unstacker(
        obj.index, level=level, constructor=obj._constructor, sort=sort
    )

    if obj._can_fast_transpose:
        return unstacker.get_result(
            obj, value_columns=obj.columns, fill_value=fill_value
        )

    mgr = obj._mgr.unstack(unstacker, fill_value=fill_value)
    return obj._constructor_from_mgr(mgr, axes=mgr.axes)

def astype_is_view(dtype: DtypeObj, new_dtype: DtypeObj) -> bool:
    """Checks if astype avoided copying the data."""

    def is_equal_itemsize():
        return hasattr(dtype, "itemsize") and hasattr(new_dtype, "itemsize") and dtype.itemsize == new_dtype.itemsize

    def is_equal_numpy_dtype():
        return numpy_dtype == new_numpy_dtype

    def get_numpy_dtype(d):
        return getattr(d, "numpy_dtype", d if isinstance(d, np.dtype) else None)

    if dtype.kind in "iufb" and dtype.kind == new_dtype.kind and is_equal_itemsize():
        return True

    if isinstance(dtype, np.dtype) and not isinstance(new_dtype, np.dtype):
        new_dtype, dtype = dtype, new_dtype

    if dtype == new_dtype:
        return True

    if isinstance(dtype, np.dtype) and isinstance(new_dtype, np.dtype):
        return is_object_dtype(dtype) and is_string_dtype(new_dtype)

    if is_string_dtype(dtype) and is_string_dtype(new_dtype):
        from pandas.core.arrays.string_ import StringDtype
        if isinstance(dtype, StringDtype) and dtype.storage == "pyarrow" and new_dtype == "object":
            return False
        return True

    if is_object_dtype(dtype) and new_dtype.kind == "O":
        return True

    if dtype.kind in "mM" and new_dtype.kind in "mM":
        dtype = getattr(dtype, "numpy_dtype", dtype)
        new_dtype = getattr(new_dtype, "numpy_dtype", new_dtype)
        return getattr(dtype, "unit", None) == getattr(new_dtype, "unit", None)

    if new_dtype == object and isinstance(dtype, (DatetimeTZDtype, PeriodDtype, IntervalDtype)):
        return False

    if isinstance(dtype, CategoricalDtype) and not isinstance(new_dtype, CategoricalDtype):
        return False

    numpy_dtype = get_numpy_dtype(dtype)
    new_numpy_dtype = get_numpy_dtype(new_dtype)

    if numpy_dtype is not None and new_numpy_dtype is not None:
        return is_equal_numpy_dtype()

    return True

def astype_float_to_int_nansafe(
    values: np.ndarray, dtype: np.dtype, copy: bool
) -> np.ndarray:
    """
    astype with a check preventing converting NaN to a meaningless integer value.
    """
    if not np.isfinite(values).all():
        raise IntCastingNaNError(
            "Cannot convert non-finite values (NA or inf) to integer. "
            "Replace or remove non-finite values or cast to an integer type "
            "that supports these values (e.g. 'Int64')"
        )

    if dtype.kind == "u" and not (values >= 0).all():
        raise ValueError(f"Cannot losslessly cast from {values.dtype} to {dtype}")

    with warnings.catch_warnings():
        warnings.filterwarnings("ignore", category=RuntimeWarning)
        return values.astype(dtype, copy=copy)

def _finalize_columns_and_data(
    content: np.ndarray,  # ndim == 2
    columns: Index | None,
    dtype: DtypeObj | None,
) -> tuple[list[ArrayLike], Index]:
    """
    Ensure we have valid columns, cast object dtypes if possible.
    """
    contents = list(content.T)

    columns = _get_validated_columns(contents, columns)

    if contents and contents[0].dtype == np.object_:
        contents = convert_object_array(contents, dtype=dtype)

    return contents, columns

def _get_validated_columns(contents, columns):
    try:
        return _validate_or_indexify_columns(contents, columns)
    except AssertionError as err:
        raise ValueError(err) from err

def obj_to_write(self) -> NDFrame | Mapping[IndexLabel, Any]:
    if self.index or self.orient != "split":
        return self.obj
    return {"name": self.obj.name, "data": self.obj.values}

def _from_sequence(cls, data, *, dtype=None, copy: bool = False) -> Self:
    if dtype:
        dtype = _validate_td64_dtype(dtype)

    data, copy = dtl.ensure_arraylike_for_datetimelike(
        data, copy, cls_name="TimedeltaArray"
    )

    unit = _determine_unit(data, dtype)

    data = sequence_to_td64ns(data, copy=copy, unit=unit)

    if dtype is not None:
        data = astype_overflowsafe(data, dtype=dtype, copy=False)

    return cls._simple_new(data, dtype=data.dtype)

def _determine_unit(data, dtype):
    if dtype is None:
        return None

    if data.dtype == object:
        apply_unit = not contains_str(data)
    else:
        apply_unit = data.dtype.kind in "iuf"

    return np.datetime_data(dtype)[0] if apply_unit else None

def _validate_color_args(self, color, colormap):
    def warn_color_colormap():
        warnings.warn(
            "'color' and 'colormap' cannot be used simultaneously. Using 'color'",
            stacklevel=find_stack_level(),
        )

    if color is lib.no_default:
        if "colors" in self.kwds and colormap is not None:
            warn_color_colormap()
        return None

    if self.nseries == 1 and color is not None and not is_list_like(color):
        color = [color]

    if isinstance(color, tuple) and self.nseries == 1 and len(color) in (3, 4):
        color = [color]

    if colormap is not None:
        warn_color_colormap()

    if self.style is not None:
        styles = (
            [self.style[col] for col in self.columns if col in self.style]
            if isinstance(self.style, dict)
            else self.style if is_list_like(self.style)
            else [self.style]
        )
        if any(_color_in_style(s) for s in styles):
            raise ValueError(
                "Cannot pass 'style' string with a color symbol and "
                "'color' keyword argument. Please use one or the "
                "other or pass 'style' without a color symbol"
            )

    return color

def _border_style(self, style: str | None, width: str | None, color: str | None) -> str | None:
    if width is None and style is None:
        return None if color is None else "none"

    if style in ("none", "hidden"):
        return "none"

    width_name = self._get_width_name(width)
    if width_name is None:
        return "none"

    if style in (None, "groove", "ridge", "inset", "outset", "solid"):
        return width_name

    if style == "double":
        return "double"

    if style == "dotted":
        return "dotted" if width_name in ("hair", "thin") else "mediumDashDotDot"

    if style == "dashed":
        return "dashed" if width_name in ("hair", "thin") else "mediumDashed"

    if style in self.BORDER_STYLE_MAP:
        return self.BORDER_STYLE_MAP[style]

    warnings.warn(
        f"Unhandled border style format: {style!r}",
        CSSWarning,
        stacklevel=find_stack_level(),
    )
    return "none"

def _box_pa_scalar(cls, value, pa_type: pa.DataType | None = None) -> pa.Scalar:
    """
    Box value into a pyarrow Scalar.

    Parameters
    ----------
    value : any
    pa_type : pa.DataType | None

    Returns
    -------
    pa.Scalar
    """
    if isinstance(value, pa.Scalar):
        return value

    if isna(value) and not (lib.is_float(value) and not is_nan_na()):
        return pa.scalar(None, type=pa_type)

    if (
        pa_type is not None
        and pa.types.is_timestamp(pa_type)
        and isinstance(value, datetime)
        and (value.tzinfo is None) != (pa_type.tz is None)
    ):
        raise pa.ArrowTypeError(
            "Cannot mix tz-aware and tz-naive datetime-like values"
        )

    if isinstance(value, Timedelta) and (
        pa_type is None or pa.types.is_duration(pa_type)
    ):
        pa_type = pa_type or pa.duration(value.unit)
        if value.unit != pa_type.unit:
            value = value.as_unit(pa_type.unit)
        value = value._value
    elif isinstance(value, Timestamp) and (
        pa_type is None or pa.types.is_timestamp(pa_type)
    ):
        pa_type = pa_type or pa.timestamp(value.unit, tz=value.tz)
        if value.unit != pa_type.unit:
            value = value.as_unit(pa_type.unit)
        value = value._value

    pa_scalar = pa.scalar(value, type=pa_type)

    if pa_type is not None and pa_scalar.type != pa_type:
        if (
            pa_scalar.is_valid
            and pa.types.is_timestamp(pa_scalar.type)
            and pa.types.is_timestamp(pa_type)
            and (pa_scalar.type.tz is None) != (pa_type.tz is None)
        ):
            raise pa.ArrowTypeError(
                "Cannot mix tz-aware and tz-naive datetime-like values"
            )
        pa_scalar = pa_scalar.cast(pa_type)

    return pa_scalar

def generate_filter_op(self, invert: bool = False):
    should_invert = (self.op == "!=" and not invert) or (self.op == "==" and invert)
    return lambda axis, vals: ~axis.isin(vals) if should_invert else axis.isin(vals)

def names(self):
    """
    Get the names in an expression.
    """
    terms = [self.terms] if is_term(self.terms) else com.flatten(self.terms)
    return frozenset(term.name for term in terms)

def __getstate__(self) -> dict[str, Any]:
    return {
        "_mgr": self._mgr,
        "_typ": self._typ,
        "_metadata": self._metadata,
        "attrs": self.attrs,
        "_flags": {k: self.flags[k] for k in self.flags._keys},
        **{k: getattr(self, k, None) for k in self._metadata},
    }

def __from_arrow__(self, array: pyarrow.Array | pyarrow.ChunkedArray) -> BaseStringArray:
    """
    Construct StringArray from pyarrow Array/ChunkedArray.
    """
    if self.storage == "pyarrow":
        return self._from_arrow_pyarrow(array)
    else:
        return self._from_arrow_numpy(array)

def _from_arrow_pyarrow(self, array: pyarrow.Array | pyarrow.ChunkedArray) -> BaseStringArray:
    from pandas.core.arrays.string_arrow import ArrowStringArray, _check_pyarrow_available

    _check_pyarrow_available()

    if not pa.types.is_large_string(array.type):
        array = pc.cast(array, pa.large_string())

    return ArrowStringArray(array, dtype=self)

def _from_arrow_numpy(self, array: pyarrow.Array | pyarrow.ChunkedArray) -> BaseStringArray:
    import pyarrow

    chunks = [array] if isinstance(array, pyarrow.Array) else array.chunks
    results = [ensure_string_array(arr.to_numpy(zero_copy_only=False), na_value=self.na_value) for arr in chunks]

    arr = np.concatenate(results) if chunks else np.array([], dtype=object)

    # Bypass validation inside StringArray constructor, see GH#47781
    new_string_array = StringArray.__new__(StringArray)
    NDArrayBacked.__init__(new_string_array, arr, self)
    return new_string_array

def value_counts(
    self,
    normalize: bool = False,
    sort: bool = True,
    ascending: bool = False,
    bins: int | None = None,
    dropna: bool = True,
) -> Series:
    from pandas import Series

    if bins is not None:
        return super().value_counts(
            normalize=normalize,
            sort=sort,
            ascending=ascending,
            bins=bins,
            dropna=dropna,
        )

    count = len(self)
    data = np.ones(count, dtype=np.float64 if normalize else np.int64)
    if normalize:
        data /= count

    name = "proportion" if normalize else "count"
    return Series(data, index=self.copy(), name=name)

def _safe_cast(cls, values: np.ndarray, dtype: np.dtype, copy: bool) -> np.ndarray:
    """
    Safely cast the values to the given dtype.

    "safe" in this context means the casting is lossless. e.g. if 'values'
    has a floating dtype, each value must be an integer.
    """
    if np.can_cast(values.dtype, dtype, casting="safe"):
        return values.astype(dtype, copy=copy)

    casted = values.astype(dtype, copy=copy)
    if np.array_equal(casted, values):
        return casted

    raise TypeError(
        f"cannot safely cast non-equivalent {values.dtype} to {np.dtype(dtype)}"
    )

def pandasSQL_builder(
    con,
    schema: str | None = None,
    need_transaction: bool = False,
) -> PandasSQL:
    """
    Convenience function to return the correct PandasSQL subclass based on the
    provided parameters. Also creates a sqlalchemy connection and transaction
    if necessary.
    """
    import sqlite3

    if isinstance(con, sqlite3.Connection) or con is None:
        return SQLiteDatabase(con)

    sqlalchemy = import_optional_dependency("sqlalchemy", errors="ignore")
    adbc = import_optional_dependency("adbc_driver_manager.dbapi", errors="ignore")

    if isinstance(con, str):
        if sqlalchemy is None:
            raise ImportError(
                "Using a URI string requires 'sqlalchemy' version "
                f"'{VERSIONS['sqlalchemy']}' or newer."
            )
        return SQLDatabase(con, schema, need_transaction)

    if sqlalchemy and isinstance(con, sqlalchemy.engine.Connectable):
        return SQLDatabase(con, schema, need_transaction)

    if adbc and isinstance(con, adbc.Connection):
        return ADBCDatabase(con)

    warnings.warn(
        "pandas only supports SQLAlchemy connectable (engine/connection) or "
        "database string URI or sqlite3 DBAPI2 connection. Other DBAPI2 "
        "objects are not tested. Please consider using SQLAlchemy.",
        UserWarning,
        stacklevel=find_stack_level(),
    )
    return SQLiteDatabase(con)

def isin(self, values: ArrayLike) -> npt.NDArray[np.bool_]:
    if isinstance(values, (BaseStringArray, ExtensionArray)) and is_string_dtype(values.dtype):
        values = values.astype(self.dtype, copy=False)
    else:
        values = np.array(
            [val for val in values if isinstance(val, str) or isna(val)],
            dtype=object,
        )
        if not len(values):
            return np.zeros(self.shape, dtype=bool)
        values = self._from_sequence(values, dtype=self.dtype)

    return isin(np.asarray(self), np.asarray(values))

def __setattr__(self, key: str, value) -> None:
    if getattr(self, "__frozen", False):
        if key != "_cache" and key not in type(self).__dict__ and getattr(self, key, None) is None:
            raise AttributeError(f"You cannot add any new attribute '{key}'")
    object.__setattr__(self, key, value)

def is_unique(self) -> bool:
    """
    Return True if the IntervalIndex contains unique elements, else False.
    """
    if self.isna().sum() > 1:
        return False

    if self.left.is_unique or self.right.is_unique:
        return True

    seen_pairs = set()
    for idx in np.where(self.left.duplicated(keep=False))[0]:
        pair = (self.left[idx], self.right[idx])
        if pair in seen_pairs:
            return False
        seen_pairs.add(pair)

    return True

def _str_map(self, f, na_value=lib.no_default, dtype: NpDtype | None = None, convert: bool = True):
    """
    Map a callable over valid elements of the array.

    Parameters
    ----------
    f : Callable
        A function to call on each non-NA element.
    na_value : Scalar, optional
        The value to set for NA values. Might also be used for the
        fill value if the callable `f` raises an exception.
        This defaults to ``self.dtype.na_value`` which is ``np.nan``
        for object-dtype and Categorical and ``pd.NA`` for StringArray.
    dtype : Dtype, optional
        The dtype of the result array.
    convert : bool, default True
        Whether to call `maybe_convert_objects` on the resulting ndarray
    """
    dtype = dtype or np.dtype("object")
    na_value = na_value if na_value is not lib.no_default else self.dtype.na_value  # type: ignore[attr-defined]

    if not len(self):
        return np.array([], dtype=dtype)

    arr = np.asarray(self, dtype=object)
    mask = isna(arr)
    map_convert = convert and not np.all(mask)

    try:
        result = lib.map_infer_mask(arr, f, mask.view(np.uint8), convert=map_convert)
    except (TypeError, AttributeError) as err:
        if len(err.args) >= 1 and re.search(r"((takes)|(missing)) (?(2)from \d+ to )?\d+ (?(3)required )positional arguments?", err.args[0]):
            raise err

        def g(x):
            try:
                return f(x)
            except (TypeError, AttributeError):
                return na_value

        return self._str_map(g, na_value=na_value, dtype=dtype)

    if isinstance(result, np.ndarray):
        if na_value is not np.nan:
            np.putmask(result, mask, na_value)
            if convert and result.dtype == object:
                result = lib.maybe_convert_objects(result)
    return result

def prune(self, klass):
    if self.op != "~":
        raise NotImplementedError("UnaryOp only support invert type ops")

    operand = self.operand.prune(klass)

    if operand is None:
        return None

    is_condition_op = issubclass(klass, ConditionBinOp)
    is_filter_op = issubclass(klass, FilterBinOp)

    if (is_condition_op and operand.condition is not None) or (is_filter_op and operand.filter is not None):
        return operand.invert()

    return None

def _select_data(self) -> DataFrame:
    """Select columns to be described."""
    if self.include is None and self.exclude is None:
        data = self.obj.select_dtypes(include=[np.number, "datetime"])
        return data if len(data.columns) > 0 else self.obj

    if isinstance(self.include, str) and self.include == "all":
        if self.exclude is not None:
            raise ValueError("exclude must be None when include is 'all'")
        return self.obj

    data = self.obj.select_dtypes(include=self.include, exclude=self.exclude)
    if len(data.columns) == 0:
        raise ValueError("No columns match the specified include or exclude data types")

    return data

def __init__(
    self,
    table: Table,
    where=None,
    start: int | None = None,
    stop: int | None = None,
) -> None:
    self.table = table
    self.where = where
    self.start = start
    self.stop = stop
    self.condition = None
    self.filter = None
    self.terms = None
    self.coordinates = None

    if is_list_like(where):
        self._process_list_like_where(where)
    else:
        self._process_non_list_like_where(where)

def _process_list_like_where(self, where):
    inferred = lib.infer_dtype(where, skipna=False)
    if inferred in ("integer", "boolean"):
        where = np.asarray(where)
        start, stop = _resolve_row_window(self.start, self.stop, self.table.nrows)
        if where.dtype == np.bool_:
            self.coordinates = np.arange(start, stop)[where]
        elif issubclass(where.dtype.type, np.integer):
            self._validate_integer_where(where, start, stop)

def _validate_integer_where(self, where, start, stop):
    invalid = where[(where < start) | (where >= stop)]
    if len(invalid):
        raise ValueError(
            "where must have index locations >= start and < stop, "
            f"but got {invalid[:5].tolist()}"
            f"{' ...' if len(invalid) > 5 else ''} "
            f"with start={start} and stop={stop}"
        )
    self.coordinates = where

def _process_non_list_like_where(self, where):
    self.terms = self.generate(where)
    if self.terms is not None:
        self.condition, self.filter = self.terms.evaluate()

def _is_monotonic_decreasing(self) -> bool:
    pa_array = self._pa_array
    if pa_array.null_count > 0 or len(pa_array) <= 1:
        return pa_array.null_count == 0
    try:
        return pc.all(pc.less_equal(pa_array[1:], pa_array[:-1])).as_py()
    except pa.ArrowNotImplementedError:
        return False

def _validate_listlike(self, value):
    value = extract_array(value, extract_numpy=True)

    if isinstance(value, Categorical):
        self._validate_categorical(value)
        value = self._encode_with_my_categories(value)
        return value._codes

    return self._validate_non_categorical(value)

def _validate_categorical(self, value):
    if self.dtype != value.dtype:
        raise TypeError(
            "Cannot set a Categorical with another, "
            "without identical categories"
        )

def _validate_non_categorical(self, value):
    from pandas import Index

    to_add = Index._with_infer(value, tupleize_cols=False, copy=False).difference(
        self.categories
    )

    if len(to_add) and not isna(to_add).all():
        raise TypeError(
            "Cannot setitem on a Categorical with a new "
            "category, set the categories first"
        )

    codes = self.categories.get_indexer(value)
    return codes.astype(self._ndarray.dtype, copy=False)

def map_array(
    arr: ArrayLike,
    mapper,
    na_action: Literal["ignore"] | None = None,
) -> np.ndarray | ExtensionArray | Index:
    """
    Map values using an input mapping or function.

    Parameters
    ----------
    mapper : function, dict, or Series
        Mapping correspondence.
    na_action : {None, 'ignore'}, default None
        If 'ignore', propagate NA values, without passing them to the
        mapping correspondence.

    Returns
    -------
    Union[ndarray, Index, ExtensionArray]
        The output of the mapping function applied to the array.
        If the function returns a tuple with more than one element
        a MultiIndex will be returned.
    """
    from pandas import Index, Series

    if na_action not in (None, "ignore"):
        raise ValueError(f"na_action must either be 'ignore' or None, {na_action} was passed")

    if is_dict_like(mapper):
        mapper = _prepare_mapper(mapper)

    if isinstance(mapper, ABCSeries):
        return _map_series(arr, mapper, na_action)

    if not len(arr):
        return arr.copy()

    values = arr.astype(object, copy=False)
    return lib.map_infer(values, mapper) if na_action is None else lib.map_infer_mask(values, mapper, mask=isna(values).view(np.uint8))


def _prepare_mapper(mapper):
    from pandas import Series, Index

    if isinstance(mapper, dict) and hasattr(mapper, "__missing__"):
        dict_with_default = mapper
        return lambda x: dict_with_default[np.nan if isinstance(x, float) and np.isnan(x) else x]

    if len(mapper) == 0:
        return Series(mapper, dtype=np.float64)

    if isinstance(mapper, dict):
        return Series(mapper.values(), index=Index(mapper.keys(), tupleize_cols=False))

    return Series(mapper)


def _map_series(arr, mapper, na_action):
    if na_action == "ignore":
        mapper = mapper[mapper.index.notna()]

    indexer = mapper.index.get_indexer(arr)
    return take_nd(mapper._values, indexer)

def __init__(
    self,
    storage: str | None = None,
    na_value: libmissing.NAType | float = libmissing.NA,
) -> None:
    storage = self._infer_storage(storage)
    self._validate_storage(storage)
    self._na_value = self._validate_na_value(na_value)
    self._storage = cast("str", storage)

def _infer_storage(self, storage: str | None) -> str:
    if storage is None:
        storage = config["mode"]["string_storage"]
        if storage == "auto":
            storage = "pyarrow" if HAS_PYARROW else "python"
    return storage

def _validate_storage(self, storage: str) -> None:
    if storage not in {"python", "pyarrow"}:
        raise ValueError(
            f"Storage must be 'python' or 'pyarrow'. Got {storage} instead."
        )
    if storage == "pyarrow" and not HAS_PYARROW:
        raise ImportError(
            f"pyarrow>={PYARROW_MIN_VERSION} is required for PyArrow "
            "backed StringArray."
        )

def _validate_na_value(self, na_value: libmissing.NAType | float) -> libmissing.NAType | float:
    if isinstance(na_value, float) and np.isnan(na_value):
        return np.nan
    if na_value is not libmissing.NA:
        raise ValueError(f"'na_value' must be np.nan or pd.NA, got {na_value}")
    return na_value

def _get_layout(
    nplots: int,
    layout: tuple[int, int] | None = None,
    layout_type: str = "box",
) -> tuple[int, int]:
    if layout:
        if not isinstance(layout, (tuple, list)) or len(layout) != 2:
            raise ValueError("Layout must be a tuple of (rows, columns)")

        nrows, ncols = layout
        if nrows == -1 and ncols > 0:
            nrows = ceil(nplots / ncols)
        elif ncols == -1 and nrows > 0:
            ncols = ceil(nplots / nrows)
        elif ncols <= 0 and nrows <= 0:
            raise ValueError("At least one dimension of layout must be positive")

        if nrows * ncols < nplots:
            raise ValueError(
                f"Layout of {nrows}x{ncols} must be larger than required size {nplots}"
            )

        return nrows, ncols

    layout_options = {
        "single": (1, 1),
        "horizontal": (1, nplots),
        "vertical": (nplots, 1),
    }
    if layout_type in layout_options:
        return layout_options[layout_type]

    layouts = {1: (1, 1), 2: (1, 2), 3: (2, 2), 4: (2, 2)}
    if nplots in layouts:
        return layouts[nplots]

    k = 1
    while k**2 < nplots:
        k += 1

    return (k, k - 1) if (k - 1) * k >= nplots else (k, k)

def __getattr__(self, attr: str):
    if attr in self._internal_names_set or attr in self.obj:
        return object.__getattribute__(self, attr)
    if attr in self._attributes:
        return getattr(self._timegrouper, attr)
    return object.__getattribute__(self, attr)

def get_period_offset(ax: Axes, index: Index) -> BaseOffset | None:
    """
    Resolve the period frequency to plot `index` with on `ax`, or None.
    """
    freq = _get_index_freq(index) or _get_ax_freq(ax)
    if not freq:
        return None

    freq_str = _get_period_alias(freq)
    if not freq_str:
        return None

    return to_offset(OFFSET_TO_PERIOD_FREQSTR.get(freq_str, freq_str), is_period=True)

def _get_prev_label(label):
    dtype = getattr(label, "dtype", type(label))
    if isinstance(label, (Timestamp, Timedelta)):
        dtype = "datetime64[ns]"
    dtype = pandas_dtype(dtype)

    if lib.is_np_dtype(dtype, "mM") or isinstance(dtype, DatetimeTZDtype):
        return label - np.timedelta64(1, "ns")
    if is_integer_dtype(dtype):
        return label - 1
    if is_float_dtype(dtype):
        return np.nextafter(label, -np.inf)

    raise TypeError(f"cannot determine next label for type {type(label)!r}")

def __rtruediv__(self, other):
    op = roperator.rtruediv

    if is_scalar(other):
        return self._scalar_divlike_op(other, op)

    other = self._cast_divlike_op(other)

    if lib.is_np_dtype(other.dtype, "m"):
        return self._vector_divlike_op(other, op)

    if is_object_dtype(other.dtype):
        return np.array([other[n] / self[n] for n in range(len(self))])

    return NotImplemented

def astype(self, dtype, copy: bool = True):
    dtype = pandas_dtype(dtype)

    if dtype == self.dtype:
        return self.copy() if copy else self

    arr = self._ndarray.copy()
    mask = self.isna()

    if isinstance(dtype, IntegerDtype):
        arr[mask] = 0
        values = arr.astype(dtype.numpy_dtype)
        return IntegerArray(values, mask, copy=False)

    if isinstance(dtype, FloatingDtype):
        arr_ea = self.copy()
        arr_ea[mask] = "0"
        values = arr_ea.astype(dtype.numpy_dtype)
        return FloatingArray(values, mask, copy=False)

    if isinstance(dtype, ExtensionDtype):
        return ExtensionArray.astype(self, dtype, copy)

    if np.issubdtype(dtype, np.floating):
        arr[mask] = 0
        values = arr.astype(dtype)
        values[mask] = np.nan
        return values

    return super().astype(dtype, copy)

def _filter_usecols(usecols, names: SequenceT) -> SequenceT | list[Hashable]:
    usecols = evaluate_callable_usecols(usecols, names)
    if usecols is None or len(names) == len(usecols):
        return names
    return [name for i, name in enumerate(names) if i in usecols or name in usecols]

def _get_next_label(label):
    dtype = getattr(label, "dtype", type(label))
    if isinstance(label, (Timestamp, Timedelta)):
        dtype = "datetime64[ns]"
    dtype = pandas_dtype(dtype)

    if lib.is_np_dtype(dtype, "mM") or isinstance(dtype, DatetimeTZDtype):
        increment = np.timedelta64(1, "ns")
    elif is_integer_dtype(dtype):
        increment = 1
    elif is_float_dtype(dtype):
        increment = np.nextafter(label, np.inf) - label
    else:
        raise TypeError(f"cannot determine next label for type {type(label)!r}")

    return label + increment

def create_block_manager_from_blocks(
    blocks: list[Block],
    axes: list[Index],
    consolidate: bool = True,
    verify_integrity: bool = True,
) -> BlockManager:
    try:
        mgr = BlockManager(blocks, axes, verify_integrity=verify_integrity)
    except ValueError as err:
        arrays = [blk.values for blk in blocks]
        tot_items = sum(arr.shape[0] for arr in arrays)
        raise_construction_error(tot_items, arrays[0].shape[1:], axes, err)

    if consolidate:
        mgr._consolidate_inplace()

    return mgr

def validate(self, other) -> None:
    """validate against an existing table"""
    if other is None:
        return

    if other.table_type != self.table_type:
        raise TypeError(
            "incompatible table_type with existing "
            f"[{other.table_type} - {self.table_type}]"
        )

    def compare_axes(sv, ov, c):
        for i, sax in enumerate(sv):  # type: ignore[arg-type]
            oax = ov[i]  # type: ignore[index]
            if sax != oax:
                if c == "values_axes" and sax.kind != oax.kind:
                    raise ValueError(
                        f"Cannot serialize the column [{oax.values[0]}] "
                        f"because its data contents are not [{sax.kind}] "
                        f"but [{oax.kind}] object dtype"
                    )
                raise ValueError(
                    f"invalid combination of [{c}] on appending data "
                    f"[{sax}] vs current table [{oax}]"
                )

    for c in ["index_axes", "non_index_axes", "values_axes"]:
        sv = getattr(self, c, None)
        ov = getattr(other, c, None)
        if sv != ov:
            compare_axes(sv, ov, c)
            raise Exception(
                f"invalid combination of [{c}] on appending data [{sv}] vs "
                f"current table [{ov}]"
            )

def private_function_across_module(file_obj: IO[str]) -> Iterable[tuple[int, str]]:
    """
    Checking that a private function is not used across modules.
    Parameters
    ----------
    file_obj : IO
        File-like object containing the Python code to validate.
    Yields
    ------
    line_number : int
        Line number of the private function that is used across modules.
    msg : str
        Explanation of the error.
    """
    contents = file_obj.read()
    tree = ast.parse(contents)

    imported_modules = {
        module.name if module.asname is None else module.asname
        for node in ast.walk(tree)
        if isinstance(node, (ast.Import, ast.ImportFrom))
        for module in node.names
    }

    for node in ast.walk(tree):
        if isinstance(node, ast.Call):
            module_name, function_name = get_module_and_function_name(node)
            if module_name and function_name and is_private_function_violation(module_name, function_name, imported_modules):
                yield (node.lineno, f"Private function '{module_name}.{function_name}'")

def get_module_and_function_name(node: ast.Call) -> tuple[str, str]:
    try:
        return node.func.value.id, node.func.attr
    except AttributeError:
        return None, None

def is_private_function_violation(module_name: str, function_name: str, imported_modules: set[str]) -> bool:
    if module_name[0].isupper():
        return False
    if function_name.startswith("__") and function_name.endswith("__"):
        return False
    if module_name + "." + function_name in PRIVATE_FUNCTIONS_ALLOWED:
        return False
    return module_name in imported_modules and function_name.startswith("_")

def mask_missing(arr: ArrayLike, value) -> npt.NDArray[np.bool_]:
    """
    Return a masking array of same size/shape as arr
    with entries equaling value set to True.

    Parameters
    ----------
    arr : ArrayLike
    value : scalar-like
        Caller has ensured `not is_list_like(value)` and that it can be held
        by `arr`.

    Returns
    -------
    np.ndarray[bool]
    """
    dtype, value = infer_dtype_from(value)

    if (
        isinstance(arr.dtype, (BaseMaskedDtype, ArrowDtype))
        and lib.is_float(value)
        and np.isnan(value)
        and not is_nan_na()
    ):
        return handle_special_float_case(arr)

    if isna(value):
        return isna(arr)

    return create_mask(arr, value, dtype)


def handle_special_float_case(arr):
    if arr.dtype.kind == "f":
        if isinstance(arr.dtype, BaseMaskedDtype):
            return np.isnan(arr._data) & ~arr.isna()  # type: ignore[attr-defined]
        else:
            import pyarrow.compute as pc
            return pc.is_nan(arr._pa_array).fill_null(False).to_numpy()  # type: ignore[attr-defined]
    elif arr.dtype.kind in "iu":
        return np.zeros(arr.shape, dtype=bool)


def create_mask(arr, value, dtype):
    mask = np.zeros(arr.shape, dtype=bool)
    if (
        is_numeric_dtype(arr.dtype)
        and not is_bool_dtype(arr.dtype)
        and lib.is_bool(value)
    ):
        return mask
    elif (
        is_bool_dtype(arr.dtype) and is_numeric_dtype(dtype) and not lib.is_bool(value)
    ):
        return mask
    elif is_numeric_dtype(arr.dtype) and isinstance(value, str):
        return mask
    elif is_object_dtype(arr.dtype):
        arr_mask = ~isna(arr)
        mask[arr_mask] = arr[arr_mask] == value
    else:
        new_mask = arr == value
        if not isinstance(new_mask, np.ndarray):
            new_mask = new_mask.to_numpy(dtype=bool, na_value=False)
        mask = new_mask
    return mask

def update_info(self, info) -> None:
    """
    set/update the info for this indexable with the key/value
    if there is a conflict raise/warn as needed
    """
    idx = info.setdefault(self.name, {})
    for key in self._info_fields:
        value = getattr(self, key, None)
        existing_value = idx.get(key)

        if value is None and existing_value is None:
            continue

        if key in idx and value is not None and existing_value != value:
            if key in ["freq", "index_name"]:
                ws = attribute_conflict_doc % (key, existing_value, value)
                warnings.warn(
                    ws, AttributeConflictWarning, stacklevel=find_stack_level()
                )
                idx[key] = None
                setattr(self, key, None)
            else:
                raise ValueError(
                    f"invalid info for [{self.name}] for [{key}], "
                    f"existing_value [{existing_value}] conflicts with "
                    f"new value [{value}]"
                )
        else:
            idx[key] = value

def _str_fullmatch(
    self,
    pat: str | re.Pattern,
    case: bool = True,
    flags: int = 0,
    na: Scalar | lib.NoDefault = lib.no_default,
):
    pat, case, flags = self._unwrap_re_pattern(pat, case, flags)

    if not pat.startswith("^"):
        pat = f"^({pat})$"
    elif not pat.endswith("$") or pat.endswith("\\$"):
        pat = f"^({pat[1:]})$"
    else:
        pat = f"^({pat[0:-1]})$"

    return ArrowStringArrayMixin._str_match(self, pat, case, flags, na)

def add_body_lines(self) -> None:
    for row in self.strrows:
        body_line = self.SPACING.join(
            self._ljust(col, gross_colwidth)
            for col, gross_colwidth in zip(row, self.gross_column_widths, strict=True)
        )
        self._lines.append(body_line)

def _convert_grouper(axis: Index, grouper):
    if isinstance(grouper, dict):
        return grouper.get

    if isinstance(grouper, Series):
        return grouper._values if grouper.index.equals(axis) else grouper.reindex(axis)._values

    if isinstance(grouper, MultiIndex):
        return grouper._values

    if isinstance(grouper, (list, tuple, Index, Categorical, np.ndarray)):
        if len(grouper) != len(axis):
            raise ValueError("Grouper and axis must be same length")
        return com.asarray_tuplesafe(grouper) if isinstance(grouper, (list, tuple)) else grouper

    return grouper

def __eq__(self, other):
    if not isinstance(other, pyarrow.BaseExtensionType):
        return NotImplemented
    return (
        type(self) == type(other)
        and self.subtype == other.subtype
        and self.closed == other.closed
    )

def _engine(
    self,
) -> libindex.IndexEngine | libindex.ExtensionEngine | libindex.MaskedIndexEngine:
    dtype = self.dtype
    target_values = self._get_engine_target()

    if isinstance(dtype, ArrowDtype) and dtype.kind in "Mm":
        return self._handle_arrow_dtype()

    if isinstance(target_values, ExtensionArray):
        return self._handle_extension_array(target_values)

    return self._handle_standard_types(target_values)

def _handle_arrow_dtype(self):
    import pyarrow as pa
    values = self._values
    pa_type = values._pa_array.type  # type: ignore[union-attr]

    if pa.types.is_timestamp(pa_type):
        target_values = values._to_datetimearray()  # type: ignore[union-attr]
        return libindex.DatetimeEngine(target_values._ndarray)
    elif pa.types.is_duration(pa_type):
        target_values = values._to_timedeltaarray()  # type: ignore[union-attr]
        return libindex.TimedeltaEngine(target_values._ndarray)

def _handle_extension_array(self, target_values):
    if isinstance(target_values, (BaseMaskedArray, ArrowExtensionArray)):
        return self._get_masked_engine(target_values)
    elif self._engine_type is libindex.ObjectEngine:
        return libindex.ExtensionEngine(target_values)

def _get_masked_engine(self, target_values):
    try:
        return _masked_engines[target_values.dtype.name](target_values)
    except KeyError:
        pass

def _handle_standard_types(self, target_values):
    if target_values.dtype == bool:
        return libindex.BoolEngine(target_values)  # type: ignore[arg-type]
    elif target_values.dtype == np.complex64:
        return libindex.Complex64Engine(target_values)  # type: ignore[arg-type]
    elif target_values.dtype == np.complex128:
        return libindex.Complex128Engine(target_values)  # type: ignore[arg-type]
    elif needs_i8_conversion(self.dtype):
        target_values = self._data._ndarray  # type: ignore[union-attr]
    elif isinstance(self.dtype, StringDtype):
        return libindex.StringObjectEngine(target_values, self.dtype.na_value)

    return self._engine_type(target_values)  # type: ignore[arg-type]

def _read_pyarrow(self) -> DataFrame:
    """
    Read JSON using the pyarrow engine.
    """
    pyarrow_json = import_optional_dependency("pyarrow.json")
    options = self._get_parse_options() if isinstance(self.dtype, dict) else None
    pa_table = pyarrow_json.read_json(self.data, parse_options=options)
    return arrow_table_to_pandas(pa_table, dtype_backend=self.dtype_backend)

def _get_parse_options(self):
    pa = import_optional_dependency("pyarrow")
    fields = [
        (field, pandas_dtype(dtype).pyarrow_dtype)
        for field, dtype in self.dtype.items()
        if isinstance(pandas_dtype(dtype), ArrowDtype)
    ]
    schema = pa.schema(fields)
    return pyarrow_json.ParseOptions(explicit_schema=schema, unexpected_field_behavior="infer")

def _reduce_calc(self, name: str, *, skipna: bool = True, keepdims: bool = False, **kwargs):
    pa_result = self._reduce_pyarrow(name, skipna=skipna, **kwargs)

    if keepdims:
        return self._wrap_with_keepdims(pa_result)

    if pc.is_null(pa_result).as_py():
        return self.dtype.na_value

    if isinstance(pa_result, pa.Scalar):
        return self._process_scalar_result(pa_result)

    return pa_result

def _wrap_with_keepdims(self, pa_result):
    if isinstance(pa_result, pa.Scalar):
        return pa.array([pa_result.as_py()], type=pa_result.type)
    return pa.array(
        [pa_result],
        type=to_pyarrow_type(infer_dtype_from_scalar(pa_result)[0]),
    )

def _process_scalar_result(self, pa_result):
    result = pa_result.as_py()
    pa_type = pa_result.type
    if pa.types.is_duration(pa_type) and pa_type.unit != "ns":
        return Timedelta(result).as_unit(pa_type.unit)
    if pa.types.is_timestamp(pa_type) and pa_type.unit != "ns":
        return Timestamp(result).as_unit(pa_type.unit)
    return result

def _info_repr(self) -> bool:
    """
    True if the repr should show the info view.
    """
    return (
        config["display"]["large_repr"] == "info"
        and not self._repr_fits_horizontal_()
        and not self._repr_fits_vertical_()
    )

def _get_cython_function(cls, kind: str, how: str, dtype: np.dtype, is_numeric: bool):
    dtype_str = dtype.name
    ftype = cls._CYTHON_FUNCTIONS[kind][how]
    f = ftype if callable(ftype) else getattr(libgroupby, ftype)

    if is_numeric:
        return f

    if dtype == np.dtype(object):
        if how in ["median", "cumprod"]:
            raise NotImplementedError(
                f"function is not implemented for this dtype: [how->{how},dtype->{dtype_str}]"
            )
        if how in ["std", "sem", "idxmin", "idxmax"]:
            return f
        if how in ["skew", "kurt"]:
            return f
        if "object" not in f.__signatures__:
            raise NotImplementedError(
                f"function is not implemented for this dtype: [how->{how},dtype->{dtype_str}]"
            )
        return f

    raise NotImplementedError(
        "This should not be reached. Please report a bug at github.com/pandas-dev/pandas/",
        dtype,
    )

def _mask_datetimelike_result(
    result: np.ndarray | np.datetime64 | np.timedelta64,
    axis: AxisInt | None,
    mask: npt.NDArray[np.bool_],
    orig_values: np.ndarray,
) -> np.ndarray | np.datetime64 | np.timedelta64 | NaTType:
    if isinstance(result, np.ndarray):
        result = result.astype("i8").view(orig_values.dtype)
        if mask.any(axis=axis):
            result[mask.any(axis=axis)] = iNaT
    elif mask.any():
        return np.int64(iNaT).view(orig_values.dtype)
    return result

def _generate_marginal_results_without_values(
    table: DataFrame,
    data: DataFrame,
    rows,
    cols,
    aggfunc,
    kwargs,
    observed: bool,
    margins_name: Hashable = "All",
    dropna: bool = True,
):
    def _all_key():
        return (margins_name,) + ("",) * (len(cols) - 1) if len(cols) > 1 else margins_name

    def _calculate_margin():
        if len(data.index) > 0:
            gb = Series(np.nan, index=data.index).groupby(
                [data[row] for row in rows], observed=observed, dropna=dropna
            )
            return gb.agg(aggfunc, **kwargs)
        else:
            from pandas import Categorical
            gb = Series(np.nan, index=data.index).groupby(
                Categorical(np.zeros(0), categories=[0]), observed=False
            )
            agged = gb.agg(aggfunc, **kwargs)
            assert isinstance(agged, Series) and len(agged) == 1
            return agged.iloc[0]

    margin_keys = []
    if len(cols) > 0:
        if len(rows) > 0:
            margin = _calculate_margin()
        else:
            margin = data.groupby(level=0, observed=observed, dropna=dropna).agg(
                aggfunc, **kwargs
            )
        all_key = _all_key()
        table[all_key] = margin
        margin_keys.append(all_key)
        result = table
    else:
        result = table
        margin_keys = table.columns

    if len(result.columns) > 0:
        row_margin = (
            Series(np.nan, index=data.index)
            .groupby([data[col] for col in cols], observed=observed, dropna=dropna)
            .agg(aggfunc, **kwargs)
        )
    else:
        row_margin = Series(np.nan, index=result.columns)

    return result, margin_keys, row_margin

def _str_split(
    self,
    pat: str | re.Pattern | None = None,
    n=-1,
    expand: bool = False,
    regex: bool | None = None,
):
    def get_split_function(pat, n):
        if isinstance(pat, re.Pattern):
            return lambda x: pat.split(x, maxsplit=n if n != -1 else 0)
        return lambda x: x.split(pat, n)

    if pat is None:
        n = -1 if n is None or n == 0 else n
        f = lambda x: x.split(pat, n)
    else:
        if regex is True or isinstance(pat, re.Pattern):
            pat = re.compile(pat)
        elif regex is None and len(pat) > 1:
            pat = re.compile(pat)

        n = -1 if n is None or n == 0 else n
        f = get_split_function(pat, n)

    return self._str_map(f, dtype=object)

def get_numeric_data(self) -> Self:
    if all(blk.is_numeric for blk in self.blocks):
        return self
    return self._combine([blk for blk in self.blocks if blk.is_numeric])

def apply_series_numba(self):
    if self._is_parallel_apply() or not self._has_unique_index_and_columns():
        raise NotImplementedError(self._get_error_message())
    self.validate_values_for_numba()
    return self.apply_with_numba(), self.result_index

def _is_parallel_apply(self):
    return self.engine_kwargs.get("parallel", False)

def _has_unique_index_and_columns(self):
    return self.obj.index.is_unique and self.columns.is_unique

def _get_error_message(self):
    if self._is_parallel_apply():
        return "Parallel apply is not supported when raw=False and engine='numba'"
    return "The index/columns must be unique when raw=False and engine='numba'"

def _set_grouper(
    self, obj: NDFrameT, sort: bool = False, *, gpr_index: Index | None = None
) -> tuple[NDFrameT, Index, npt.NDArray[np.intp] | None]:
    """
    given an object and the specifications, setup the internal grouper
    for this particular specification

    Parameters
    ----------
    obj : Series or DataFrame
    sort : bool, default False
        whether the resulting grouper should be sorted
    gpr_index : Index or None, default None

    Returns
    -------
    NDFrame
    Index
    np.ndarray[np.intp] | None
    """
    assert obj is not None

    if self.key is not None and self.level is not None:
        raise ValueError("The Grouper cannot specify both a key and a level!")

    if self._grouper is None:
        self._grouper = gpr_index
        self._indexer = self._indexer_deprecated

    ax = self._get_axis(obj, gpr_index)
    indexer = self._sort_axis(ax, obj, sort)

    return obj, ax, indexer

def _get_axis(self, obj: NDFrameT, gpr_index: Index | None) -> Index:
    if self.key is not None:
        return self._get_key_axis(obj, gpr_index)
    return self._get_level_axis(obj)

def _get_key_axis(self, obj: NDFrameT, gpr_index: Index | None) -> Index:
    key = self.key
    if getattr(gpr_index, "name", None) == key and isinstance(obj, Series):
        assert self._grouper is not None
        if self._indexer is not None:
            reverse_indexer = self._indexer.argsort()
            unsorted_ax = self._grouper.take(reverse_indexer)
            return unsorted_ax.take(obj.index)  # type: ignore[arg-type]
        return self._grouper.take(obj.index)  # type: ignore[arg-type]
    if key not in obj._info_axis:
        raise KeyError(f"The grouper name {key} is not found")
    return Index(obj[key], name=key)

def _get_level_axis(self, obj: NDFrameT) -> Index:
    ax = obj.index
    if self.level is not None:
        level = self.level
        if isinstance(ax, MultiIndex):
            level = ax._get_level_number(level)
            return Index(ax._get_level_values(level), name=ax.names[level])
        if level not in (0, ax.name):
            raise ValueError(f"The level {level} is not valid")
    return ax

def _sort_axis(self, ax: Index, obj: NDFrameT, sort: bool) -> npt.NDArray[np.intp] | None:
    if (self.sort or sort) and not ax.is_monotonic_increasing:
        indexer = self._indexer_deprecated = ax.array.argsort(
            kind="mergesort", na_position="first"
        )
        ax = ax.take(indexer)
        obj = obj.take(indexer, axis=0)
        return indexer
    return None

def astype(self, dtype, copy: bool = True):
    """
    Cast to an ExtensionArray or NumPy array with dtype 'dtype'.

    Parameters
    ----------
    dtype : str or dtype
        Typecode or data-type to which the array is cast.

    copy : bool, default True
        Whether to copy the data, even if not necessary. If False,
        a copy is made only if the old dtype does not match the
        new dtype.

    Returns
    -------
    array : ExtensionArray or ndarray
        ExtensionArray or NumPy ndarray with 'dtype' for its dtype.
    """
    from pandas import Index

    if dtype is not None:
        dtype = pandas_dtype(dtype)

    if not isinstance(dtype, IntervalDtype):
        return self._astype_super(dtype, copy)

    if dtype == self.dtype:
        return self.copy() if copy else self

    if is_float_dtype(self.dtype.subtype) and needs_i8_conversion(dtype.subtype):
        raise TypeError(
            f"Cannot convert {self.dtype} to {dtype}; subtypes are incompatible"
        )

    return self._astype_interval(dtype)

def _astype_super(self, dtype, copy):
    try:
        return super().astype(dtype, copy=copy)
    except (TypeError, ValueError) as err:
        raise TypeError(f"Cannot cast {type(self).__name__} to dtype {dtype}") from err

def _astype_interval(self, dtype):
    from pandas import Index

    try:
        new_left = Index(self._left, copy=False).astype(dtype.subtype)
        new_right = Index(self._right, copy=False).astype(dtype.subtype)
    except IntCastingNaNError:
        raise
    except (TypeError, ValueError) as err:
        raise TypeError(
            f"Cannot convert {self.dtype} to {dtype}; subtypes are incompatible"
        ) from err

    return self._shallow_copy(new_left, new_right)

def __rmatmul__(self, other) -> DataFrame:
    """
    Matrix multiplication using binary `@` operator.
    """
    try:
        return self.T.dot(np.transpose(other)).T
    except ValueError as err:
        if "shape mismatch" in str(err):
            msg = f"shapes {np.shape(other)} and {self.shape} not aligned"
            raise ValueError(msg) from err
        raise

def validate_attr(self, append) -> None:
    """validate that we have the same order as the existing & same dtype"""
    if not append:
        return

    existing_fields = getattr(self.attrs, self.kind_attr, None)
    if existing_fields is not None and existing_fields != list(self.values):
        raise ValueError("appended items do not match existing items in table!")

    existing_dtype = getattr(self.attrs, self.dtype_attr, None)
    if existing_dtype is not None and existing_dtype != self.dtype:
        raise ValueError("appended items dtype do not match existing items dtype in table!")

def _header_line(self):
    if self.header is not None:
        return None

    try:
        return self._buffered_line()
    except StopIteration as err:
        if not self.names:
            raise EmptyDataError("No columns to parse from file") from err
        return self.names[:]

def _falsey_value(self):
    kind_falsey_map = {
        "f": 0.0,
        "i": 0,
        "u": 0
    }
    return kind_falsey_map.get(self.kind, False)

def _join_empty(
    self, other: Index, how: JoinHow, sort: bool
) -> tuple[Index, npt.NDArray[np.intp] | None, npt.NDArray[np.intp] | None]:
    assert len(self) == 0 or len(other) == 0
    _validate_join_method(how)

    if len(other):
        how = cast("JoinHow", {"left": "right", "right": "left"}.get(how, how))
        return other._join_empty(self, how, sort)

    if how in ["left", "outer"]:
        if sort and not self.is_monotonic_increasing:
            lidx = self.argsort()
            join_index = self.take(lidx)
        else:
            lidx = None
            join_index = self._view()
        ridx = np.broadcast_to(np.intp(-1), len(join_index))
    else:
        join_index = other._view()
        lidx = np.array([], dtype=np.intp)
        ridx = None

    return join_index, lidx, ridx

def agg_or_apply_dict_like(self, op_name: Literal["agg", "apply"]) -> DataFrame | Series:
    from pandas.core.groupby.generic import DataFrameGroupBy, SeriesGroupBy

    assert op_name in ["agg", "apply"]

    if getattr(self.obj, "axis", 0) == 1:
        raise NotImplementedError("axis other than 0 is not supported")

    kwargs = self._prepare_kwargs(op_name)
    selected_obj = self.obj._selected_obj
    selection = self.obj._selection

    if isinstance(self.obj, (DataFrameGroupBy, SeriesGroupBy)):
        self._update_kwargs_with_engine(kwargs)

    with com.temp_setattr(self.obj, "as_index", True, condition=hasattr(self.obj, "as_index")):
        result_index, result_data = self.compute_dict_like(op_name, selected_obj, selection, kwargs)

    return self.wrap_results_dict_like(selected_obj, result_index, result_data)

def _prepare_kwargs(self, op_name: str) -> dict[str, Any]:
    kwargs = {}
    if op_name == "apply":
        kwargs["by_row"] = "_compat" if self.by_row else False
    return kwargs

def _update_kwargs_with_engine(self, kwargs: dict[str, Any]) -> None:
    engine = self.kwargs.get("engine")
    engine_kwargs = self.kwargs.get("engine_kwargs")
    kwargs.update({"engine": engine, "engine_kwargs": engine_kwargs})

def _get_required_dependencies_from_pixi_content(
    content: list[str], pixi_toml: dict[str, Any]
) -> dict[str, str]:
    required_deps = {}
    in_dependencies = False
    in_required_dependencies = False

    for line in map(str.strip, content):
        if not line:
            continue

        if line.startswith("["):
            in_dependencies = line == "[dependencies]"
            in_required_dependencies = False
            continue

        if not in_dependencies:
            continue

        if line.casefold() == "# required dependencies":
            in_required_dependencies = True
            continue

        if line.startswith("#"):
            in_required_dependencies = False
            continue

        if in_required_dependencies:
            package, _, _ = line.partition("=")
            package = package.strip()
            version = _get_version_from_pixi_spec(pixi_toml["dependencies"].get(package))
            if version and package not in EXCLUDE_DEPS:
                required_deps[package.casefold()] = version

    return required_deps

def _parse_latex_cell_styles(
    latex_styles: CSSList, display_value: str, convert_css: bool = False
) -> str:
    if convert_css:
        latex_styles = _parse_latex_css_conversion(latex_styles)

    wrap_formats = {
        "--wrap": "{{\\{command}{options} {display_value}}}",
        "--nowrap": "\\{command}{options} {display_value}",
        "--lwrap": "{{\\{command}{options}}} {display_value}",
        "--rwrap": "\\{command}{options}{{{display_value}}}",
        "--dwrap": "{{\\{command}{options}}}{{{display_value}}}",
    }

    for command, options in reversed(latex_styles):
        for wrap_type, format_str in wrap_formats.items():
            if wrap_type in options:
                stripped_options = _parse_latex_options_strip(value=options, arg=wrap_type)
                display_value = format_str.format(command=command, options=stripped_options, display_value=display_value)
                break
        else:
            display_value = f"\\{command}{options} {display_value}"

    return display_value

def __init__(
    self,
    path: FilePath | WriteExcelBuffer | ExcelWriter,
    engine: str | None = None,
    date_format: str | None = None,
    datetime_format: str | None = None,
    mode: str = "w",
    storage_options: StorageOptions | None = None,
    if_sheet_exists: ExcelWriterIfSheetExists | None = None,
    engine_kwargs: dict[str, Any] | None = None,
) -> None:
    if isinstance(path, str):
        ext = os.path.splitext(path)[-1]
        self.check_extension(ext)

    mode = self._prepare_mode(mode)
    self._validate_if_sheet_exists(if_sheet_exists, mode)

    self._handles = self._initialize_handles(path, mode, storage_options)
    self._cur_sheet = None

    self._date_format = date_format or "YYYY-MM-DD"
    self._datetime_format = datetime_format or "YYYY-MM-DD HH:MM:SS"
    self._mode = mode

def _prepare_mode(self, mode: str) -> str:
    if "b" not in mode:
        mode += "b"
    return mode.replace("a", "r+")

def _validate_if_sheet_exists(self, if_sheet_exists: ExcelWriterIfSheetExists | None, mode: str) -> None:
    valid_options = {None, "error", "new", "replace", "overlay"}
    if if_sheet_exists not in valid_options:
        raise ValueError(
            f"'{if_sheet_exists}' is not valid for if_sheet_exists. "
            "Valid options are 'error', 'new', 'replace' and 'overlay'."
        )
    if if_sheet_exists and "r+" not in mode:
        raise ValueError("if_sheet_exists is only valid in append mode (mode='a')")
    self._if_sheet_exists = if_sheet_exists or "error"

def _initialize_handles(self, path: FilePath | WriteExcelBuffer | ExcelWriter, mode: str, storage_options: StorageOptions | None) -> IOHandles:
    if isinstance(path, ExcelWriter):
        return IOHandles(cast("IO[bytes]", path), compression={"compression": None})
    return get_handle(path, mode, storage_options=storage_options, is_text=False)

def _index_col_should_parse_dates(self, name, position: int) -> bool:
    """
    Whether the index column with the given name/position should be parsed
    as dates. Unlike the other engines, the pyarrow path sets the index after
    reading, so parse_dates handling for index columns happens here.
    """
    if isinstance(self.parse_dates, bool):
        return self.parse_dates
    return any(item in self.parse_dates for item in (name, position))

def write_multi_index(self, key: str, index: MultiIndex) -> None:
    setattr(self.attrs, f"{key}_nlevels", index.nlevels)

    for i, (lev, level_codes, name) in enumerate(zip(index.levels, index.codes, index.names, strict=True)):
        self._write_level(key, i, lev, name)
        self._write_labels(key, i, level_codes)

def _write_level(self, key: str, i: int, lev, name) -> None:
    if isinstance(lev.dtype, ExtensionDtype) and not isinstance(lev.dtype, StringDtype):
        raise NotImplementedError("Saving a MultiIndex with an extension dtype is not supported.")

    level_key = f"{key}_level{i}"
    conv_level = _convert_index(level_key, lev, self.encoding, self.errors)
    self.write_array(level_key, conv_level.values)
    node = getattr(self.group, level_key)
    node._v_attrs.kind = conv_level.kind
    node._v_attrs.name = name

    if conv_level.kind == "string":
        node._v_attrs.nan_rep = conv_level.nan_rep or ""

    setattr(node._v_attrs, f"{key}_name{name}", name)

def _write_labels(self, key: str, i: int, level_codes) -> None:
    label_key = f"{key}_label{i}"
    self.write_array(label_key, level_codes)

def _public_names() -> frozenset[str]:
    """Return ``pandas.__all__``, read without importing pandas."""
    path = Path(__file__).parent.parent / "pandas" / "__init__.py"
    tree = ast.parse(path.read_text(encoding="utf-8"))

    def is_all_assign(node):
        return (
            isinstance(node, ast.Assign) and
            any(isinstance(target, ast.Name) and target.id == "__all__" for target in node.targets) and
            isinstance(node.value, ast.List)
        )

    def extract_constants(node):
        return frozenset(
            element.value
            for element in node.value.elts
            if isinstance(element, ast.Constant)
        )

    for node in tree.body:
        if is_all_assign(node):
            return extract_constants(node)

    raise AssertionError(f"could not find __all__ in {path}")

def _setitem_single_column(self, loc: int, value, plane_indexer) -> None:
    """
    Parameters
    ----------
    loc : int
        Indexer for column position
    plane_indexer : int, slice, listlike[int]
        The indexer we use for setitem along axis=0.
    """
    pi = plane_indexer

    if com.is_empty_slice(pi) or (is_array_like_deprecate_non_pandas(pi) and len(pi) == 0):
        return

    if com.is_null_slice(pi) or com.is_full_slice(pi, len(self.obj)):
        self._handle_full_setter(loc, value, pi)
    else:
        self._handle_partial_setter(loc, value)

def _handle_full_setter(self, loc, value, plane_indexer):
    try:
        self.obj._mgr.column_setitem(loc, plane_indexer, value, inplace_only=True)
    except (ValueError, TypeError, LossySetitemError) as exc:
        dtype = self.obj.dtypes.iloc[loc]
        if dtype not in (np.void, object) and not self.obj.empty:
            raise TypeError(f"Invalid value '{value}' for dtype '{dtype}'") from exc
        self.obj.isetitem(loc, value)

def _handle_partial_setter(self, loc, value):
    dtype = self.obj.dtypes.iloc[loc]
    if dtype == np.void:
        new_arr = construct_1d_array_from_inferred_fill_value(value, len(self.obj))
        self.obj.isetitem(loc, new_arr)
    self.obj._mgr.column_setitem(loc, plane_indexer, value)

def set_ticks_props(
    axes: Axes | Iterable[Axes],
    xlabelsize: int | None = None,
    xrot=None,
    ylabelsize: int | None = None,
    yrot=None,
):
    def set_tick_properties(ticklabels, size, rotation):
        if size is not None:
            mpl.artist.setp(ticklabels, fontsize=size)  # type: ignore[arg-type]
        if rotation is not None:
            mpl.artist.setp(ticklabels, rotation=rotation)  # type: ignore[arg-type]

    for ax in flatten_axes(axes):
        set_tick_properties(ax.get_xticklabels(), xlabelsize, xrot)
        set_tick_properties(ax.get_yticklabels(), ylabelsize, yrot)

    return axes

def _read_strls(self) -> None:
    self._path_or_buf.seek(self._seek_strls)
    self.GSO = {"0": ""}

    while self._path_or_buf.read(3) == b"GSO":
        v_o = self._read_uint64() if self._format_version == 117 else self._read_v_o()
        typ = self._read_uint8()
        length = self._read_uint32()
        va = self._path_or_buf.read(length)
        decoded_va = self._decode_va(va, typ)
        self.GSO[str(v_o)] = decoded_va

def _read_v_o(self) -> int:
    buf = self._path_or_buf.read(12)
    v_size = 2 if self._format_version == 118 else 3
    if self._byteorder == "<":
        buf = buf[0:v_size] + buf[4:(12 - v_size)]
    else:
        buf = buf[4 - v_size:4] + buf[(4 + v_size):]
    return struct.unpack(f"{self._byteorder}Q", buf)[0]

def _decode_va(self, va: bytes, typ: int) -> str:
    if typ == 130:
        return va[0:-1].decode(self._encoding)
    return str(va)

def _col_idx_to_axis_idx(self, col_idx: int) -> int:
    """Return the index of the axis where the column at col_idx should be plotted"""
    if isinstance(self.subplots, list):
        return next(
            (group_idx for group_idx, group in enumerate(self.subplots) if col_idx in group),
            col_idx
        )
    return col_idx

def _get_common_dtype(self, dtypes: list[DtypeObj]) -> DtypeObj | None:
    from pandas.core.dtypes.cast import find_common_type

    unwrapped_dtypes = [
        dtype.numpy_dtype if isinstance(dtype, BaseMaskedDtype) else dtype
        for dtype in dtypes
    ]
    new_dtype = find_common_type(unwrapped_dtypes)

    if isinstance(new_dtype, np.dtype):
        try:
            return type(self).from_numpy_dtype(new_dtype)
        except (KeyError, NotImplementedError):
            pass
    return None

def _set_endianness(endianness: str) -> str:
    endianness_map = {
        "<": "<",
        "little": "<",
        ">": ">",
        "big": ">"
    }
    try:
        return endianness_map[endianness.lower()]
    except KeyError:  # pragma: no cover
        raise ValueError(f"Endianness {endianness} not understood")

def is_nested_tuple(tup, labels) -> bool:
    """
    Returns
    -------
    bool
    """
    if isinstance(tup, tuple):
        return any(is_list_like(k) or isinstance(k, slice) for k in tup) and isinstance(labels, MultiIndex)
    return False

def _post_plot_logic(self, ax: Axes, data) -> None:
    # GH 45465: make sure that the boxplot doesn't ignore xlabel/ylabel
    if self.xlabel or self.ylabel:
        ax.set_xlabel(pprint_thing(self.xlabel) if self.xlabel else ax.get_xlabel())
        ax.set_ylabel(pprint_thing(self.ylabel) if self.ylabel else ax.get_ylabel())

def _validate_dtype(cls, dtype) -> DtypeObj | None:
    """validate the passed dtype"""
    if dtype is None:
        return None

    dtype = pandas_dtype(dtype)

    if dtype.kind == "V" and not isinstance(dtype, ExtensionDtype):
        raise NotImplementedError(
            "compound dtypes are not implemented "
            f"in the {cls.__name__} constructor"
        )

    return dtype

def _parse_temporal_dtype_string(cls, string: str) -> ArrowDtype:
    """
    Construct a temporal ArrowDtype from string.
    """
    head, tail = string.split("[", 1)

    if not tail.endswith("]"):
        raise ValueError("Invalid format: missing closing bracket")

    tail = tail[:-1]

    if head != "timestamp":
        raise NotImplementedError(f"Unsupported type: {string}")

    if "," not in tail:
        raise ValueError("Invalid format: missing comma in timestamp")

    unit, tz = map(str.strip, tail.split(",", 1))
    if tz.startswith("tz="):
        tz = tz[3:]

    pa_type = pa.timestamp(unit, tz=tz)
    return cls(pa_type)

def _get_column_weights(weights, i: int, y):
    if weights is None:
        return weights

    if np.ndim(weights) != 1 and np.shape(weights)[-1] != 1:
        try:
            weights = weights[:, i]
        except IndexError as err:
            raise ValueError(
                "weights must have the same shape as data, "
                "or be a single column"
            ) from err

    return weights[~isna(y)]

def _adjust_bins(self, bins: int | np.ndarray | list[np.ndarray]):
    if not is_integer(bins):
        return bins

    if self.by is None:
        return self._calculate_bins(self.data, bins)

    by_modified = unpack_single_str_list(self.by)
    grouped = self.data.groupby(by_modified)[self.columns]
    return [self._calculate_bins(group, bins) for _, group in grouped]

def _wrap_applied_output(
    self,
    data: DataFrame,
    values: list,
    not_indexed_same: bool = False,
    is_transform: bool = False,
):
    if not values:
        return self._handle_empty_values(data, is_transform)

    first_not_none = next(com.not_none(*values), None)

    if first_not_none is None:
        return self._handle_all_none_values(data)

    if isinstance(first_not_none, DataFrame):
        return self._concat_objects(
            values,
            not_indexed_same=not_indexed_same,
            is_transform=is_transform,
        )

    key_index = self._grouper.result_index if self.as_index else None

    if isinstance(first_not_none, (np.ndarray, Index)):
        return self._handle_array_like_values(values, key_index)

    if not isinstance(first_not_none, Series):
        return self._handle_scalar_values(values, key_index)

    return self._wrap_applied_output_series(
        values,
        not_indexed_same,
        first_not_none,
        key_index,
        is_transform,
    )

def _handle_empty_values(self, data, is_transform):
    if is_transform:
        res_index = data.index
    elif not self.group_keys or not self.as_index:
        res_index = None
    else:
        res_index = self._grouper.result_index

    result = self.obj._constructor(index=res_index, columns=data.columns)
    return result.astype(data.dtypes)

def _handle_all_none_values(self, data):
    result = self.obj._constructor(columns=data.columns)
    return result.astype(data.dtypes)

def _handle_array_like_values(self, values, key_index):
    name = self._selection if is_hashable(self._selection) else tuple(self._selection)
    return self.obj._constructor_sliced(values, index=key_index, name=name)

def _handle_scalar_values(self, values, key_index):
    if self.as_index:
        return self.obj._constructor_sliced(values, index=key_index)
    result = self.obj._constructor(values, columns=[self._selection])
    return self._insert_inaxis_grouper(result)

def argmax(self, axis: AxisInt = 0, skipna: bool = True):  # type: ignore[override]
    validate_bool_kwarg(skipna, "skipna")
    if not skipna and self._hasna:
        raise ValueError("Encountered an NA value with skipna=False")
    return nargminmax(self, "argmax", axis=axis)

def _get_out_dtype(self, dtype: np.dtype) -> np.dtype:
    how_to_dtype = {
        "rank": "float64",
        "idxmin": "intp",
        "idxmax": "intp"
    }

    if self.how in how_to_dtype:
        out_dtype = how_to_dtype[self.how]
    elif dtype.kind in "iufcb":
        out_dtype = f"{dtype.kind}{dtype.itemsize}"
    else:
        out_dtype = "object"

    return np.dtype(out_dtype)

def __arrow_array__(self, type=None):
    """
    Convert myself into a pyarrow Array.
    """
    import pyarrow
    from pandas.core.arrays.arrow.array import to_pyarrow_type
    from pandas.core.arrays.arrow.extension_types import ArrowIntervalType

    def _get_subtype():
        try:
            return to_pyarrow_type(self.dtype.subtype)
        except (TypeError, pyarrow.ArrowNotImplementedError) as err:
            raise TypeError(
                f"Conversion to arrow with subtype '{self.dtype.subtype}' "
                "is not supported"
            ) from err

    def _to_arrow(values) -> pyarrow.Array:
        if isinstance(self.dtype.subtype, np.dtype):
            return pyarrow.array(values, type=subtype, from_pandas=True)
        return pyarrow.array(values._ndarray, from_pandas=True).cast(subtype)

    def _create_storage_array():
        return pyarrow.StructArray.from_arrays(
            [_to_arrow(self._left), _to_arrow(self._right)],
            names=["left", "right"],
        )

    def _apply_null_bitmap(storage_array):
        mask = self.isna()
        if mask.any():
            null_bitmap = pyarrow.array(~mask).buffers()[1]
            return pyarrow.StructArray.from_buffers(
                storage_array.type,
                len(storage_array),
                [null_bitmap],
                children=[storage_array.field(0), storage_array.field(1)],
            )
        return storage_array

    def _validate_type(interval_type, storage_array):
        if type is not None:
            if type.equals(interval_type.storage_type):
                return storage_array
            if isinstance(type, ArrowIntervalType) and not type.equals(interval_type):
                raise TypeError(
                    "Not supported to convert IntervalArray to type with "
                    f"different 'subtype' ({self.dtype.subtype} vs {type.subtype}) "
                    f"and 'closed' ({self.closed} vs {type.closed}) attributes"
                )
            if not isinstance(type, ArrowIntervalType):
                raise TypeError(
                    f"Not supported to convert IntervalArray to '{type}' type"
                )
        return pyarrow.ExtensionArray.from_storage(interval_type, storage_array)

    subtype = _get_subtype()
    if subtype is None:
        raise TypeError(
            f"Conversion to arrow with subtype '{self.dtype.subtype}' "
            "is not supported"
        )

    interval_type = ArrowIntervalType(subtype, self.closed)
    storage_array = _create_storage_array()
    storage_array = _apply_null_bitmap(storage_array)
    return _validate_type(interval_type, storage_array)

def queryables(self) -> dict[str, Any]:
    """Return a dict of the kinds allowable columns for this object."""
    axis_names = {0: "index", 1: "columns"}

    index_queryables = [(a.cname, a) for a in self.index_axes]
    non_index_queryables = [(axis_names[axis], None) for axis, _ in self.non_index_axes]
    values_queryables = [
        (v.cname, v) for v in self.values_axes if v.name in self.data_columns
    ]

    return dict(index_queryables + non_index_queryables + values_queryables)

def median(self, *, axis: AxisInt | None = None, skipna: bool = True, **kwargs):
    nv.validate_median((), kwargs)

    if axis is not None and abs(axis) >= self.ndim:
        raise ValueError("abs(axis) must be less than ndim")

    result = nanops.nanmedian(self._ndarray, axis=axis, skipna=skipna)
    return self._wrap_reduction_result(axis, result)

def __iter__(self) -> Iterator:
    if self.ndim == 1:
        yield from self._iter_1d()
    else:
        yield from (self[i] for i in range(len(self)))

def _iter_1d(self) -> Iterator:
    if not self._hasna:
        yield from self._data
    else:
        na_value = self.dtype.na_value
        yield from (na_value if isna_ else val for isna_, val in zip(self._mask, self._data, strict=True))

def get_dtypes(self) -> npt.NDArray[np.object_]:
    if self._dtypes_cache is None:
        blocks = self.blocks
        dtypes = np.array([blk.dtype for blk in blocks], dtype=object)
        cache = dtypes.take(self.blknos)
        if blocks is self.blocks:
            self._dtypes_cache = cache
    return self._dtypes_cache.copy()

def dtype(self) -> tuple[DtypeKind, int, str, str]:
    dtype = self._col.dtype

    if isinstance(dtype, pd.CategoricalDtype):
        return self._categorical_dtype_info()
    elif is_string_dtype(dtype):
        return self._string_dtype_info(dtype)
    else:
        return self._dtype_from_pandasdtype(dtype)

def _categorical_dtype_info(self) -> tuple[DtypeKind, int, str, str]:
    codes = self._col.values.codes
    _, bitwidth, c_arrow_dtype_f_str, _ = self._dtype_from_pandasdtype(codes.dtype)
    return (
        DtypeKind.CATEGORICAL,
        bitwidth,
        c_arrow_dtype_f_str,
        Endianness.NATIVE,
    )

def _string_dtype_info(self, dtype) -> tuple[DtypeKind, int, str, str]:
    if infer_dtype(self._col) in ("string", "empty"):
        return (
            DtypeKind.STRING,
            8,
            dtype_to_arrow_c_fmt(dtype),
            Endianness.NATIVE,
        )
    raise NotImplementedError("Non-string object dtypes are not supported yet")

def __from_arrow__(self, array: pyarrow.Array | pyarrow.ChunkedArray) -> BooleanArray:
    """
    Construct BooleanArray from pyarrow Array/ChunkedArray.
    """
    import pyarrow

    def create_boolean_array(arr):
        buflist = arr.buffers()
        data = pyarrow.BooleanArray.from_buffers(
            arr.type, len(arr), [None, buflist[1]], offset=arr.offset
        ).to_numpy(zero_copy_only=False)
        mask = (
            ~pyarrow.BooleanArray.from_buffers(
                arr.type, len(arr), [None, buflist[0]], offset=arr.offset
            ).to_numpy(zero_copy_only=False)
            if arr.null_count != 0
            else np.zeros(len(arr), dtype=bool)
        )
        return BooleanArray(data, mask)

    if array.type != pyarrow.bool_() and not pyarrow.types.is_null(array.type):
        raise TypeError(f"Expected array of boolean type, got {array.type} instead")

    chunks = [array] if isinstance(array, pyarrow.Array) else array.chunks
    length = len(array) if isinstance(array, pyarrow.Array) else array.length()

    if pyarrow.types.is_null(array.type):
        mask = np.ones(length, dtype=bool)
        data = np.empty(length, dtype=bool)
        return BooleanArray(data, mask)

    results = [create_boolean_array(arr) for arr in chunks]

    return (
        BooleanArray._concat_same_type(results)
        if results
        else BooleanArray(np.array([], dtype=np.bool_), np.array([], dtype=np.bool_))
    )

def _intersection(self, other, sort: bool = False):
    """
    intersection specialized to the case with matching dtypes.
    """
    if (self.left.is_unique and self.right.is_unique) or (
        other.left.is_unique and other.right.is_unique and self.isna().sum() <= 1
    ):
        # Swap other/self if other is unique and self does not have multiple NaNs
        taken = self._intersection_unique(other) if self.left.is_unique else other._intersection_unique(self)
    else:
        # duplicates
        taken = self._intersection_non_unique(other)

    return taken.sort_values() if sort else taken

def __call__(
    self,
    args: tuple[Any, ...],
    kwargs: dict[str, Any],
    fname: str | None = None,
    max_fname_arg_count: int | None = None,
    method: str | None = None,
) -> None:
    if not args and not kwargs:
        return

    fname = fname or self.fname
    max_fname_arg_count = max_fname_arg_count or self.max_fname_arg_count
    method = method or self.method

    validation_methods = {
        "args": lambda: validate_args(fname, args, cast("int", max_fname_arg_count), self.defaults),
        "kwargs": lambda: validate_kwargs(fname, kwargs, self.defaults),
        "both": lambda: validate_args_and_kwargs(fname, args, kwargs, cast("int", max_fname_arg_count), self.defaults)
    }

    if method in validation_methods:
        validation_methods[method]()
    else:
        raise ValueError(f"invalid validation method '{method}'")

def _setitem_array(self, key, value) -> None:
    if com.is_bool_indexer(key):
        self._handle_bool_indexer(key, value)
    elif isinstance(value, DataFrame):
        self._handle_dataframe_value(key, value)
    elif not is_list_like(value):
        self._handle_scalar_value(key, value)
    elif isinstance(value, np.ndarray) and value.ndim == 2:
        self._iset_not_inplace(key, value)
    elif np.ndim(value) > 1:
        self._handle_list_of_lists(key, value)
    else:
        self._iset_not_inplace(key, value)

def _handle_bool_indexer(self, key, value):
    if len(key) != len(self.index):
        raise ValueError(f"Item wrong length {len(key)} instead of {len(self.index)}!")
    key = check_bool_indexer(self.index, key)
    indexer = key.nonzero()[0]
    if isinstance(value, DataFrame):
        value = value.reindex(self.index.take(indexer))
    self.iloc[indexer] = value

def _handle_dataframe_value(self, key, value):
    check_key_length(self.columns, key, value)
    for k1, k2 in zip(key, value.columns, strict=False):
        self[k1] = value[k2]

def _handle_scalar_value(self, key, value):
    for col in key:
        self[col] = value

def _handle_list_of_lists(self, key, value):
    value = DataFrame(value).values
    self._setitem_array(key, value)

def equals(self, other: object) -> bool:
    """
    Implementation for DataFrame.equals
    """
    if not isinstance(other, type(self)):
        return False

    if len(self.axes) != len(other.axes):
        return False

    if not all(ax1.equals(ax2) for ax1, ax2 in zip(self.axes, other.axes, strict=True)):
        return False

    return self._equal_values(other)

def _maybe_cast_listlike_indexer(self, keyarr):
    """
    Analogue to maybe_cast_indexer for get_indexer instead of get_loc.
    """
    try:
        res = self._data._validate_listlike(keyarr, allow_object=True)
    except (ValueError, TypeError):
        if isinstance(keyarr, ExtensionArray):
            res = keyarr
        else:
            res = com.asarray_tuplesafe(keyarr)
    return Index(res, dtype=res.dtype)

def delete(self, loc) -> Self:
    if isinstance(self._left, np.ndarray):
        new_left = np.delete(self._left, loc)
        new_right = np.delete(self._right, loc)
    else:
        new_left = self._left.delete(loc)
        new_right = self._right.delete(loc)
    return self._shallow_copy(left=new_left, right=new_right)

def _getitem_nested_tuple(self, tup: tuple):
    for key in tup:
        check_dict_or_set_indexers(key)

    if len(tup) > self.ndim:
        if self.name != "loc":
            raise ValueError("Too many indices")  # pragma: no cover

        if all(is_hashable(x, allow_slice=False) or com.is_null_slice(x) for x in tup):
            with suppress(IndexingError):
                return cast("_LocIndexer", self)._handle_lowerdim_multi_index_axis0(tup)

        if isinstance(self.obj, ABCSeries) and any(isinstance(k, tuple) for k in tup):
            raise IndexingError("Too many indexers")

        axis = self.axis or 0
        return self._getitem_axis(tup, axis=axis)

    obj = self.obj
    axis = len(tup) - 1
    for key in reversed(tup):
        if com.is_null_slice(key):
            axis -= 1
            continue

        obj = getattr(obj, self.name)._getitem_axis(key, axis=axis)
        axis -= 1

        if is_scalar(obj) or not hasattr(obj, "ndim"):
            break

    return obj

def apply(self, f, align_keys: list[str] | None = None, **kwargs) -> Self:
    """
    Iterate over the blocks, collect and create a new BlockManager.

    Parameters
    ----------
    f : str or callable
        Name of the Block method to apply.
    align_keys: List[str] or None, default None
    **kwargs
        Keywords to pass to `f`

    Returns
    -------
    BlockManager
    """
    assert "filter" not in kwargs

    align_keys = align_keys or []
    result_blocks: list[Block] = []
    aligned_args = {k: kwargs[k] for k in align_keys}

    def update_kwargs_for_block(b):
        for k, obj in aligned_args.items():
            if isinstance(obj, (ABCSeries, ABCDataFrame)):
                kwargs[k] = obj.iloc[b.mgr_locs.indexer]._values if obj.ndim == 1 else obj.iloc[:, b.mgr_locs.indexer]._values
            else:
                kwargs[k] = obj[b.mgr_locs.indexer]

    for b in self.blocks:
        if aligned_args:
            update_kwargs_for_block(b)

        applied = b.apply(f, **kwargs) if callable(f) else getattr(b, f)(**kwargs)
        result_blocks = extend_blocks(applied, result_blocks)

    return type(self).from_blocks(result_blocks, [ax.view() for ax in self.axes])

def __contains__(self, key: str) -> bool:
    """
    Check for existence of this key
    Can match the exact pathname or the pathname without the leading '/'
    """
    node = self.get_node(key)
    if node:
        return key in (node._v_pathname, node._v_pathname[1:])
    return False

def _get_axes(
    N: int, K: int, index: Index | None, columns: Index | None
) -> tuple[Index, Index]:
    index = ensure_index(index) if index is not None else default_index(N)
    columns = ensure_index(columns) if columns is not None else default_index(K)
    return index, columns

def range_to_ndarray(rng: range) -> np.ndarray:
    """
    Cast a range object to ndarray.
    """
    def construct_array(dtype):
        try:
            return np.arange(rng.start, rng.stop, rng.step, dtype=dtype)
        except OverflowError:
            return construct_1d_object_array_from_listlike(list(rng))

    try:
        return construct_array("int64")
    except OverflowError:
        if (rng.start >= 0 and rng.step > 0) or (rng.step < 0 <= rng.stop):
            return construct_array("uint64")
        return construct_1d_object_array_from_listlike(list(rng))

def __eq__(self, other: object) -> bool:
    if isinstance(other, str):
        return other == self.name
    if other is self:
        return True
    if not (hasattr(other, "ordered") and hasattr(other, "categories")):
        return False
    if self.categories is None or other.categories is None:
        return self.categories is other.categories
    if self.ordered or other.ordered:
        return (self.ordered == other.ordered) and self.categories.equals(other.categories)

    left, right = self.categories, other.categories
    if left.dtype != right.dtype or len(left) != len(right):
        return False
    if self.categories.equals(other.categories):
        return True
    if left.dtype != object:
        indexer = left.get_indexer(right)
        return bool((indexer != -1).all())
    return set(left) == set(right)

def _take_nd_ndarray(
    arr: np.ndarray,
    indexer: npt.NDArray[np.intp] | None,
    axis: AxisInt,
    fill_value,
    allow_fill: bool,
) -> np.ndarray:
    if indexer is None:
        indexer = np.arange(arr.shape[axis], dtype=np.intp)
        dtype, fill_value = arr.dtype, arr.dtype.type()
    else:
        indexer = ensure_platform_int(indexer)

    dtype, fill_value, mask_info = _take_preprocess_indexer_and_fill_value(
        arr, indexer, fill_value, allow_fill
    )

    flip_order = arr.ndim == 2 and arr.flags.f_contiguous
    if flip_order:
        arr = arr.T
        axis = arr.ndim - axis - 1

    out_shape = list(arr.shape)
    out_shape[axis] = len(indexer)
    order = "F" if arr.flags.f_contiguous and axis == arr.ndim - 1 else "C"
    out = np.empty(tuple(out_shape), dtype=dtype, order=order)

    func = _get_take_nd_function(
        arr.ndim, arr.dtype, out.dtype, axis=axis, mask_info=mask_info
    )
    needs_fill = mask_info[1] if mask_info is not None else allow_fill
    func(arr, indexer, out, fill_value, allow_fill=needs_fill)

    return out.T if flip_order else out

def _maybe_infer_ndim(
    values: ArrayLike, placement: BlockPlacement, ndim: int | None
) -> int:
    """
    If `ndim` is not provided, infer it from placement and values.
    """
    if ndim is not None:
        return ndim

    # GH#38134 Block constructor now assumes ndim is not None
    if isinstance(values.dtype, np.dtype):
        return values.ndim

    return 1 if len(placement) != 1 else 2

def visit_Assign(self, node, **kwargs):
    """
    Support a single assignment node, like

    c = a + b

    Set the assigner at the top level, must be a Name node which
    might or might not exist in the resolvers.
    """
    self._validate_assignment(node)
    assigner = self._get_assigner(node.targets[0], **kwargs)
    self.assigner = getattr(assigner, "name", assigner)
    if self.assigner is None:
        raise SyntaxError(
            "left hand side of an assignment must be a single resolvable name"
        )
    return self.visit(node.value, **kwargs)

def _validate_assignment(self, node):
    if len(node.targets) != 1:
        raise SyntaxError("can only assign a single expression")
    if not isinstance(node.targets[0], ast.Name):
        raise SyntaxError("left hand side of an assignment must be a single name")
    if self.env.target is None:
        raise ValueError("cannot assign without a target object")

def _get_assigner(self, target, **kwargs):
    try:
        return self.visit(target, **kwargs)
    except UndefinedVariableError:
        return target.id

def _format_regular_rows(self) -> Iterable[ExcelCell]:
    if self._has_aliases or self.header:
        self.rowcounter += 1

    coloffset = 0
    if self.index:
        index_label = self._determine_index_label()
        if isinstance(self.columns, MultiIndex):
            self.rowcounter += 1

        if index_label and self.header is not False:
            yield ExcelCell(self.rowcounter - 1, 0, index_label, None)

        index_values = self._get_index_values()
        for idx, idxval in enumerate(index_values):
            yield CssExcelCell(
                row=self.rowcounter + idx,
                col=0,
                val=idxval,
                style=None,
                css_styles=getattr(self.styler, "ctx_index", None),
                css_row=idx,
                css_col=0,
                css_converter=self.style_converter,
            )
        coloffset = 1

    yield from self._generate_body(coloffset)

def _determine_index_label(self):
    if self.index_label and isinstance(self.index_label, (list, tuple, np.ndarray, Index)):
        return self.index_label[0]
    elif self.index_label and isinstance(self.index_label, str):
        return self.index_label
    else:
        return self.df.index.names[0]

def _get_index_values(self):
    if isinstance(self.df.index, PeriodIndex):
        return self.df.index.to_timestamp()
    return self.df.index

def _arith_method(self, other, op):
    op_name = op.__name__

    if isinstance(other, SparseArray):
        return _sparse_array_op(self, other, op, op_name)

    if is_scalar(other):
        return self._handle_scalar_op(other, op, op_name)

    return self._handle_non_scalar_op(other, op, op_name)

def _handle_scalar_op(self, other, op, op_name):
    with np.errstate(all="ignore"):
        fill = op(_get_fill(self), np.asarray(other))
        result = op(self.sp_values, other)

    if op_name == "divmod":
        left, right = result
        lfill, rfill = fill
        return (
            _wrap_result(op_name, left, self.sp_index, lfill),
            _wrap_result(op_name, right, self.sp_index, rfill),
        )

    return _wrap_result(op_name, result, self.sp_index, fill)

def _handle_non_scalar_op(self, other, op, op_name):
    if not isinstance(other, (list, np.ndarray, ExtensionArray)) and not ops.has_castable_attr(other):
        warnings.warn(
            f"Operation with {type(other).__name__} is deprecated. "
            "In a future version these will be treated as scalar-like. "
            "To retain the old behavior, explicitly wrap in a Series "
            "instead.",
            Pandas4Warning,
            stacklevel=find_stack_level(),
        )

    other = np.asarray(other)
    with np.errstate(all="ignore"):
        if len(self) != len(other):
            raise AssertionError(f"length mismatch: {len(self)} vs. {len(other)}")
        if not isinstance(other, SparseArray):
            dtype = getattr(other, "dtype", None)
            other = _as_sparse_operand(other, self.fill_value, dtype=dtype)
        return _sparse_array_op(self, other, op, op_name)

def _getitem_axis(self, key, axis: AxisInt):
    if key is Ellipsis:
        key = slice(None)
    elif isinstance(key, ABCDataFrame):
        raise IndexError(
            "DataFrame indexer is not allowed for .iloc\n"
            "Consider using .loc for automatic alignment."
        )

    if isinstance(key, slice):
        return self._get_slice_axis(key, axis=axis)

    if is_iterator(key):
        key = list(key)

    if isinstance(key, list):
        key = np.asarray(key)

    if com.is_bool_indexer(key):
        self._validate_key(key, axis)
        return self._getbool_axis(key, axis=axis)

    if is_list_like_indexer(key):
        return self._get_list_axis(key, axis=axis)

    key = item_from_zerodim(key)
    if not is_integer(key):
        raise TypeError("Cannot index by location index with a non-integer key")

    self._validate_integer(key, axis)
    return self.obj._ixs(key, axis=axis)

def _update_stacker(cls, ax: Axes, stacking_id: int | None, values) -> None:
    if stacking_id is None:
        return

    if (values >= 0).all():
        stacker_prior = ax._stacker_pos_prior
    elif (values <= 0).all():
        stacker_prior = ax._stacker_neg_prior
    else:
        return

    # TODO #54485
    stacker_prior[stacking_id] += values  # type: ignore[attr-defined]

def infer_filename(self) -> str | None:
    """
    If an explicit archive_name is not given, we still want the file inside the zip
    file not to be named something.tar, because that causes confusion (GH39465).
    """
    if self.name is None:
        return None

    filename = Path(self.name)
    suffixes_to_strip = {".tar": 1, ".tar.gz": 2, ".tar.bz2": 2, ".tar.xz": 2}
    strip_count = suffixes_to_strip.get(filename.suffix, 0)

    for _ in range(strip_count):
        filename = filename.with_suffix("")

    return filename.name

def isin(self, values: ArrayLike) -> npt.NDArray[np.bool_]:
    value_set = [
        pa.scalar(value, from_pandas=True).as_py()
        for value in values
        if pa.scalar(value, from_pandas=True).type in (pa.string(), pa.null(), pa.large_string())
    ]

    if not value_set:
        return np.zeros(len(self), dtype=bool)

    result = pc.is_in(
        self._pa_array, value_set=pa.array(value_set, type=self._pa_array.type)
    )
    return np.array(result, dtype=np.bool_)

def _chunk_to_dataframe(self) -> DataFrame:
    n = self._current_row_in_chunk_index
    m = self._current_row_in_file_index
    ix = range(m - n, m)
    rslt = {}

    js, jb = 0, 0
    infer_string = using_string_dtype()

    for j, name in enumerate(self.column_names):
        col_type = self._column_types[j]

        if col_type == b"d":
            col_arr = self._byte_chunk[jb, :].view(dtype=self.byte_order + "d")
            rslt[name] = pd.Series(col_arr, dtype=np.float64, index=ix, copy=False)
            convert_type = self._column_convert_types[j]
            if convert_type is not None:
                rslt[name] = _convert_datetimes(rslt[name], convert_type)
            jb += 1

        elif col_type == b"s":
            if self._str_mode != const.string_mode_object:
                rslt[name] = pd.Series(self._string_column(js), index=ix, copy=False)
            else:
                rslt[name] = pd.Series(self._string_chunk[js, :], index=ix, copy=False)
                if self.convert_text and self.encoding is not None:
                    rslt[name] = self._decode_string(rslt[name].str)
                    if infer_string:
                        rslt[name] = rslt[name].astype("str")
            js += 1

        else:
            self.close()
            raise ValueError(f"unknown column type {col_type!r}")

    return DataFrame(rslt, columns=self.column_names, index=ix, copy=False)

def _have_mi_columns(self) -> bool:
    if self.header is None:
        return False

    return isinstance(self.header, (list, tuple, np.ndarray)) and len(self.header) > 1

def write(self, obj, data_columns=None, **kwargs) -> None:  # type: ignore[override]
    data_columns = self._initialize_data_columns(data_columns, obj)
    obj, self.levels = self.validate_multiindex(obj)
    assert isinstance(self.levels, list)  # for mypy
    self._prepend_levels_to_data_columns(data_columns)
    super().write(obj=obj, data_columns=data_columns, **kwargs)

def _initialize_data_columns(self, data_columns, obj):
    if data_columns is None:
        return []
    if data_columns is True:
        return obj.columns.tolist()
    return data_columns

def _prepend_levels_to_data_columns(self, data_columns):
    for n in self.levels:
        if n not in data_columns:
            data_columns.insert(0, n)

def assert_class_equal(
    left: Any, right: Any, exact: bool | str = True, obj: str = "Input"
) -> None:
    """
    Checks classes are equal.
    """
    __tracebackhide__ = True

    def repr_class(x: Any) -> Any:
        return x if isinstance(x, Index) else type(x).__name__

    def is_class_equiv(idx: Index) -> bool:
        """Classes that are a RangeIndex (sub-)instance or exactly an `Index`."""
        return isinstance(idx, (Index, RangeIndex))

    if type(left) == type(right):
        return

    if exact == "equiv" and is_class_equiv(left) and is_class_equiv(right):
        return

    msg = f"{obj} classes are different"
    raise_assert_detail(obj, msg, repr_class(left), repr_class(right))

def _get_value(self, index, col, takeable: bool = False) -> Scalar:
    """
    Quickly retrieve single value at passed column and index.

    Parameters
    ----------
    index : row label
    col : column label
    takeable : interpret the index/col as indexers, default False

    Returns
    -------
    scalar

    Notes
    -----
    Assumes that both `self.index._index_as_unique` and
    `self.columns._index_as_unique`; Caller is responsible for checking.
    """
    if takeable:
        return self._get_takeable_value(index, col)

    return self._get_non_takeable_value(index, col)

def _get_takeable_value(self, index, col):
    values = self._get_column_array(col)
    return maybe_unbox_numpy_scalar(values[index], object_with_dtype=values)

def _get_non_takeable_value(self, index, col):
    series = self._get_item(col)

    if not isinstance(self.index, MultiIndex):
        row = self.index.get_loc(index)
        values = series._values
        return maybe_unbox_numpy_scalar(values[row], object_with_dtype=values)

    return self._get_multiindex_value(index, series)

def _get_multiindex_value(self, index, series):
    try:
        loc = self.index._engine.get_loc(index)
    except TypeError:
        loc = self.index.get_loc(index)
    return series._ixs(loc)

def _searchsorted_monotonic(self, label, side: Literal["left", "right"] = "left"):
    if self.is_monotonic_increasing and isinstance(label, (Timestamp, Timedelta)):
        label_unit = abbrev_to_npy_unit(label.unit)
        self_unit = abbrev_to_npy_unit(self.unit)

        if label_unit > self_unit:
            label = label.as_unit(self.unit) if side == "right" else label.ceil(self.unit).as_unit(self.unit)

    return super()._searchsorted_monotonic(label, side)

def _parse_letter_version(
    letter: str | None, number: str | bytes | SupportsInt | None
) -> tuple[str, int] | None:
    if not letter and number:
        return "post", int(number)

    if letter:
        number = 0 if number is None else int(number)
        letter = letter.lower()

        letter_map = {
            "alpha": "a",
            "beta": "b",
            "c": "rc",
            "pre": "rc",
            "preview": "rc",
            "rev": "post",
            "r": "post"
        }
        letter = letter_map.get(letter, letter)

        return letter, number

    return None

def __getitem__(self, key: int) -> Any:
    """Provide backward-compatible tuple-style access."""
    try:
        return (self.column, self.aggfunc, self.args, self.kwargs)[key]
    except IndexError:
        raise IndexError("index out of range")

def _check_compatible_with(
    self,
    other: Period | NaTType | PeriodArray,  # type: ignore[override]
) -> None:
    if other is NaT:
        return

    freqstr = other._dtype._freqstr if isinstance(other, Period) else other.dtype._freqstr  # type: ignore[union-attr]
    self._require_matching_unit(freqstr)

def _get_block_for_concat_plan(
    mgr: BlockManager, bp: BlockPlacement, blkno: int, *, max_len: int
) -> Block:
    blk = mgr.blocks[blkno]

    if _is_full_block(bp, blk):
        return blk

    ax0_blk_indexer = mgr.blklocs[bp.indexer]
    slc = lib.maybe_indices_to_slice(ax0_blk_indexer, max_len)

    return blk.slice_block_columns(slc) if isinstance(slc, slice) else blk.take_block_columns(slc)

def _is_full_block(bp: BlockPlacement, blk: Block) -> bool:
    return len(bp) == len(blk.mgr_locs) and blk.mgr_locs.is_slice_like and blk.mgr_locs.as_slice.step == 1

def _getitem_bool_array(self, key):
    if isinstance(key, Series) and not key.index.equals(self.index):
        warnings.warn(
            "Boolean Series key will be reindexed to match DataFrame index.",
            UserWarning,
            stacklevel=find_stack_level(),
        )
    elif len(key) != len(self.index):
        raise ValueError(
            f"Item wrong length {len(key)} instead of {len(self.index)}."
        )

    key = check_bool_indexer(self.index, key)

    if key.all():
        return self.copy(deep=False)

    return self.take(key.nonzero()[0], axis=0)

def _na_value(self) -> Hashable:
    """The expected NA value to use with this index."""
    dtype = self.dtype
    if isinstance(dtype, np.dtype) and dtype.kind in "mM":
        return NaT
    return getattr(dtype, 'na_value', np.nan)

def prune(self, klass):
    if self.op in ARITH_OPS_SYMS:
        raise NotImplementedError(
            "arithmetic operations are not supported inside an HDFStore "
            "'where' filter; instead store a precomputed column as a "
            "data_column and query that, or read the data and apply the "
            "filter in pandas (e.g. df[df['A'] % 3 == 0])."
        )

    def pr(left, right):
        if left is None:
            return right
        if right is None:
            return left

        if isinstance(left, ConditionBinOp) and isinstance(right, ConditionBinOp):
            return JointConditionBinOp(
                self.op, left, right, queryables=self.queryables, encoding=self.encoding
            ).evaluate()

        if isinstance(left, FilterBinOp) and isinstance(right, FilterBinOp):
            return JointFilterBinOp(
                self.op, left, right, queryables=self.queryables, encoding=self.encoding
            ).evaluate()

        if isinstance(left, klass):
            return left
        if isinstance(right, klass):
            return right

        return klass(
            self.op, left, right, queryables=self.queryables, encoding=self.encoding
        ).evaluate()

    left, right = self.lhs, self.rhs

    if is_term(left):
        left = left if is_term(right) else left.prune(klass)
    if is_term(right):
        right = right if is_term(left) else right.prune(klass)

    return pr(left, right)

def to_string(self) -> str:
    series = self.tr_series
    footer = self._get_footer()

    if not series:
        return f"{type(self.series).__name__}([], {footer})"

    index = series.index
    have_header = _has_names(index)
    fmt_index = self._format_index(index)
    fmt_values = self._get_formatted_values()

    if self.is_truncated_vertically:
        self._insert_truncation_marker(fmt_values, fmt_index)

    result = self._assemble_result(fmt_index, fmt_values, have_header)

    if footer:
        result += "\n" + footer

    return str("".join(result))

def _format_index(self, index):
    if isinstance(index, MultiIndex):
        fmt_index = index._format_multi(include_names=True, sparsify=None)
        adj = printing.get_adjustment()
        return adj.adjoin(2, *fmt_index).split("\n")
    return index._format_flat(include_name=True)

def _insert_truncation_marker(self, fmt_values, fmt_index):
    row_num = cast("int", self.tr_row_num)
    width = self.adj.len(fmt_values[row_num - 1])
    dot_str = "..." if width > 3 else ".."
    dot_str = self.adj.justify([dot_str], width, mode="center")[0]
    fmt_values.insert(row_num, dot_str)
    fmt_index.insert(row_num + 1, "")

def _assemble_result(self, fmt_index, fmt_values, have_header):
    if self.index:
        result = self.adj.adjoin(3, *[fmt_index[1:], fmt_values])
    else:
        result = self.adj.adjoin(3, fmt_values)

    if self.header and have_header:
        result = fmt_index[0] + "\n" + result

    return result

def _str_rsplit(self, pat: str | None = None, n: int | None = -1) -> Self:
    if pat is not None and not isinstance(pat, str):
        raise TypeError(f"expected a string object, not {type(pat).__name__}")

    n = None if n in {-1, 0} else n

    split_function = (
        pc.utf8_split_whitespace if pat is None else pc.split_pattern
    )

    return self._from_pyarrow_array(
        split_function(self._pa_array, pat, max_splits=n, reverse=True)
    )

def _key_for_pipe(
    self,
    key: str,
    base_class_name: str | None = None,
    settings: Settings | None = None,
) -> str:
    class_name = self.__class__.__name__
    if base_class_name and class_name != base_class_name:
        formatted_key = f"{class_name.upper()}_{key}"
        if settings and settings.get(formatted_key):
            return formatted_key
    return key

def _normalize_stop_mode(mode: _StopMode, *, allow_force: bool = True) -> _StopMode:
    if mode not in _STOP_MODE_PRIORITY:
        raise ValueError(
            f"Unknown stop mode {mode!r}. Expected one of: graceful, fast, force"
        )
    if mode == "force" and not allow_force:
        raise ValueError("The force stop mode is not supported in this context")
    return mode

def process_options(self, args: list[str], opts: argparse.Namespace) -> None:
    super().process_options(args, opts)
    self._convert_spargs_to_dict(opts)
    if opts.output or opts.overwrite_output:
        self._process_feed_options(opts)

def _convert_spargs_to_dict(self, opts: argparse.Namespace) -> None:
    try:
        opts.spargs = arglist_to_dict(opts.spargs)
    except ValueError:
        raise UsageError(
            "Invalid -a value, use -a NAME=VALUE", print_help=False
        ) from None

def _process_feed_options(self, opts: argparse.Namespace) -> None:
    assert self.settings is not None
    feeds = feed_process_params_from_cli(
        self.settings,
        opts.output,
        overwrite_output=opts.overwrite_output,
    )
    self.settings.set("FEEDS", feeds, priority="cmdline")

def _update_curprio(self) -> None:
    prios = {
        p for queues in (self.queues, self._start_queues) for p, q in queues.items() if q
    }
    self.curprio = min(prios, default=None)

def _process_queue(self, slot: Slot) -> None:
    if slot.latercall:
        return

    now = monotonic()
    delay = slot.download_delay()
    if delay:
        penalty = delay - now + slot.lastseen
        if penalty > 0:
            slot.latercall = call_later(penalty, self._latercall, slot)
            return

    self._process_requests(slot, now, delay)

def _process_requests(self, slot: Slot, now: float, delay: float) -> None:
    while slot.queue and slot.free_transfer_slots() > 0:
        slot.lastseen = now
        request, queue_dfd = slot.queue.popleft()
        download_dfd = deferred_from_coro(
            self._wait_for_download(slot, request, queue_dfd)
        )
        assert isinstance(download_dfd, Deferred)
        self._download_tasks[request] = download_dfd
        download_dfd.addBoth(self._download_task_done, request)
        if delay:
            self._process_queue(slot)
            break

def _set_conditional_validators(self, request: Request, cachedresponse: Response) -> None:
    headers_map = {
        b"Last-Modified": b"If-Modified-Since",
        b"ETag": b"If-None-Match"
    }

    for cached_header, request_header in headers_map.items():
        if cached_header in cachedresponse.headers:
            request.headers[request_header] = cachedresponse.headers[cached_header]

def replace(
    self, *args: Any, cls: type[Request] | None = None, **kwargs: Any
) -> Request:
    if "body" not in kwargs and (data := kwargs.pop("data", None)) is not None:
        kwargs["body"] = self._dumps(data)
    elif "body" in kwargs and "data" in kwargs:
        warnings.warn(
            "Both body and data passed. data will be ignored", stacklevel=2
        )

    return super().replace(*args, cls=cls, **kwargs)

async def _process_request(
    self,
    request: Request,
    download_func: Callable[[Request], Coroutine[Any, Any, Response]],
) -> Response | Request:
    for method in self.methods["process_request"]:
        assert method is not None
        response = await ensure_awaitable(
            self._handle_mw_method(method, request=request),
            _warn=global_object_name(method),
        )
        if response is None:
            continue
        if not isinstance(response, (Response, Request)):
            raise _InvalidOutput(
                f"Middleware {method.__qualname__} must return None, Response or "
                f"Request, got {response.__class__.__name__}"
            )
        return response
    return await download_func(request)

def set_asyncio_event_loop(event_loop_path: str | None) -> AbstractEventLoop:
    """Sets and returns the event loop with specified import path."""
    if event_loop_path:
        return _set_custom_event_loop(event_loop_path)
    return _set_default_event_loop()

def _set_custom_event_loop(event_loop_path: str) -> AbstractEventLoop:
    event_loop_class: type[AbstractEventLoop] = load_object(event_loop_path)
    event_loop = _get_asyncio_event_loop()
    if not isinstance(event_loop, event_loop_class):
        event_loop = event_loop_class()
        asyncio.set_event_loop(event_loop)
    return event_loop

def _set_default_event_loop() -> AbstractEventLoop:
    try:
        with catch_warnings():
            filterwarnings(
                "ignore",
                message="There is no current event loop",
                category=DeprecationWarning,
            )
            return asyncio.get_event_loop()
    except RuntimeError:
        event_loop = asyncio.new_event_loop()
        asyncio.set_event_loop(event_loop)
        return event_loop

def __init__(
    self, *args: Any, dumps_kwargs: dict[str, Any] | None = None, **kwargs: Any
) -> None:
    self._dumps_kwargs: dict[str, Any] = copy.deepcopy(dumps_kwargs) if dumps_kwargs else {}
    self._dumps_kwargs.setdefault("sort_keys", True)

    body_passed = "body" in kwargs
    data = kwargs.pop("data", None)

    if body_passed and data is not None:
        warnings.warn(
            "Both body and data passed. data will be ignored", stacklevel=2
        )
    elif not body_passed and data is not None:
        kwargs["body"] = self._dumps(data)
        kwargs.setdefault("method", "POST")

    super().__init__(*args, **kwargs)
    self.headers.setdefault("Content-Type", "application/json")
    self.headers.setdefault(
        "Accept", "application/json, text/javascript, */*; q=0.01"
    )

def check_stop_download(
    signal: object, crawler: Crawler, request: Request, **kwargs: Any
) -> StopDownload | None:
    """Send the given signal and check if any of its handlers raised
    :exc:`~scrapy.exceptions.StopDownload`.

    Return the raised exception or ``None``.
    """
    signal_result = crawler.signals.send_catch_log(
        signal=signal,
        request=request,
        spider=crawler.spider,
        **kwargs,
    )
    stop_download_exception = next(
        (
            result.value
            for handler, result in signal_result
            if isinstance(result, Failure) and isinstance(result.value, StopDownload)
        ),
        None,
    )
    if stop_download_exception:
        logger.debug(
            f"Download stopped for {request} from signal handler {handler.__qualname__}"
        )
    return stop_download_exception

def start_parsing(self, url: str, opts: argparse.Namespace) -> None:
    assert self.crawler_process and self.spidercls
    self.pcrawler = self._create_crawler(self.spidercls)
    self.crawler_process.crawl(self.pcrawler, **opts.spargs)
    self.crawler_process.start()

    if self.crawler_process.bootstrap_failed:
        self.exitcode = 1

    if not self.first_response:
        logger.error("No response downloaded for: %(url)s", {"url": url})

def process_options(self, args: list[str], opts: argparse.Namespace) -> None:
    super().process_options(args, opts)
    self._convert_spargs_to_dict(opts)
    self._set_empty_pipelines_and_feeds()

def _convert_spargs_to_dict(self, opts: argparse.Namespace) -> None:
    try:
        opts.spargs = arglist_to_dict(opts.spargs)
    except ValueError:
        raise UsageError(
            "Invalid -a value, use -a NAME=VALUE", print_help=False
        ) from None

def _set_empty_pipelines_and_feeds(self) -> None:
    assert self.settings is not None
    priority = (SETTINGS_PRIORITIES["spider"] + SETTINGS_PRIORITIES["cmdline"]) // 2
    self.settings.set("ITEM_PIPELINES", {}, priority=priority)
    self.settings.set("FEEDS", {}, priority=priority)

async def download_request(self, request: Request) -> Response:
    if urlparse_cached(request).scheme == "http":
        raise UnsupportedURLSchemeError(
            f"{type(self).__name__} doesn't support plain HTTP."
        )
    agent = self._create_agent()
    assert self._crawler.spider
    with wrap_twisted_exceptions():
        return await maybe_deferred_to_future(
            agent.download_request(request, self._crawler.spider)
        )

def _create_agent(self) -> _ScrapyH2Agent:
    return _ScrapyH2Agent(
        context_factory=self._context_factory,
        pool=self._pool,
        bind_address=self._bind_address,
        crawler=self._crawler,
    )

def closest_scrapy_cfg(
    path: str | os.PathLike[str] = ".",
    prevpath: str | os.PathLike[str] | None = None,
) -> str:
    """Return the path to the closest scrapy.cfg file by traversing the current
    directory and its parents
    """
    path = Path(path).resolve()
    if path == prevpath:
        return ""
    cfgfile = path / "scrapy.cfg"
    return str(cfgfile) if cfgfile.exists() else closest_scrapy_cfg(path.parent, path)

def _print_commands(settings: BaseSettings, inproject: bool) -> None:
    _print_header(settings, inproject)
    print(
        "Usage:\n",
        "  scrapy <command> [options] [args]\n",
        "Available commands:\n",
    )
    cmds = _get_commands_dict(settings, inproject)
    command_list = "\n".join(
        f"  {cmdname:<13} {cmdclass.short_desc()}"
        for cmdname, cmdclass in sorted(cmds.items())
    )
    print(command_list)
    if not inproject:
        print(
            "\n",
            "  [ more ]      More commands available when run from project directory",
        )
    print("\n", 'Use "scrapy <command> -h" to see more info about a command')

def _slot_gc(self, age: float = 60) -> None:
    mintime = monotonic() - age
    inactive_slots = [key for key, slot in self.slots.items() if not slot.active and slot.lastseen + slot.delay <= mintime]
    for key in inactive_slots:
        self.slots.pop(key).close()

def _store_in_thread(self, file: IO[bytes]) -> None:
    file.seek(0)
    try:
        from google.cloud.storage import Client  # noqa: PLC0415

        client = Client(project=self.project_id)
        bucket = client.bucket(self.bucket_name)
        kwargs = {} if self.timeout is None else {"timeout": self.timeout}
        blob = bucket.get_blob(self.blob_name, **kwargs) if not self.overwrite else None

        if blob is None:
            self._upload_new_blob(bucket, file, kwargs)
        else:
            self._append_to_existing_blob(bucket, blob, file, client, kwargs)
    finally:
        file.close()

def _upload_new_blob(self, bucket, file, kwargs):
    bucket.blob(self.blob_name).upload_from_file(
        file, predefined_acl=self.acl, **kwargs
    )

def _append_to_existing_blob(self, bucket, blob, file, client, kwargs):
    part = bucket.blob(f"{self.blob_name}.{uuid4().hex}.part")
    part.upload_from_file(file, predefined_acl=self.acl, **kwargs)
    try:
        blob.compose([blob, part], client=client, **kwargs)
    finally:
        part.delete(client=client, **kwargs)
    if self.acl:
        blob.acl.save_predefined(self.acl, client=client, **kwargs)

def _get_method(method: _CallableT | str | None, spider: Spider) -> _CallableT | None:
    if isinstance(method, str):
        return getattr(spider, method, None)
    return method if callable(method) else None

def init_prios(self, startprios: Iterable[int]) -> None:
    if not startprios:
        return

    for priority in startprios:
        self._initialize_queue(priority, self.qfactory, self.queues)
        if self._start_queue_cls:
            self._initialize_queue(priority, self._sqfactory, self._start_queues)

    self.curprio = min(startprios)

def _initialize_queue(self, priority, factory, queue_dict):
    q = factory(priority)
    if q:
        queue_dict[priority] = q
    else:
        q.close()
        self.changed = True

def get_help(self) -> str:
    help_lines = [
        "Available Scrapy objects:",
        "  scrapy     scrapy module (contains scrapy.Request, scrapy.Selector, etc)"
    ]

    help_lines.extend(
        f"  {k:<10} {v}" for k, v in sorted(self.vars.items()) if self._is_relevant(v)
    )

    help_lines.append("Useful shortcuts:")

    if self.fetch_available:
        help_lines.extend([
            "  fetch(url[, redirect=True]) Fetch URL and update local objects (by default, redirects are followed)",
            "  fetch(req)                  Fetch a scrapy.Request and update local objects"
        ])

    help_lines.extend([
        "  shelp()           Shell help (print this help)",
        "  view(response)    View response in a browser"
    ])

    return "\n".join(f"[s] {line}" for line in help_lines) + "\n"

def should_cache_response(self, response: Response, request: Request) -> bool:
    cc = self._parse_cachecontrol(response)

    if b"no-store" in cc or response.status == 304:
        return False

    if self.always_store:
        return True

    if b"max-age" in cc or b"Expires" in response.headers:
        return True

    if response.status in {300, 301, 308}:
        return True

    if response.status in {200, 203, 401}:
        return b"Last-Modified" in response.headers or b"ETag" in response.headers

    return False

def convert_image(
    self,
    image: Image.Image,
    size: tuple[int, int] | None = None,
    *,
    image_format: str,
    response_body: BytesIO,
) -> tuple[Image.Image, BytesIO]:
    target_format = image_format if self.preserve_format else "JPEG"

    def convert_to_rgb(image: Image.Image) -> Image.Image:
        if image.mode == "RGBA" or image.mode == "P":
            background = self._Image.new("RGBA", image.size, (255, 255, 255))
            background.paste(image, image)
            return background.convert("RGB")
        elif image.mode != "RGB":
            return image.convert("RGB")
        return image

    if target_format == "JPEG":
        image = convert_to_rgb(image)

    if size:
        image = image.copy()
        resampling_filter = getattr(self._Image.Resampling, 'LANCZOS', self._Image.ANTIALIAS)
        image.thumbnail(size, resampling_filter)
    elif target_format == image_format:
        image.format = target_format
        return image, response_body

    buf = BytesIO()
    image.save(buf, target_format)
    image.format = target_format
    return image, buf

def __init__(self, *middlewares: object, crawler: Crawler | None = None) -> None:
    self.crawler: Crawler | None = crawler
    self._warn_if_no_crawler(crawler)
    self.middlewares: tuple[object, ...] = middlewares
    self.methods: dict[str, deque[Callable[..., Any] | None]] = defaultdict(deque)
    self._mw_methods_requiring_spider: set[Callable[..., Any]] = set()
    self._initialize_middlewares(middlewares)

def _warn_if_no_crawler(self, crawler: Crawler | None) -> None:
    if crawler is None:
        warnings.warn(
            f"MiddlewareManager.__init__() was called without the crawler argument"
            f" when creating {global_object_name(self.__class__)}."
            f" This is deprecated and the argument will be required in future Scrapy versions.",
            category=ScrapyDeprecationWarning,
            stacklevel=2,
        )

def _initialize_middlewares(self, middlewares: tuple[object, ...]) -> None:
    for mw in middlewares:
        self._add_middleware(mw)

def _get_formatter(handler: logging.Handler, settings: Settings) -> logging.Formatter:
    fmt = settings.get("LOG_FORMAT")
    datefmt = settings.get("LOG_DATEFORMAT")

    use_colored_formatter = (
        isinstance(handler, logging.StreamHandler)
        and not isinstance(handler, logging.FileHandler)
        and settings.getbool("LOG_COLOR")
        and handler.stream.isatty()
        and tty_supports_color()
    )

    if use_colored_formatter:
        try:
            from colorlog import ColoredFormatter  # noqa: PLC0415
            return ColoredFormatter(fmt=f"%(log_color)s{fmt}", datefmt=datefmt)
        except ImportError:
            pass

    return logging.Formatter(fmt=fmt, datefmt=datefmt)

def window_updated(self, event: WindowUpdated) -> None:
    streams_to_update = (
        [self.streams[event.stream_id]] if event.stream_id != 0 else self.streams.values()
    )
    for stream in streams_to_update:
        stream.receive_window_update()

def spider_closed(self, spider: Spider, reason: str) -> None:
    if getattr(self.task, 'running', False):
        self.task.stop()

    rpm_final, ipm_final = self.calculate_final_stats(spider)
    self.stats.set_value("responses_per_minute", rpm_final)
    self.stats.set_value("items_per_minute", ipm_final)

def _get_request_cookies(self, jar: CookieJar, request: Request) -> Sequence[Cookie]:
    """
    Extract cookies from the Request.cookies attribute
    """
    if not request.cookies:
        return ()

    cookies = _to_verbose_cookies(request.cookies)
    scheme_is_https = urlparse_cached(request).scheme == "https"

    for cookie in cookies:
        cookie.setdefault("secure", scheme_is_https)

    formatted_cookies = filter(None, (self._format_cookie(c, request) for c in cookies))
    response = Response(request.url, headers={"Set-Cookie": formatted_cookies})

    return jar.make_cookies(response, request)

def to_bytes(
    text: str | bytes, encoding: str = "utf-8", errors: str = "strict"
) -> bytes:
    """Return the binary representation of ``text``. If ``text``
    is already a bytes object, return it as-is."""
    if isinstance(text, bytes):
        return text
    if not isinstance(text, str):
        raise TypeError(
            f"to_bytes must receive a str or bytes object, got {type(text).__name__}"
        )
    return text.encode(encoding, errors)

def item_completed(
    self, results: list[FileInfoOrError], item: Any, info: MediaPipeline.SpiderInfo
) -> Any:
    try:
        ItemAdapter(item)[self.images_result_field] = [x for ok, x in results if ok]
    except KeyError:
        pass
    return item

def _collect(result: Any) -> list[Any]:
    if isinstance(result, (AsyncGenerator, CoroutineType)):
        if isinstance(result, CoroutineType):
            result.close()
        raise TypeError(
            "Callbacks that return a coroutine or an asynchronous generator "
            "must be defined with async def to be supported by contracts."
        )
    return list(arg_to_iter(result))

def _chunk_iter(
    text: str, chunk_size: int
) -> Iterable[tuple[str, int]]:  # pragma: no cover
    offset = len(text)
    while offset > 0:
        offset -= chunk_size * 1024
        yield (text[max(offset, 0):], max(offset, 0))

def __init__(
    self,
    response: TextResponse | None = None,
    text: str | None = None,
    type: SelectorType | None = None,  # noqa: A002
    root: Any | None = _NOT_SET,
    **kwargs: Any,
):
    if response and text:
        raise ValueError(
            f"{self.__class__.__name__}.__init__() received both response and text"
        )

    type = self._determine_type(response, type, root)

    if text:
        response = _response_from_text(text, type)

    if response:
        text = self._process_response(response, type, kwargs)

    self.response = response

    if root is not _NOT_SET:
        kwargs["root"] = root

    super().__init__(text=text, type=type, **kwargs)

def _determine_type(self, response, type, root):
    if type is None and root is _NOT_SET:
        if isinstance(response, XmlResponse):
            return "xml"  # noqa: A001
        elif isinstance(response, JsonResponse):
            return "json"  # noqa: A001
        elif response is None or isinstance(response, HtmlResponse):
            return "html"  # noqa: A001
    return type

def _process_response(self, response, type, kwargs):
    if PARSEL_BODY_ENCODING_FIXED and type in ("html", "xml") and response.body:
        encoding = response.encoding
        if response._cached_ubody is None:
            kwargs["body"] = response.body
            kwargs["encoding"] = encoding
            return None
    kwargs.setdefault("base_url", get_base_url(response))
    return response.text

def _link_allowed(self, link: Link) -> bool:
    parsed_url = urlparse(link.url)

    conditions = [
        self.schemes and parsed_url.scheme not in self.schemes,
        self.allow_res and not _matches(link.url, self.allow_res),
        self.deny_res and _matches(link.url, self.deny_res),
        self.allow_domains and not url_is_from_any_domain(parsed_url, self.allow_domains),
        self.deny_domains and url_is_from_any_domain(parsed_url, self.deny_domains),
        self.deny_extensions and url_has_any_extension(parsed_url, self.deny_extensions)
    ]

    if any(conditions):
        return False

    return not self.restrict_text or _matches(link.text, self.restrict_text)

def _handle_downloader_output(
    self, result: Request | Response | Failure, request: Request
) -> Generator[Deferred[Any], Any, None]:
    if self._should_skip_due_to_failure(result):
        return

    if isinstance(result, Request):
        self.crawl(result)
        return

    yield from self._enqueue_scrape_safely(result, request)

def _should_skip_due_to_failure(self, result: Failure) -> bool:
    return (
        isinstance(result, Failure)
        and self._stop_mode == "fast"
        and result.check(
            DownloadCancelledError,
            CancelledError,
            asyncio.exceptions.CancelledError,
        )
    )

def _enqueue_scrape_safely(
    self, result: Request | Response | Failure, request: Request
) -> Generator[Deferred[Any], Any, None]:
    try:
        yield self.scraper.enqueue_scrape(result, request)
    except Exception:
        assert self.spider is not None
        logger.exception(
            "Error while enqueuing scrape", extra={"spider": self.spider}
        )

def _url_from_selector(sel: parsel.Selector) -> str:
    if isinstance(sel.root, str):
        return strip_html5_whitespace(sel.root)

    if not hasattr(sel.root, "tag") or sel.root.tag not in {"a", "link"}:
        tag = getattr(sel.root, "tag", None)
        raise _InvalidSelector(
            f"Only <a> and <link> elements are supported; got <{tag}>"
        )

    href = sel.root.get("href")
    if href is None:
        raise _InvalidSelector(f"<{sel.root.tag}> element has no href attribute: {sel}")

    return strip_html5_whitespace(href)

def _sync_dqs_state(self) -> None:
    if self._should_sync_dqs():
        self._reset_dqs_changes()
        self._write_dqs_state(self.dqdir, self.dqs.state())

def _should_sync_dqs(self) -> bool:
    return self._sync_every and getattr(self.dqs, "changed", False)

def _reset_dqs_changes(self) -> None:
    self.dqs.changed = False
    self._dqs_changes += 1
    if self._dqs_changes >= self._sync_every:
        self._dqs_changes = 0

def _deps(tox_ini: str, name: str) -> list[str]:
    section_content = _section(tox_ini, name)[1]
    block = re.search(r"^deps =\n((?:[ \t]+.*\n)*)", section_content, re.MULTILINE)
    if block:
        return [
            dep for line in block[1].splitlines()
            if (dep := re.sub(r"\s*#.*", "", line).strip())
        ]
    return []

def __next__(self) -> Deferred[Any]:
    if self.finished:
        raise StopIteration

    d = Deferred[Any]()
    self.waiting_deferreds.append(d)

    if self.anext_deferred is None:
        self._call_anext()

    return d

def from_spider(self, spider: Spider, results: TestResult) -> list[Request]:
    requests: list[Request] = []
    spider_cls = type(spider)

    for method in self.tested_methods_from_spidercls(spider_cls):
        bound_method = getattr(spider, method)
        try:
            requests.extend(self.from_method(bound_method, results))
        except Exception:
            case = _create_testcase(bound_method, "contract")
            results.addError(case, sys.exc_info())

    return requests

def from_body(self, body: bytes) -> type[Response]:
    """Try to guess the appropriate response based on the body content."""
    chunk = to_bytes(body[:5000])
    if not binary_is_text(chunk):
        return self.from_mimetype("application/octet-stream")

    lowercase_chunk = chunk.lower()
    if any(tag in lowercase_chunk for tag in [b"<html>", b"<!doctype html>"]):
        return self.from_mimetype("text/html")
    if b"<?xml" in lowercase_chunk:
        return self.from_mimetype("text/xml")

    return self.from_mimetype("text")

async def process_item(self, item: Any, spider: Spider | None = None) -> Any:
    info = self.spiderinfo
    requests = arg_to_iter(self.get_media_requests(item, info))
    coros = [self._process_request(r, info, item) for r in requests]

    if not coros:
        return self.item_completed([], item, info)

    if is_asyncio_available():
        results_asyncio = await asyncio.gather(*coros, return_exceptions=True)
        results = [
            (False, Failure(res)) if isinstance(res, BaseException) else (True, res)
            for res in results_asyncio
        ]
    else:
        results = await cast(
            "Deferred[list[FileInfoOrError]]",
            DeferredList(
                (deferred_from_coro(coro) for coro in coros), consumeErrors=True
            ),
        )

    return self.item_completed(results, item, info)

def _force_stop(self) -> None:
    if self.settings.getbool("TWISTED_REACTOR_ENABLED"):
        self._stop_reactor()
        return

    loop = self._reactorless_loop
    task = self._reactorless_main_task

    if loop and task:
        loop.call_soon_threadsafe(task.cancel)

def _parse_cachecontrol(self, r: Request | Response) -> dict[bytes, bytes | None]:
    if r in self._cc_parsed:
        return self._cc_parsed[r]

    cch = r.headers.get(b"Cache-Control", b"")
    assert cch is not None
    parsed = parse_cachecontrol(cch)

    if isinstance(r, Response):
        parsed = {k: v for k, v in parsed.items() if k not in self.ignore_response_cache_controls}

    self._cc_parsed[r] = parsed
    return parsed

def decode_robotstxt(
    robotstxt_body: bytes, spider: Spider | None, to_native_str_type: bool = False
) -> str:
    try:
        decode_method = to_unicode if to_native_str_type else lambda x: x.decode("utf-8-sig", errors="ignore")
        return decode_method(robotstxt_body)
    except UnicodeDecodeError:
        logger.warning(
            "Failure while parsing robots.txt. File either contains garbage or "
            "is in an encoding other than UTF-8, treating it as an empty file.",
            exc_info=sys.exc_info(),
            extra={"spider": spider},
        )
        return ""

def _dqpush(self, request: Request) -> bool:
    if self.dqs is None:
        return False

    try:
        self.dqs.push(request)
    except ValueError as e:
        if self.logunser:
            logger.warning(
                "Unable to serialize request: %(request)s - reason: %(reason)s - "
                "no more unserializable requests will be logged (stats being collected)",
                {"request": request, "reason": e},
                exc_info=True,
                extra={"spider": self.spider},
            )
            self.logunser = False
        if self.stats:
            self.stats.inc_value("scheduler/unserializable")
        return False
    finally:
        self._sync_dqs_state()

    return True

def _exporter_supported(self, format_: str) -> bool:
    if format_ in self.exporters:
        return True

    error_message = (
        "Unknown feed format: %(format)s" if format_ else
        "Feed format not set and it could not be inferred from the "
        "feed URI; set it explicitly with the 'format' key"
    )
    logger.error(error_message, {"format": format_} if format_ else {})
    return False

def deferred_from_coro(o: Awaitable[_T] | _T2) -> Deferred[_T] | _T2:
    """Convert a coroutine or other awaitable object into a Deferred,
    or return the object as is if it isn't a coroutine."""
    if isinstance(o, Deferred):
        return o
    if not inspect.isawaitable(o):
        return o
    if is_asyncio_available():
        return Deferred.fromFuture(asyncio.ensure_future(o))
    return Deferred.fromCoroutine(cast("Coroutine[Deferred[Any], Any, _T]", o))

def _spider_idle(self) -> None:
    """
    Called when a spider gets idle, i.e. when there are no remaining requests to download or schedule.
    It can be called multiple times. If a handler for the spider_idle signal raises a DontCloseSpider
    exception, the spider is not closed until the next loop and this function is guaranteed to be called
    (at least) once again. A handler can raise CloseSpider to provide a custom closing reason.
    """
    assert self.spider is not None  # typing
    expected_ex = (DontCloseSpider, CloseSpider)
    res = self.signals.send_catch_log(
        signals.spider_idle, spider=self.spider, dont_log=expected_ex
    )
    detected_ex = self._detect_exceptions(res, expected_ex)

    if DontCloseSpider in detected_ex:
        return

    if self.spider_is_idle():
        self._handle_spider_idle(detected_ex)

def _detect_exceptions(self, res, expected_ex):
    return {
        ex: x.value
        for _, x in res
        for ex in expected_ex
        if isinstance(x, Failure) and isinstance(x.value, ex)
    }

def _handle_spider_idle(self, detected_ex):
    default_reason = "start_error" if self._start_error else "finished"
    ex = detected_ex.get(
        CloseSpider,
        CloseSpider(reason=default_reason, error=self._start_error),
    )
    assert isinstance(ex, CloseSpider)  # typing
    _schedule_coro(self.close_spider_async(reason=ex.reason, error=ex.error))

def get_reactor_settings() -> dict[str, Any]:
    """Return a settings dict that works with the installed reactor.

    ``Crawler._apply_settings()`` checks that the installed reactor matches the
    settings, so tests that run the crawler in the current process may need to
    pass a correct :setting:`TWISTED_REACTOR` setting value when creating it.
    """
    if is_reactor_installed():
        return {"TWISTED_REACTOR": None} if not _is_asyncio_reactor_installed() else {}

    return {
        "TWISTED_REACTOR_ENABLED": False,
        "DOWNLOAD_HANDLERS": {
            "ftp": None,
            "http": "scrapy.core.downloader.handlers._aiohttp.AiohttpDownloadHandler",
            "https": "scrapy.core.downloader.handlers._aiohttp.AiohttpDownloadHandler",
        }
    }

def get_callback_from_rules(
    self, spider: Spider, response: Response
) -> CallbackT | str | None:
    if not getattr(spider, "rules", None):
        logger.error(
            "No CrawlSpider rules found in spider %(spider)r, "
            "please specify a callback to use for parsing",
            {"spider": spider.name},
        )
        return None

    for rule in spider.rules:  # type: ignore[attr-defined]
        if rule.link_extractor.matches(response.url):
            return rule.callback or "parse"

    return None

def is_cached_response_fresh(self, cachedresponse: Response, request: Request) -> bool:
    cc = self._parse_cachecontrol(cachedresponse)
    ccreq = self._parse_cachecontrol(request)

    if b"no-cache" in cc or b"no-cache" in ccreq:
        return False

    now = time()
    freshnesslifetime = self._compute_freshness_lifetime(cachedresponse, request, now)
    currentage = self._compute_current_age(cachedresponse, request, now)

    reqmaxage = self._get_max_age(ccreq)
    if reqmaxage is not None:
        freshnesslifetime = min(freshnesslifetime, reqmaxage)

    if currentage < freshnesslifetime:
        return True

    if b"max-stale" in ccreq and b"must-revalidate" not in cc:
        staleage = ccreq[b"max-stale"]
        if staleage is None or self._is_within_stale_age(currentage, freshnesslifetime, staleage):
            return True

    self._set_conditional_validators(request, cachedresponse)
    return False

def _is_within_stale_age(self, currentage: int, freshnesslifetime: int, staleage: bytes) -> bool:
    try:
        return currentage < freshnesslifetime + max(0, int(staleage))
    except ValueError:
        return False

def _schedule_reactorless_shutdown(self, *, mode: _StopMode, signum: int) -> None:
    loop = self._reactorless_loop
    if loop is None:
        return

    log_func = self._log_fast_shutdown if mode == "fast" else self._log_shutdown
    loop.call_soon_threadsafe(log_func, signum)

    def _create_shutdown_task() -> None:
        coro = self._shutdown_reactorless(mode=mode)
        try:
            loop.create_task(coro)
        except RuntimeError:
            coro.close()

    loop.call_soon_threadsafe(_create_shutdown_task)

def sitemap_urls_from_robots(
    robots_text: str | bytes,
    base_url: str | None = None,
) -> Iterable[str]:
    if isinstance(robots_text, bytes):
        yield from _sitemap_urls_from_bytes(robots_text, base_url)
    else:
        warnings.warn(
            "Passing `str` type as `robots_text` is deprecated, use `bytes`",
            ScrapyDeprecationWarning,
            stacklevel=2,
        )
        yield from _sitemap_urls_from_robots_str(robots_text, base_url)

def _sitemap_urls_from_bytes(robots_bytes: bytes, base_url: str | None) -> Iterable[str]:
    for line in BytesIO(robots_bytes):
        if line.lstrip()[:8].lower() == b"sitemap:":
            try:
                url = line.partition(b":")[2].strip().decode()
                yield urljoin(base_url or "", url)
            except UnicodeDecodeError:
                continue

async def stop_async(self, *, mode: _StopMode = "graceful") -> None:
    """Start a graceful stop of the crawler and complete when the crawler is stopped.

    .. versionadded:: 2.14
    """
    mode = _normalize_stop_mode(mode)
    was_crawling = self.crawling
    self.crawling = False

    if not was_crawling and mode == "graceful":
        return

    if mode == "force":
        await self._handle_force_stop()
        return

    if self._engine is None or (mode == "graceful" and not self._engine.running):
        return

    await self._attempt_engine_stop(mode)

async def _handle_force_stop(self):
    if self._force_stop_callback is not None:
        await ensure_awaitable(self._force_stop_callback())
    else:
        logger.warning(
            "Force stop requested, but no process-level force stop callback is available. Falling back to fast stop."
        )
        mode = "fast"

async def _attempt_engine_stop(self, mode):
    try:
        await self._engine.stop_async(mode=mode)
    except RuntimeError as exc:
        if str(exc) != "Engine not running":
            raise

def _embed_standard_shell(
    namespace: dict[str, Any] | None = None, banner: str = ""
) -> EmbedFuncT:
    """Start a standard python shell"""
    try:
        import readline
        import rlcompleter
        readline.parse_and_bind("tab:complete")
    except ImportError:
        pass

    @wraps(_embed_standard_shell)
    def wrapper(namespace: dict[str, Any] = namespace or {}, banner: str = "") -> None:
        code.interact(banner=banner, local=namespace)

    return wrapper

def close_connections(self) -> None:
    """Close all the HTTP/2 connections and remove them from pool."""
    for conn in self._connections.values():
        if conn.transport:
            conn.transport.abortConnection()

def start(
    self,
    url: str | None = None,
    request: Request | None = None,
    response: Response | None = None,
    spider: Spider | None = None,
    redirect: bool = True,
) -> None:
    signal.signal(signal.SIGINT, signal.SIG_IGN)

    if url:
        self.fetch(url, spider, redirect=redirect)
    elif request:
        self.fetch(request, spider)
    elif response:
        request = response.request
        self.populate_vars(response, request, spider)
    else:
        self.populate_vars()

    if self.code:
        print(eval(self.code, globals(), self.vars))  # noqa: S307
        return

    cfg = get_config()
    section, option = "settings", "shell"
    env = os.environ.get("SCRAPY_PYTHON_SHELL")
    shells = self._get_shells(env, cfg, section, option)
    start_python_console(
        self.vars, shells=shells, banner=self.vars.pop("banner", "")
    )

def _get_shells(self, env, cfg, section, option):
    shells = []
    if env:
        shells += env.strip().lower().split(",")
    elif cfg.has_option(section, option):
        shells += [cfg.get(section, option).strip().lower()]
    else:
        shells += DEFAULT_PYTHON_SHELLS.keys()
    shells += ["python"]
    return shells

def __init__(self, uri: str):
    if not uri.startswith("ftp://"):
        raise ValueError(f"Incorrect URI scheme in {uri}, expected 'ftp'")

    u = urlparse(uri)

    if not u.port or not u.hostname:
        raise ValueError("URI must include both hostname and port")

    self.host: str = u.hostname
    self.port: int = int(u.port or 21)

    if not self.FTP_USERNAME or not self.FTP_PASSWORD:
        raise ValueError("FTP_USERNAME and FTP_PASSWORD must be set")

    self.username: str = u.username or self.FTP_USERNAME
    self.password: str = u.password or self.FTP_PASSWORD
    self.basedir: str = u.path.rstrip("/")

def open(self, spider: Spider) -> IO[bytes]:
    path = spider.crawler.settings["FEED_TEMPDIR"]
    if path:
        path = Path(path)
        if not path.is_dir():
            raise OSError(f"Not a Directory: {path}")
    return NamedTemporaryFile(prefix="feed-", dir=path)

def process_spider_output(
    self,
    response: Response | None,
    result: Iterable[Any],
    spider: Spider | None = None,
) -> Iterable[Any]:
    return (o for o in map(lambda o: self._get_processed(o, response), result) if o is not None)

def set_environ(**kwargs: str) -> Iterator[None]:
    """Temporarily set environment variables inside the context manager and
    fully restore previous environment afterwards
    """
    original_env = {k: os.environ.get(k) for k in kwargs}
    os.environ.update(kwargs)
    try:
        yield
    finally:
        os.environ.update({k: v for k, v in original_env.items() if v is not None})
        for k in kwargs:
            if original_env[k] is None:
                del os.environ[k]

def __init__(self, uri: str, *, feed_options: dict[str, Any] | None = None):
    self.path: str = self._get_path_from_uri(uri)
    self.write_mode: OpenBinaryMode = self._determine_write_mode(feed_options)

def _get_path_from_uri(self, uri: str) -> str:
    return file_uri_to_path(uri) if uri.startswith("file:") else uri

def _determine_write_mode(self, feed_options: dict[str, Any] | None) -> OpenBinaryMode:
    return "wb" if (feed_options or {}).get("overwrite", False) else "ab"

def _iter_command_classes(module_name: str) -> Iterable[type[ScrapyCommand]]:
    # TODO: add `name` attribute to commands and merge this function with
    # scrapy.utils.spider.iter_spider_classes
    excluded_classes = {ScrapyCommand, BaseRunSpiderCommand}
    for module in walk_modules_iter(module_name):
        yield from (
            obj for obj in vars(module).values()
            if (
                inspect.isclass(obj)
                and issubclass(obj, ScrapyCommand)
                and obj.__module__ == module.__name__
                and obj not in excluded_classes
            )
        )

def spider_closed(self, spider: Spider) -> None:
    if not self.jobdir:
        return
    with Path(self.statefn).open("wb") as f:
        assert hasattr(spider, "state")  # set in spider_opened
        pickle.dump(spider.state, f, protocol=4)

def get_shell_embed_func(
    shells: Iterable[str] | None = None, known_shells: KnownShellsT | None = None
) -> EmbedFuncT | None:
    """Return the first acceptable shell-embed function
    from a given list of shell names.
    """
    shells = shells or DEFAULT_PYTHON_SHELLS.keys()
    known_shells = known_shells or DEFAULT_PYTHON_SHELLS.copy()

    for shell in shells:
        func = known_shells.get(shell)
        if func:
            try:
                return func()
            except ImportError:
                continue
    return None

def get_processed_request(self, request: Request, response: Response | None) -> Request | None:
    if response is not None:
        referrer = self.policy(response, request).referrer(response.url, request.url)
        if referrer:
            request.headers.setdefault("Referer", referrer)
    return request

def _requirements(tox_ini: str, name: str) -> list[str]:
    requirements = []
    for dep in _deps(tox_ini, name):
        match = re.fullmatch(r"\{\[(.+)\]deps\}", dep)
        if match:
            requirements.extend(_requirements(tox_ini, match[1]))
        else:
            requirements.append(dep)
    return requirements

def _is_authenticated(self, request: web.Request) -> bool:
    """Check if the request is authenticated with the correct Bearer token."""
    token = request.headers.get("Authorization", "").removeprefix("Bearer ")
    return bool(self._auth_token) and token.isascii() and hmac.compare_digest(token, self._auth_token)

def resolutionComplete(self) -> None:
    self.resolutionReceiver.resolutionComplete()
    if not self.addresses:
        return
    # Name resolution does not depend on the port, so cache entries are
    # kept port-agnostic and the requested port is set on cache hits.
    dnscache[self.hostName] = [
        _address_with_port(address, 0) for address in self.addresses
    ]

def _requests_to_follow(self, response: Response) -> Iterable[Request | None]:
    if not isinstance(response, HtmlResponse):
        return

    seen: set[Link] = set()
    response_rule_name = response.request.meta.get("rule_name") if response.request else None

    for rule_index, rule in enumerate(self._rules):
        if rule.from_rules is not None and response_rule_name not in rule.from_rules:
            continue

        links = rule.link_extractor.extract_links(response)
        new_links = (lnk for lnk in links if lnk not in seen)

        for link in cast("ProcessLinksT", rule.process_links)(new_links):
            seen.add(link)
            request = self._build_request(rule_index, link)
            yield cast("ProcessRequestT", rule.process_request)(request, response)

def post_process(self, output: list[Any]) -> None:
    for x in output:
        if not is_item(x):
            continue
        missing = [arg for arg in self.args if arg not in ItemAdapter(x)]
        if missing:
            raise ContractFail(f"Missing fields: {', '.join(missing)}")

def _job_dir(settings: BaseSettings) -> str | None:
    path: str | None = settings.get("JOBDIR")
    if path and not Path(path).exists():
        Path(path).mkdir(parents=True)
    return path

def start_python_console(
    namespace: dict[str, Any] | None = None,
    banner: str = "",
    shells: Iterable[str] | None = None,
) -> None:
    """Start Python console bound to the given namespace.
    Readline support and tab completion will be used on Unix, if available.
    """
    namespace = namespace or {}

    try:
        if (shell := get_shell_embed_func(shells)) is not None:
            shell(namespace=namespace, banner=banner)
    except SystemExit:
        pass

def _make_client(self, proxy_url: str | None = None) -> httpx.AsyncClient:
    proxy = self._configure_proxy(proxy_url)
    client = httpx.AsyncClient(
        cookies=NullCookieJar(),
        transport=httpx.AsyncHTTPTransport(
            verify=self._ssl_context,
            local_address=self._bind_host,
            http2=self._enable_h2,
            limits=self._limits,
            trust_env=False,
            proxy=proxy,
        ),
    )
    self._remove_default_headers(client)
    return client

def _configure_proxy(self, proxy_url: str | None) -> httpx.Proxy | None:
    if not proxy_url:
        return None
    proxy_ssl_context = (
        _make_insecure_ssl_ctx() if proxy_url.startswith("https:") and not self._verify_certificates else None
    )
    return httpx.Proxy(proxy_url, ssl_context=proxy_ssl_context)

def _remove_default_headers(self, client: httpx.AsyncClient) -> None:
    for header_name in ("accept", "accept-encoding", "user-agent"):
        client.headers.pop(header_name, None)

def is_asyncio_available() -> bool:
    """Check if it's possible to call asyncio code that relies on the asyncio event loop."""

    if _has_running_loop():
        return True

    if not is_reactor_installed():
        raise RuntimeError(
            "is_asyncio_available() called without an installed reactor"
            " or running asyncio loop."
        )

    return _is_asyncio_reactor_installed()

def _export_xml_field(self, name: str, serialized_value: Any, depth: int) -> None:
    def process_items():
        self._beautify_newline()
        for subname, value in serialized_value.items():
            self._export_xml_field(subname, value, depth=depth + 1)
        self._beautify_indent(depth=depth)

    def process_list():
        self._beautify_newline()
        for value in serialized_value:
            self._export_xml_field("value", value, depth=depth + 1)
        self._beautify_indent(depth=depth)

    def process_characters():
        if isinstance(serialized_value, str):
            self.xg.characters(serialized_value)
        else:
            self.xg.characters(str(serialized_value))

    self._beautify_indent(depth=depth)
    self.xg.startElement(name, AttributesImpl({}))

    if hasattr(serialized_value, "items"):
        process_items()
    elif is_listlike(serialized_value):
        process_list()
    else:
        process_characters()

    self.xg.endElement(name)
    self._beautify_newline()

def binary_is_text(data: bytes) -> bool:
    """Returns ``True`` if the given ``data`` argument (a ``bytes`` object)
    does not contain unprintable control characters.
    """
    if isinstance(data, bytes):
        return all(c not in _BINARYCHARS for c in data)
    raise TypeError(f"data must be bytes, got '{type(data).__name__}'")

async def close_async(self, *, reason: str = "shutdown", error: bool = False) -> None:
    """
    Gracefully close the execution engine.
    If it has already been started, stop it. In all cases, close the spider and the downloader.
    """
    if self.running:
        await self.stop_async()  # will also close spider and downloader
    elif self.spider is not None:
        await self.close_spider_async(reason=reason, error=error)  # will also close downloader
    else:
        self.downloader.close()

    if self._state not in (_EngineState.STOPPING, _EngineState.STOPPED):
        self._transition_to(_EngineState.STOPPED)

def _extract_links(
    self,
    selector: Selector,
    response_url: str,
    response_encoding: str,
    base_url: str,
) -> list[Link]:
    links: list[Link] = []
    for el, _, attr_val in self._iter_links(selector.root):
        attr_val = self._process_attribute(attr_val, base_url)
        if attr_val is None:
            continue

        url = self.process_attr(attr_val)
        if url is None:
            continue

        url = self._safe_url(url, response_encoding)
        if url is None:
            continue

        url = urljoin(response_url, url)
        link = Link(
            url,
            _collect_string_content(el) or "",
            nofollow=rel_has_nofollow(el.get("rel")),
        )
        links.append(link)
    return self._deduplicate_if_needed(links)

def _process_attribute(self, attr_val: str, base_url: str) -> str | None:
    try:
        if self.strip:
            attr_val = strip_html5_whitespace(attr_val)
        return urljoin(base_url, attr_val)
    except ValueError:
        return None

def _safe_url(self, url: str, encoding: str) -> str | None:
    try:
        return safe_url_string(url, encoding=encoding)
    except ValueError:
        logger.debug(f"Skipping extraction of link with bad URL {url!r}")
        return None

def from_args(
    self,
    headers: Mapping[bytes, bytes] | None = None,
    url: str | None = None,
    filename: str | None = None,
    body: bytes | None = None,
) -> type[Response]:
    """Guess the most appropriate Response class based on
    the given arguments."""
    if headers is not None:
        return self.from_headers(headers)
    if url is not None:
        return self.from_filename(url)
    if filename is not None:
        return self.from_filename(filename)
    if body is not None:
        return self.from_body(body)
    return Response

def process_options(self, args: list[str], opts: argparse.Namespace) -> None:
    """Set settings based on the command line options."""
    assert self.settings is not None
    self._set_settings_from_options(opts)
    self._handle_logging_options(opts)
    self._write_pidfile(opts.pidfile)
    self._setup_debugger(opts.pdb)

def _set_settings_from_options(self, opts: argparse.Namespace) -> None:
    try:
        self.settings.setdict(arglist_to_dict(opts.set), priority="cmdline")
    except ValueError:
        raise UsageError(
            "Invalid -s value, use -s NAME=VALUE", print_help=False
        ) from None

def _handle_logging_options(self, opts: argparse.Namespace) -> None:
    if opts.logfile or opts.loglevel:
        self.settings.set("LOG_ENABLED", True, priority="cmdline")
    if opts.logfile:
        self.settings.set("LOG_FILE", opts.logfile, priority="cmdline")
    if opts.loglevel:
        self.settings.set("LOG_LEVEL", opts.loglevel, priority="cmdline")
    if opts.nolog:
        self.settings.set("LOG_ENABLED", False, priority="cmdline")

def _write_pidfile(self, pidfile: str) -> None:
    if pidfile:
        Path(pidfile).write_text(
            str(os.getpid()) + os.linesep, encoding="utf-8"
        )

def _setup_debugger(self, pdb_option: bool) -> None:
    if pdb_option:
        try:
            import ipdb  # noqa: T100,PLC0415
        except ImportError:
            pass
        else:
            sys.modules["pdb"] = ipdb
        logging.root.addHandler(_PdbHandler(level=logging.ERROR))

def __init__(self, obj: Response | str | bytes):
    self._ptr: int = 0
    self._text, self.encoding = self._extract_text_and_encoding(obj)
    self._is_unicode: bool = isinstance(self._text, str)
    self._is_first_read: bool = True

def _extract_text_and_encoding(self, obj: Response | str | bytes) -> tuple[str | bytes, str]:
    if isinstance(obj, TextResponse):
        return obj.body, obj.encoding
    if isinstance(obj, Response):
        return obj.body, "utf-8"
    return obj, "utf-8"

def _next_slot(self, stats: list[tuple[int, str]], *, update_state: bool) -> str:
    last = self._last_selected_slot
    min_active = float('inf')
    best_slot = None
    best_slot_after_last = None

    for active, slot in stats:
        if active < min_active:
            min_active = active
            best_slot = slot
            best_slot_after_last = slot if last is not None and slot > last else None
        elif active == min_active:
            if slot < best_slot:
                best_slot = slot
            if last is not None and slot > last and (best_slot_after_last is None or slot < best_slot_after_last):
                best_slot_after_last = slot

    slot = best_slot_after_last if best_slot_after_last is not None else best_slot
    if update_state:
        self._last_selected_slot = slot
    return slot

async def download_request(self, request: Request) -> Response:
    self._check_proxy_support(request)
    self._log_unsupported_bindaddress(request)

    timeout = request.meta.get("download_timeout", self._DEFAULT_CONNECT_TIMEOUT)
    start_time = time.monotonic()

    async with self._make_request(request, timeout) as response:
        request.meta["download_latency"] = time.monotonic() - start_time
        return await self._read_response(response, request)

def _check_proxy_support(self, request: Request):
    if not self.supports_proxies and request.meta.get("proxy"):
        raise NotImplementedError(f"{type(self).__name__} doesn't support proxies.")

def _log_unsupported_bindaddress(self, request: Request):
    if not self.supports_per_request_bindaddress and request.meta.get("bindaddress"):
        logger.error(
            f"The 'bindaddress' request meta key is not supported by"
            f" {type(self).__name__} and will be ignored."
        )

def _build_redirect_request(
    self, source_request: Request, response: Response, *, url: str, **kwargs: Any
) -> Request:
    redirect_request = source_request.replace(
        url=url,
        **kwargs,
        cls=None,
        cookies=None,
    )

    self._handle_scheme_proxy(source_request, redirect_request)
    self._handle_sensitive_headers(source_request, redirect_request)

    self.handle_referer(redirect_request, response)

    return redirect_request

def _handle_scheme_proxy(self, source_request: Request, redirect_request: Request):
    if "_scheme_proxy" in redirect_request.meta:
        source_scheme = urlparse_cached(source_request).scheme
        redirect_scheme = urlparse_cached(redirect_request).scheme
        if source_scheme != redirect_scheme:
            redirect_request.meta.pop("_scheme_proxy")
            redirect_request.meta.pop("proxy", None)
            redirect_request.meta.pop("_auth_proxy", None)
            redirect_request.headers.pop(b"Proxy-Authorization", None)

def _handle_sensitive_headers(self, source_request: Request, redirect_request: Request):
    has_cookie_header = "Cookie" in redirect_request.headers
    has_authorization_header = "Authorization" in redirect_request.headers

    if has_cookie_header or has_authorization_header:
        default_ports = {"http": 80, "https": 443}

        parsed_source = urlparse_cached(source_request)
        source_scheme, source_host, source_port = (
            parsed_source.scheme,
            parsed_source.hostname,
            parsed_source.port or default_ports.get(parsed_source.scheme),
        )

        parsed_redirect = urlparse_cached(redirect_request)
        redirect_scheme, redirect_host, redirect_port = (
            parsed_redirect.scheme,
            parsed_redirect.hostname,
            parsed_redirect.port or default_ports.get(parsed_redirect.scheme),
        )

        if has_cookie_header and (
            redirect_scheme not in {source_scheme, "https"} or source_host != redirect_host
        ):
            del redirect_request.headers["Cookie"]

        if has_authorization_header and (
            source_scheme != redirect_scheme
            or source_host != redirect_host
            or source_port != redirect_port
        ):
            del redirect_request.headers["Authorization"]

def configure_logging(
    settings: Settings | dict[str, Any] | None = None,
    install_root_handler: bool | None = None,
) -> None:
    """
    Initialize logging defaults for Scrapy.
    """
    settings = Settings(settings) if isinstance(settings, dict) or settings is None else settings

    install_root_handler = (
        settings.getbool("LOG_INSTALL_ROOT_HANDLER")
        if install_root_handler is None
        else _warn_deprecated_install_root_handler()
    )

    if not sys.warnoptions:
        logging.captureWarnings(True)

    twisted_log.PythonLoggingObserver("twisted").start()
    dictConfig(DEFAULT_LOGGING)

    if settings.getbool("LOG_STDOUT"):
        sys.stdout = StreamLogger(logging.getLogger("stdout"))

    if install_root_handler:
        install_scrapy_root_handler(settings)


def _warn_deprecated_install_root_handler():
    warnings.warn(
        "The install_root_handler parameter is deprecated. Set the "
        "LOG_INSTALL_ROOT_HANDLER setting instead.",
        category=ScrapyDeprecationWarning,
        stacklevel=2,
    )
    return True

def _get_agent(self, request: Request, timeout: float | None) -> H2Agent:
    from twisted.internet import reactor

    if self._is_proxy_request(request):
        raise NotImplementedError(f"{type(self).__name__} doesn't support proxies.")

    bind_address = self._get_bind_address(request)

    return H2Agent(
        reactor=reactor,
        context_factory=self._context_factory,
        connect_timeout=timeout,
        bind_address=bind_address,
        pool=self._pool,
    )

def _is_proxy_request(self, request: Request) -> bool:
    return bool(request.meta.get("proxy"))

def _get_bind_address(self, request: Request) -> str:
    bind_address = request.meta.get("bindaddress") or self._bind_address
    return normalize_bind_address(bind_address)

def load_settings(self, settings: Settings) -> None:
    """Load add-ons and configurations from a settings object and apply them.

    This will load the add-on for every add-on path in the
    ``ADDONS`` setting and execute their ``update_settings`` methods.

    :param settings: The :class:`~scrapy.settings.Settings` object from \
        which to read the add-on configuration
    :type settings: :class:`~scrapy.settings.Settings`
    """
    addon_paths = build_component_list(settings["ADDONS"])
    for clspath in addon_paths:
        self._load_and_configure_addon(clspath, settings)
    self._log_enabled_addons()

def _load_and_configure_addon(self, clspath, settings):
    try:
        addoncls = load_object(clspath)
        addon = build_from_crawler(addoncls, self.crawler)
        if hasattr(addon, "update_settings"):
            addon.update_settings(settings)
        self.addons.append(addon)
    except NotConfigured as e:
        self._log_disabled_addon(clspath, e)

def _log_disabled_addon(self, clspath, exception):
    if exception.args:
        logger.warning(
            "Disabled %(clspath)s: %(eargs)s",
            {"clspath": clspath, "eargs": exception.args[0]},
            extra={"crawler": self.crawler},
        )

def _log_enabled_addons(self):
    logger.info(
        "Enabled addons:\n%(addons)s",
        {"addons": self.addons},
        extra={"crawler": self.crawler},
    )

def getlist(
    self, key: str | bytes, def_val: _RawValue | Iterable[_RawValue] | None = None
) -> list[bytes]:
    value = dict.get(self, self.normkey(key))
    if value is not None:
        return cast("list[bytes]", value)
    return self.normvalue(def_val) if def_val is not None else []

def _get_reactorless_loop(self) -> asyncio.AbstractEventLoop:
    assert isinstance(self.crawler_process, AsyncCrawlerProcess), "Invalid crawler process"
    return self.crawler_process._reactorless_loop

def _version(item: str) -> str:
    version_map = {
        "libxml2": lambda: ".".join(map(str, lxml.etree.LIBXML_VERSION)),
        "platform": platform.platform,
        "pyopenssl": _get_openssl_version,
        "python": lambda: sys.version.replace("\n", "- ")
    }
    return version_map.get(item.lower(), lambda: version(item))()

def _start_asyncio(self, stop_after_crawl: bool, install_signal_handlers: bool) -> None:
    loop = self._reactorless_loop
    assert loop

    self._reactorless_main_task = (
        loop.create_task(self.join()) if stop_after_crawl else loop.create_future()
    )
    self._stop_after_crawl = stop_after_crawl

    try:
        self._run_loop(install_signal_handlers)
    except asyncio.CancelledError:
        pass
    finally:
        self._close_loop()

def _warn_if_feeds_unused(self, sender: Crawler, **kwargs: Any) -> None:
    feeds = sender.settings.getdict("FEEDS")
    feed_exporter_enabled = sender.get_extension(FeedExporter) is not None
    if feeds and not feed_exporter_enabled:
        logger.warning(
            "The FeedExporter extension is not enabled, so no item will be "
        )

def run(self, args: list[str], opts: argparse.Namespace) -> None:
    if opts.verbose:
        self._print_verbose_versions()
    else:
        self._print_scrapy_version()

def _print_verbose_versions(self) -> None:
    versions = get_versions()
    width = max(len(name) for name, _ in versions)
    for name, version in versions:
        print(f"{name:<{width}} : {version}")

def _print_scrapy_version(self) -> None:
    print(f"Scrapy {scrapy.__version__}")

def _serialize_value(self, value: Any) -> Any:
    if isinstance(value, Item):
        return self.export_item(value)
    if isinstance(value, (str, bytes)):
        return to_unicode(value, encoding=self.encoding)
    if is_item(value):
        return dict(self._serialize_item(value))
    if is_listlike(value):
        return [self._serialize_value(v) for v in value]
    return value

def iter_spider_classes(module: ModuleType) -> Iterable[type[Spider]]:
    """Return an iterator over all spider classes defined in the given module
    that can be instantiated (i.e. which have name)
    """
    def is_valid_spider_class(obj):
        return (
            inspect.isclass(obj)
            and issubclass(obj, Spider)
            and obj.__module__ == module.__name__
            and getattr(obj, "name", None)
        )

    return (obj for obj in vars(module).values() if is_valid_spider_class(obj))

def data_path(path: str | os.PathLike[str], createdir: bool = False) -> str:
    """
    Return the given path joined with the .scrapy data directory.
    If given an absolute path, return it unmodified.
    """
    path_obj = Path(path)
    if not path_obj.is_absolute():
        base_dir = project_data_dir() if inside_project() else ".scrapy"
        path_obj = Path(base_dir, path)
    if createdir:
        path_obj.mkdir(parents=True, exist_ok=True)
    return str(path_obj)

async def _async_chain(
    *iterables: Iterable[_T] | AsyncIterator[_T],
) -> AsyncIterator[_T]:
    for iterable in iterables:
        async for item in as_async_generator(iterable):
            yield item

def failure_to_exc_info(
    failure: Failure,
) -> tuple[type[BaseException], BaseException, TracebackType | None] | None:
    """Extract exc_info from Failure instances"""
    if not isinstance(failure, Failure):
        return None

    assert failure.type
    assert failure.value
    return (
        failure.type,
        failure.value,
        cast("TracebackType | None", failure.getTracebackObject()),
    )

def __subclasscheck__(cls, subclass: type) -> bool:
    required_methods = ["has_pending_requests", "enqueue_request", "next_request"]
    return all(callable(getattr(subclass, method, None)) for method in required_methods)

def project_data_dir(project: str = "default") -> str:
    """Return the current project data dir, creating it if it doesn't exist"""
    if not inside_project():
        raise NotConfigured("Not inside a project")

    cfg = get_config()
    if cfg.has_option(DATADIR_CFG_SECTION, project):
        data_dir = Path(cfg.get(DATADIR_CFG_SECTION, project))
    else:
        scrapy_cfg = closest_scrapy_cfg()
        if not scrapy_cfg:
            raise NotConfigured("Unable to find scrapy.cfg file to infer project data dir")
        data_dir = (Path(scrapy_cfg).parent / ".scrapy").resolve()

    data_dir.mkdir(parents=True, exist_ok=True)
    return str(data_dir)

def _callback(self, result: _T) -> None:
    self.anext_deferred = None
    self.on_value()

    callable_result = self.callable(result, *self.callable_args, **self.callable_kwargs)
    d = self.waiting_deferreds.popleft()

    if isinstance(callable_result, Deferred):
        callable_result.chainDeferred(d)
    else:
        d.callback(None)

    if self.waiting_deferreds:
        self._call_anext()

def _add_middleware(self, mw: Any) -> None:
    self._add_method(mw, "process_spider_input", append=True)
    self._add_method(mw, "process_start", append=False)

    process_spider_output = self._get_process_spider_output(mw)
    self._add_method(mw, "process_spider_output", append=False, method=process_spider_output)

    process_spider_exception = getattr(mw, "process_spider_exception", None)
    self._add_method(mw, "process_spider_exception", append=False, method=process_spider_exception)

def _add_method(self, mw, method_name, append, method=None):
    method = method or getattr(mw, method_name, None)
    if method:
        collection = self.methods[method_name]
        if append:
            collection.append(method)
        else:
            collection.appendleft(method)
        self._check_mw_method_spider_arg(method)

def get_header_size(
    headers: dict[str, list[str | bytes] | tuple[str | bytes, ...]],
) -> int:
    size = sum(
        len(b": ") + len(key) + len(v)
        for key, value in headers.items()
        if isinstance(value, (list, tuple))
        for v in value
    )
    return size + len(b"\r\n") * (len(headers) - 1)

def _genspider(
    self,
    module: str,
    name: str,
    url: str,
    template_name: str,
    template_file: str | os.PathLike[str],
) -> Path:
    """Generate the spider module, based on the given template"""
    assert self.settings is not None
    tvars = self._generate_template_variables(module, name, url, template_name)
    spiders_dir, spiders_module = self._get_spiders_dir_and_module()
    spider_file = f"{spiders_dir / module}.py"
    shutil.copyfile(template_file, spider_file)
    render_templatefile(spider_file, **tvars)
    self._print_creation_message(name, template_name, spiders_module, module)
    return Path(spider_file)

def _get_spiders_dir_and_module(self):
    if self.settings.get("NEWSPIDER_MODULE"):
        spiders_module = import_module(self.settings["NEWSPIDER_MODULE"])
        assert spiders_module.__file__
        spiders_dir = Path(spiders_module.__file__).parent.resolve()
    else:
        spiders_module = None
        spiders_dir = Path()
    return spiders_dir, spiders_module

def _print_creation_message(self, name, template_name, spiders_module, module):
    print(
        f"Created spider {name!r} using template {template_name!r} ",
        end=("" if spiders_module else "\n"),
    )
    if spiders_module:
        print(f"in module:\n  {spiders_module.__name__}.{module}")

def _get_client(self, proxy_url: str | None) -> httpx.AsyncClient:
    if proxy_url is not None:
        if cached := self._proxy_clients.get(proxy_url):
            return cached
        self._proxy_clients[proxy_url] = client = self._make_client(proxy_url)
        return client
    return self._default_client

def _make_ssl_context(settings: BaseSettings) -> ssl.SSLContext:
    """Create an :class:`ssl.SSLContext` instance according to the settings.

    It's intended to be used in an HTTPS download handler.
    """

    tls_min_ver, tls_max_ver = _get_tls_version_limits(
        settings, _STDLIB_VERSION_MAP.__getitem__
    )
    ciphers_setting: str | None = settings["DOWNLOADER_CLIENT_TLS_CIPHERS"]
    verify_setting = settings.getbool("DOWNLOAD_VERIFY_CERTIFICATES")

    ctx = ssl.SSLContext(ssl.PROTOCOL_TLS_CLIENT)
    ctx.check_hostname = verify_setting
    ctx.verify_mode = ssl.CERT_REQUIRED if verify_setting else ssl.CERT_NONE

    if verify_setting:
        ctx.load_default_certs()

    if tls_min_ver is not None:
        ctx.minimum_version = tls_min_ver
    if tls_max_ver is not None:
        ctx.maximum_version = tls_max_ver
    if ciphers_setting:
        ctx.set_ciphers(ciphers_setting)
    if keylog_filename := _get_keylog_filename():
        ctx.keylog_filename = keylog_filename

    return ctx

def getdictorlist(
    self,
    name: str,
    default: dict[Any, Any] | list[Any] | tuple[Any, ...] | None = None,
) -> dict[Any, Any] | list[Any]:
    """Get a setting value as either a :class:`dict` or a :class:`list`."""
    value = self.get(name, default)
    if value is None:
        return {}

    if isinstance(value, str):
        return self._parse_string_value(name, value)

    if isinstance(value, tuple):
        return list(value)

    if isinstance(value, (dict, list)):
        return copy.deepcopy(value)

    raise ValueError(
        f"Setting '{name}' must be a dict, list, tuple, or string, "
        f"got {type(value).__name__}: {value!r}"
    )

def _parse_string_value(self, name: str, value: str) -> dict[Any, Any] | list[Any]:
    try:
        value_loaded = json.loads(value)
        if isinstance(value_loaded, (dict, list)):
            return value_loaded
        raise ValueError
    except ValueError:
        return value.split(",")

def page_count(self, response: Response, request: Request, spider: Spider) -> None:
    self.counter["pagecount"] += 1
    self.counter["pagecount_since_last_item"] += 1

    if self.counter["pagecount"] == self.close_on["pagecount"]:
        self._close_spider("closespider_pagecount")
    elif self.close_on["pagecount_no_item"] and (
        self.counter["pagecount_since_last_item"] >= self.close_on["pagecount_no_item"]
    ):
        self._close_spider("closespider_pagecount_no_item")

async def _wait_for_download(self, slot: Slot, request: Request, queue_dfd: Deferred[Response]) -> None:
    try:
        response = await self._download(slot, request)
    except Exception:
        if not queue_dfd.called:
            queue_dfd.errback(Failure())
    else:
        queue_dfd.callback(response)

def _get_form(
    response: TextResponse,
    formname: str | None,
    formid: str | None,
    formnumber: int,
    formxpath: str | None,
) -> FormElement:
    """Find the wanted form element within the given response."""
    root = response.selector.root
    forms = root.xpath("//form")
    if not forms:
        raise ValueError(f"No <form> element found in {response}")

    def find_form_by_attribute(attribute: str, value: str) -> FormElement | None:
        f = root.xpath(f'//form[@{attribute}="{value}"]')
        return cast("FormElement", f[0]) if f else None

    if formname:
        form = find_form_by_attribute("name", formname)
        if form:
            return form

    if formid:
        form = find_form_by_attribute("id", formid)
        if form:
            return form

    if formxpath:
        nodes = root.xpath(formxpath)
        if nodes:
            el = nodes[0]
            while el:
                if el.tag == "form":
                    return cast("FormElement", el)
                el = el.getparent()
        raise ValueError(f"No <form> element found with {formxpath}")

    try:
        return cast("FormElement", forms[formnumber])
    except IndexError:
        raise IndexError(f"Form number {formnumber} not found in {response}") from None

def _pop_command_name(argv: list[str]) -> str | None:
    for arg in argv[1:]:
        if not arg.startswith("-"):
            argv.remove(arg)
            return arg
    return None

def render_templatefile(path: str | PathLike[str], **kwargs: Any) -> None:
    path_obj = Path(path)
    raw = path_obj.read_text("utf8")
    content = string.Template(raw).substitute(**kwargs)

    if path_obj.suffix == ".tmpl":
        render_path = path_obj.with_suffix("")
        path_obj.rename(render_path)
    else:
        render_path = path_obj

    render_path.write_text(content, "utf8")

def _process_spider_exception(
    self,
    response: Response,
    exception: Exception,
    start_index: int = 0,
) -> MutableAsyncChain[_T]:
    if isinstance(exception, _InvalidOutput):
        raise exception

    method_list = islice(self.methods["process_spider_exception"], start_index, None)
    for method_index, method in enumerate(method_list, start=start_index):
        if method is None:
            continue

        result = self._invoke_method(method, response, exception)

        if isinstance(result, (Iterable, AsyncIterator)):
            return self._handle_iterable_result(response, result, method_index)

        if result is not None:
            self._raise_invalid_output(method, result)

    self._mark_exception_unhandled(exception)
    raise exception

def _invoke_method(self, method, response, exception):
    if method in self._mw_methods_requiring_spider:
        return method(response=response, exception=exception, spider=self._spider)
    return method(response=response, exception=exception)

def _handle_iterable_result(self, response, result, method_index):
    if isinstance(result, Iterable):
        result = as_async_generator(result)
    return self._process_spider_output(response, result, method_index + 1)

def _raise_invalid_output(self, method, result):
    msg = (
        f"{global_object_name(method)} must return None "
        f"or an iterable, got {type(result)}"
    )
    raise _InvalidOutput(msg)

def _mark_exception_unhandled(self, exception):
    with suppress(AttributeError):
        exception._spidermw_unhandled = True  # type: ignore[attr-defined]

def ensure_awaitable(o: _T | Awaitable[_T], _warn: str | None = None) -> Awaitable[_T]:
    """Convert any value to an awaitable object.

    For a :class:`~twisted.internet.defer.Deferred` object, use
    :func:`maybe_deferred_to_future` to wrap it into a suitable object. For an
    awaitable object of a different type, return it as is. For any other
    value, return a coroutine that completes with that value.

    .. versionadded:: 2.14
    """
    if isinstance(o, Deferred):
        if _warn:
            warnings.warn(
                f"{_warn} returned a Deferred, this is deprecated."
                f" Please refactor this function to return a coroutine.",
                ScrapyDeprecationWarning,
                stacklevel=2,
            )
        return maybe_deferred_to_future(o)

    if not inspect.isawaitable(o):
        async def coro() -> _T:
            return o
        return coro()

    return o

def __init__(self, contracts: Iterable[type[Contract]]):
    for contract in contracts:
        if self._overrides_hooks(contract):
            self._warn_deprecated_override(contract)
        self.contracts[contract.name] = contract

def _overrides_hooks(self, contract: type[Contract]) -> bool:
    return (
        contract.add_pre_hook is not Contract.add_pre_hook
        or contract.add_post_hook is not Contract.add_post_hook
    )

def _warn_deprecated_override(self, contract: type[Contract]) -> None:
    warnings.warn(
        f"{contract.__module__}.{contract.__qualname__} overrides"
        " Contract.add_pre_hook() or Contract.add_post_hook(), which is"
        " deprecated. Define pre_process() or post_process() instead."
        " Contracts that override those methods do not support"
        " asynchronous callbacks.",
        ScrapyDeprecationWarning,
        stacklevel=2,
    )

def __setitem__(self, key: _KT, value: _VT) -> None:
    if self.limit is not None and self.limit > 0 and key not in self:
        while len(self) >= self.limit:
            self.popitem(last=False)
    super().__setitem__(key, value)

def __get__(self, instance: Crawler | None, owner: type[Crawler]) -> _LateAttribute[_T] | _T:
    if instance is None:
        return self
    value: _T | None = getattr(instance, self._private_name)
    if value is not None:
        return value
    raise RuntimeError(
        f"Crawler.{self._name} is not set yet. It is set when the "
        "crawl starts, so it can only be used from then on, e.g. "
        "from the spider_opened signal handler onwards."
    )

def item_completed(self, results: list[FileInfoOrError], item: Any, info: SpiderInfo) -> Any:
    """Called per item when all media requests have been processed"""
    if not self.LOG_FAILED_RESULTS:
        return item

    for ok, value in results:
        if ok or _media_request_filtered(value):
            continue
        assert isinstance(value, Failure)
        logger.error(
            "%(class)s found errors processing %(item)s",
            {"class": self.__class__.__name__, "item": item},
            exc_info=failure_to_exc_info(value),
            extra={"spider": info.spider},
        )
    return item

def _report_crawl_errors(
    crawl: Awaitable[None], spidername: str, result: TextTestResult
) -> None:
    """Make an exception that stops *crawl* before its contracts can run show
    up as an error in *result*, instead of being silently discarded."""

    class CrawlTestCase(TestCase):
        runTest = staticmethod(lambda: None)

        def __str__(self) -> str:
            return f"[{spidername}] crawl"

    def report(exception: BaseException) -> None:
        result.addError(
            CrawlTestCase(),
            (type(exception), exception, exception.__traceback__),  # type: ignore[arg-type]
        )

    def handle_deferred(failure: Failure) -> None:
        assert failure.value is not None
        report(failure.value)

    def handle_task(task: asyncio.Task[None]) -> None:
        if not task.cancelled() and (exception := task.exception()) is not None:
            report(exception)

    if isinstance(crawl, Deferred):
        crawl.addErrback(handle_deferred)
    else:
        assert isinstance(crawl, asyncio.Task)
        crawl.add_done_callback(handle_task)

def _clean_req(
    self, request: Request, method: Callable[..., Any], results: TestResult
) -> None:
    """stop the request from returning objects and records any errors"""

    cb = request.callback
    assert cb is not None

    def create_cb_wrapper(is_async: bool):
        if is_async:
            @wraps(cb)
            async def cb_wrapper(response: Response, **cb_kwargs: Any) -> None:
                try:
                    await _collect_async(cb(response, **cb_kwargs))
                except Exception:
                    case = _create_testcase(method, "callback")
                    results.addError(case, sys.exc_info())
        else:
            @wraps(cb)
            def cb_wrapper(response: Response, **cb_kwargs: Any) -> None:
                try:
                    _collect(cb(response, **cb_kwargs))
                except Exception:
                    case = _create_testcase(method, "callback")
                    results.addError(case, sys.exc_info())
        return cb_wrapper

    request.callback = create_cb_wrapper(_is_async(cb))

    def eb_wrapper(failure: Failure) -> None:
        case = _create_testcase(method, "errback")
        exc_info = failure.type, failure.value, failure.getTracebackObject()
        results.addError(case, exc_info)  # type: ignore[arg-type]

    request.errback = eb_wrapper

def _get_handler(self, scheme: str) -> DownloadHandlerProtocol | None:
    """Lazy-load the downloadhandler for a scheme
    only on the first request for that scheme.
    """
    if scheme in self._handlers:
        return self._handlers[scheme]
    if scheme in self._notconfigured or scheme not in self._schemes:
        self._notconfigured.setdefault(scheme, "no handler available for that scheme")
        return None
    return self._load_handler(scheme)

def _get_tag_name(elem: lxml.etree._Element) -> str:
    tag = elem.tag
    if isinstance(tag, str):
        return tag.partition("}")[2] or tag
    return ""

def __init__(self, *args: Any, **kwargs: Any):
    super().__init__(*args, **kwargs)

    if len(self.args) not in {1, 2, 3}:
        raise ValueError(
            f"Incorrect argument quantity: expected 1, 2 or 3, got {len(self.args)}"
        )

    self.obj_name = self.args[0] or None
    self.obj_type_verifier = self.object_type_verifiers[self.obj_name]

    self.min_bound: float = int(self.args[1]) if len(self.args) > 1 else 1
    self.max_bound: float = int(self.args[2]) if len(self.args) > 2 else float("inf")

def __init__(self, uri: str):
    from google.cloud import storage  # noqa: PLC0415

    client = storage.Client(project=self.GCS_PROJECT_ID)
    bucket_name, prefix = uri[5:].split("/", 1)
    self.bucket = client.bucket(bucket_name)
    self.prefix: str = prefix
    self._check_permissions(bucket_name)

def _check_permissions(self, bucket_name: str):
    permissions = self.bucket.test_iam_permissions(
        ["storage.objects.get", "storage.objects.create"]
    )
    self._log_permission_warnings(permissions, bucket_name)

def _log_permission_warnings(self, permissions, bucket_name: str):
    if "storage.objects.get" not in permissions:
        logger.warning(
            "No 'storage.objects.get' permission for GCS bucket %(bucket)s. "
            "Checking if files are up to date will be impossible. Files will be downloaded every time.",
            {"bucket": bucket_name},
        )
    if "storage.objects.create" not in permissions:
        logger.error(
            "No 'storage.objects.create' permission for GCS bucket %(bucket)s. Saving files will be impossible!",
            {"bucket": bucket_name},
        )

def is_reactorless() -> bool:
    """Check if we are running in the reactorless mode."""
    if not is_reactor_installed():
        if _has_running_loop():
            return True
        raise RuntimeError(
            "is_reactorless() called without an installed reactor or running asyncio loop."
        )
    return False

def open(self, spider: Spider) -> IO[bytes]:
    dirname = Path(self.path).parent
    dirname.mkdir(parents=True, exist_ok=True)
    return Path(self.path).open(self.write_mode)

async def download_request_async(self, request: Request) -> Response:
    scheme = urlparse_cached(request).scheme
    handler = self._get_handler(scheme)

    if not handler:
        raise NotSupported(
            f"Unsupported URL scheme '{scheme}': {self._notconfigured[scheme]}"
        )

    assert self._crawler.spider

    if scheme in self._old_style_handlers:  # pragma: no cover
        deferred_response = handler.download_request(request, self._crawler.spider)  # type: ignore[call-arg]
        return await maybe_deferred_to_future(cast("Deferred[Response]", deferred_response))

    return await handler.download_request(request)

def _freshen_cached_response(self, cachedresponse: Response, response: Response) -> None:
    # RFC 7234, section 4.3.4: update the stored response with the
    # header fields from a successful revalidation (304) response.
    warnings = [
        warning for warning in cachedresponse.headers.getlist(b"Warning")
        if warning.startswith(b"2")
    ]
    cachedresponse.headers.update(response.headers)
    if warnings:
        cachedresponse.headers[b"Warning"] = warnings
    else:
        cachedresponse.headers.pop(b"Warning", None)

def crawled(self, request: Request, response: Response, spider: Spider) -> LogFormatterResult:
    """Logs a message when the crawler finds a webpage."""
    def format_flags(flags):
        return f" {flags!s}" if flags else ""

    request_flags = format_flags(request.flags)
    response_flags = format_flags(response.flags)

    return {
        "level": logging.DEBUG,
        "msg": CRAWLEDMSG,
        "args": {
            "status": response.status,
            "request": request,
            "request_flags": request_flags,
            "referer": referer_str(request),
            "response_flags": response_flags,
            "flags": response_flags,
        }
    }

def process_response(self, request: Request, response: Response, spider: Spider | None = None) -> Request | Response:
    if self._should_not_redirect(request, response):
        return response

    if not self._is_redirect(response):
        return response

    location = self._get_safe_location(request, response)
    redirected_url = self._get_redirected_url(request, location)

    if not urlparse(redirected_url).fragment:
        redirected_url = self._add_fragment_if_missing(request, redirected_url)

    redirected = self._build_redirect_request(request, response, url=redirected_url)

    if urlparse_cached(redirected).scheme not in {"http", "https"}:
        return response

    if self._should_redirect_using_get(response, request):
        redirected = self._redirect_request_using_get(request, response, redirected_url)

    return self._redirect(redirected, request, response.status)

def _should_not_redirect(self, request: Request, response: Response) -> bool:
    return (
        request.meta.get("dont_redirect", False)
        or response.status in getattr(self.crawler.spider, "handle_httpstatus_list", ())
        or response.status in request.meta.get("handle_httpstatus_list", ())
        or request.meta.get("handle_httpstatus_all", False)
    )

def _is_redirect(self, response: Response) -> bool:
    return "Location" in response.headers and response.status in {301, 302, 303, 307, 308}

def _get_safe_location(self, request: Request, response: Response) -> str:
    location = safe_url_string(response.headers["Location"])
    if response.headers["Location"].startswith(b"//"):
        request_scheme = urlparse_cached(request).scheme
        location = request_scheme + "://" + location.lstrip("/")
    return location

def _get_redirected_url(self, request: Request, location: str) -> str:
    return urljoin(request.url, location)

def _add_fragment_if_missing(self, request: Request, redirected_url: str) -> str:
    fragment = urlparse_cached(request).fragment
    if fragment:
        redirected_url = urljoin(redirected_url, f"#{fragment}")
    return redirected_url

def _should_redirect_using_get(self, response: Response, request: Request) -> bool:
    return (
        (response.status in {301, 302} and request.method == "POST")
        or (response.status == 303 and request.method not in {"GET", "HEAD"})
    )

async def _process_response(
    self, response: Response | Request, request: Request, index: int = 0
) -> Response | Request:
    if response is None:
        raise TypeError("Received None in process_response")

    methods = self.methods["process_response"]
    while index < len(methods):
        if isinstance(response, Request):
            return response

        method = methods[index]
        index += 1

        if method is None:
            continue

        try:
            result = await ensure_awaitable(
                self._handle_mw_method(method, request=request, response=response),
                _warn=global_object_name(method),
            )
        except Exception as ex:
            if not self._response_exceptions:
                if not isinstance(ex, CloseSpider):
                    self._warn_response_exception(method, ex, index)
                raise
            response, index = await self._process_exception(ex, request, index)
            continue

        if not isinstance(result, (Response, Request)):
            raise _InvalidOutput(
                f"Middleware {method.__qualname__} must return Response or Request, "
                f"got {type(result)}"
            )
        response = result

    return response

def from_headers(self, headers: Mapping[bytes, bytes]) -> type[Response]:
    """Return the most appropriate Response class by looking at the HTTP headers"""
    if b"Content-Type" in headers:
        return self.from_content_type(
            content_type=headers[b"Content-Type"],
            content_encoding=headers.get(b"Content-Encoding"),
        )
    if b"Content-Disposition" in headers:
        return self.from_content_disposition(headers[b"Content-Disposition"])
    return Response

def _load_policy_class(
    self,
    policy: str,
    warning_only: bool = False,
    *,
    allow_import_path: bool = False,
) -> type[ReferrerPolicy] | None:
    """Load the :class:`ReferrerPolicy` class to use for *policy*."""

    def _try_import_path(policy: str) -> type[ReferrerPolicy] | None:
        try:
            return cast("type[ReferrerPolicy]", load_object(policy))
        except ValueError:
            return None

    def _get_policy_from_names(policy_names: list[str]) -> type[ReferrerPolicy] | None:
        for policy_name in reversed(policy_names):
            if policy_name in self.policies:
                return self.policies[policy_name]
        return None

    if allow_import_path:
        policy_class = _try_import_path(policy)
        if policy_class:
            return policy_class

    policy_names = [name.strip() for name in policy.lower().split(",")]
    policy_class = _get_policy_from_names(policy_names)
    if policy_class:
        return policy_class

    msg = f"Could not load referrer policy {policy!r}"
    if not allow_import_path and _looks_like_import_path(policy):
        msg += " (import paths from the response Referrer-Policy header are not allowed)"

    if not warning_only:
        raise RuntimeError(msg)

    warnings.warn(msg, RuntimeWarning, stacklevel=2)
    return None

def creatorForNetloc(self, hostname: bytes, port: int) -> ClientTLSOptions:
    decoded_hostname = hostname.decode("ascii")

    if not self._verify_certificates:
        return self._createScrapyClientTLSOptions(decoded_hostname)

    creator = optionsForClientTLS(
        hostname=decoded_hostname,
        extraCertificateOptions=self._get_cert_options_kwargs(),
    )

    if _get_keylog_filename():
        _set_keylog_callback(_get_creator_context(creator))

    return cast("ClientTLSOptions", creator)

def _createScrapyClientTLSOptions(self, decoded_hostname: str) -> ClientTLSOptions:
    if TWISTED_TLS_NEW_IMPL:
        return _ScrapyClientTLSOptions26(
            self._get_cert_options()._makeTLSConnection,
            decoded_hostname,
        )
    return _ScrapyClientTLSOptions(
        decoded_hostname,  # type: ignore[arg-type]
        self._get_context(),  # type: ignore[arg-type]
    )

def _install_twisted_idna_fallbacks() -> None:
    """Patch ``_idnaBytes()``/``_idnaText()`` wherever Twisted uses them for
    client connections.

    Each module binds them at import time, so every reference needs patching,
    not just ``twisted.internet._idna``. Names that are missing or already
    patched are left alone.
    """
    from twisted.internet import _resolver, _sslverify, endpoints  # noqa: PLC0415

    modules = (_idna, _resolver, _sslverify, endpoints)
    patches = {
        "_idnaBytes": (_original_idna_bytes, _patched_idna_bytes),
        "_idnaText": (_original_idna_text, _patched_idna_text),
    }

    for module in modules:
        for name, (original, patched) in patches.items():
            if getattr(module, name, None) is original:
                setattr(module, name, patched)

def _set_body(self, body: bytes | None) -> None:
    if body is None:
        self._body = b""
        return
    if not isinstance(body, bytes):
        raise TypeError(
            "Response body must be bytes. "
            "If you want to pass unicode body use TextResponse "
            "or HtmlResponse."
        )
    self._body = body

def _update_stores(cls, settings: BaseSettings) -> None:
    upload_timeout = settings.getfloat("UPLOAD_TIMEOUT") or None

    def update_store(store, config):
        for attr, setting_key in config.items():
            setattr(store, attr, settings[setting_key])
        store.UPLOAD_TIMEOUT = upload_timeout

    s3_config = {
        "AWS_ACCESS_KEY_ID": "AWS_ACCESS_KEY_ID",
        "AWS_SECRET_ACCESS_KEY": "AWS_SECRET_ACCESS_KEY",
        "AWS_SESSION_TOKEN": "AWS_SESSION_TOKEN",
        "AWS_ENDPOINT_URL": "AWS_ENDPOINT_URL",
        "AWS_REGION_NAME": "AWS_REGION_NAME",
        "AWS_USE_SSL": "AWS_USE_SSL",
        "AWS_VERIFY": "AWS_VERIFY",
        "AWS_MAX_POOL_CONNECTIONS": _get_max_pool_connections(settings),
        "POLICY": "FILES_STORE_S3_ACL"
    }
    update_store(cast("type[S3FilesStore]", cls.STORE_SCHEMES["s3"]), s3_config)

    gcs_config = {
        "GCS_PROJECT_ID": "GCS_PROJECT_ID",
        "POLICY": "FILES_STORE_GCS_ACL"
    }
    update_store(cast("type[GCSFilesStore]", cls.STORE_SCHEMES["gs"]), gcs_config)

    ftp_config = {
        "FTP_USERNAME": "FTP_USER",
        "FTP_PASSWORD": "FTP_PASSWORD",
        "USE_ACTIVE_MODE": settings.getbool("FEED_STORAGE_FTP_ACTIVE")
    }
    update_store(cast("type[FTPFilesStore]", cls.STORE_SCHEMES["ftp"]), ftp_config)

def iterate_spider_output(
    result: Any,
) -> Iterable[Any] | AsyncGenerator[_T] | Deferred[_T]:
    if inspect.isasyncgen(result):
        return cast("AsyncGenerator[_T]", result)
    if inspect.iscoroutine(result):
        return deferred_from_coro(result).addCallback(iterate_spider_output)
    return arg_to_iter(deferred_from_coro(result))

def _compute_current_age(self, response: Response, request: Request, now: float) -> float:
    date = rfc1123_to_epoch(response.headers.get(b"Date")) or now
    currentage = max(0, now - date) if now > date else 0

    age_header = response.headers.get(b"Age")
    if age_header is not None:
        try:
            age = int(age_header)
            currentage = max(currentage, age)
        except ValueError:
            pass

    return currentage

def _sitemap_urls_from_robots_str(
    robots_text: str,
    base_url: str | None = None,
) -> Iterable[str]:
    base_url = base_url or ""
    for line in StringIO(robots_text):
        stripped_line = line.lstrip()
        if stripped_line[:8].lower() == "sitemap:":
            url = stripped_line[8:].strip()
            yield urljoin(base_url, url)

def post_process(self, output: list[Any]) -> None:
    occurrences = sum(1 for x in output if self.obj_type_verifier(x))
    if not (self.min_bound <= occurrences <= self.max_bound):
        expected = str(self.min_bound) if self.min_bound == self.max_bound else f"{self.min_bound}..{self.max_bound}"
        raise ContractFail(f"Returned {occurrences} {self.obj_name}, expected {expected}")

def walk_modules_iter(path: str) -> Iterable[ModuleType]:
    """Loads a module and all its submodules from the given module path and
    returns them. If *any* module throws an exception while importing, that
    exception is thrown back.
    """
    def _walk(path: str) -> Iterable[ModuleType]:
        mod = import_module(path)
        yield mod
        if hasattr(mod, "__path__"):
            for _, subpath, ispkg in iter_modules(mod.__path__):
                fullpath = f"{path}.{subpath}"
                yield from _walk(fullpath) if ispkg else (import_module(fullpath),)

    return _walk(path)

def get_serialized_fields(
    self, item: Any, default_value: Any = None, include_empty: bool | None = None
) -> Iterable[tuple[str, Any]]:
    """Return the fields of *item* to export, as an iterable of
    ``(name, serialized_value)`` tuples, taking :attr:`fields_to_export`
    into account and applying :meth:`serialize_field` to every value.

    Fields missing from *item* are exported with *default_value*.

    *include_empty* overrides :attr:`export_empty_fields`.
    """
    item = ItemAdapter(item)
    include_empty = include_empty if include_empty is not None else self.export_empty_fields

    def get_field_iter():
        if self.fields_to_export is None:
            return item.field_names() if include_empty else self._get_populated_field_names(item)
        if isinstance(self.fields_to_export, Mapping):
            return self.fields_to_export.items() if include_empty else ((x, y) for x, y in self.fields_to_export.items() if x in item)
        return self.fields_to_export if include_empty else (x for x in self.fields_to_export if x in item)

    for field_name in get_field_iter():
        item_field, output_field = (field_name, field_name) if isinstance(field_name, str) else field_name
        value = self.serialize_field(item.get_field_meta(item_field), output_field, item[item_field]) if item_field in item else default_value
        yield output_field, value

def get_func_args_dict(
    func: Callable[..., Any], stripself: bool = False
) -> Mapping[str, inspect.Parameter]:
    """Return the argument dict of a callable object.

    Annotations are not evaluated, so on Python 3.14 and later the ``annotation``
    attribute of the returned parameters may be a ``ForwardRef`` instead of the
    resolved type.

    .. versionadded:: 2.14
    """
    if not callable(func):
        raise TypeError(f"func must be callable, got '{type(func).__name__}'")

    try:
        sig = _signature(func)
    except ValueError:
        return {}

    args = sig.parameters
    if isinstance(func, partial) and func.keywords:
        args = {name: param for name, param in args.items() if name not in func.keywords}

    if stripself:
        args = {k: v for k, v in args.items() if k != "self"}

    return args

def format_live_refs(
    ignore: type[Any] | tuple[type[Any], ...] = NoneType,
) -> str:
    """Return a tabular representation of tracked objects"""
    s = "Live References\n\n"
    now_ns = monotonic_ns()
    for cls, wdict in sorted(
        (cls, wdict) for cls, wdict in live_refs.items() if wdict and not issubclass(cls, ignore)
    ):
        oldest_ns = min(wdict.values())
        s += f"{cls.__name__:<30} {len(wdict):6}   oldest: {int((now_ns - oldest_ns) // 1e9)}s ago\n"
    return s

def scraped(self, item: Any, response: Response | Failure | None, spider: Spider) -> LogFormatterResult:
    """Logs a message when an item is scraped by a spider."""
    src = (
        f"{global_object_name(spider.__class__)}.start"
        if response is None
        else response.getErrorMessage()
        if isinstance(response, Failure)
        else response
    )
    return {
        "level": logging.DEBUG,
        "msg": SCRAPEDMSG,
        "args": {
            "src": src,
            "item": item,
        },
    }

def __init__(self, crawler: Crawler):
    self._validate_settings(crawler)
    self._initialize_attributes(crawler)
    self._set_password_if_empty()
    self._connect_signals()

def _validate_settings(self, crawler: Crawler):
    if not crawler.settings.getbool("TELNETCONSOLE_ENABLED"):
        raise NotConfigured
    if not crawler.settings.getbool("TWISTED_REACTOR_ENABLED"):
        raise NotConfigured(
            "The TelnetConsole extension requires a Twisted reactor."
            " You can set the TELNETCONSOLE_ENABLED setting to False to remove this warning."
        )

def _initialize_attributes(self, crawler: Crawler):
    self.crawler: Crawler = crawler
    self.noisy: bool = False
    self.port: Port | None = None
    self.portrange: list[int] = [
        int(x) for x in crawler.settings.getlist("TELNETCONSOLE_PORT")
    ]
    self.host: str = crawler.settings["TELNETCONSOLE_HOST"]
    self.username: str = crawler.settings["TELNETCONSOLE_USERNAME"]
    self.password: str = crawler.settings["TELNETCONSOLE_PASSWORD"]

def _set_password_if_empty(self):
    if not self.password:
        self.password = token_hex(8)
        logger.info("Telnet Password: %s", self.password)

def _connect_signals(self):
    self.crawler.signals.connect(self.start_listening, signals.engine_started)
    self.crawler.signals.connect(self.stop_listening, signals.engine_stopped)

def execute(argv: list[str] | None = None, settings: Settings | None = None) -> None:
    argv = argv or sys.argv
    settings = settings or _initialize_settings()

    inproject = inside_project()
    cmds = _get_commands_dict(settings, inproject)
    cmdname = _pop_command_name(argv)

    if not cmdname:
        _print_commands(settings, inproject)
        sys.exit(0)

    if cmdname not in cmds:
        _print_unknown_command(settings, cmdname, inproject)
        sys.exit(2)

    cmd = cmds[cmdname]
    parser = _create_parser(cmdname, cmd)
    settings.setdict(cmd.default_settings, priority="command")
    cmd.settings = settings
    cmd.add_options(parser)
    opts, args = parser.parse_known_args(args=argv[1:])
    _run_print_help(parser, cmd.process_options, args, opts)

    cmd.crawler_process = _get_crawler_process(settings, cmd)
    _run_print_help(parser, _run_command, cmd, args, opts)
    sys.exit(cmd.exitcode)

def _initialize_settings() -> Settings:
    settings = get_project_settings()
    editor = os.environ.get("EDITOR")
    if editor:
        settings["EDITOR"] = editor
    return settings

def _create_parser(cmdname: str, cmd) -> ScrapyArgumentParser:
    return ScrapyArgumentParser(
        formatter_class=ScrapyHelpFormatter,
        usage=f"scrapy {cmdname} {cmd.syntax()}",
        conflict_handler="resolve",
        description=cmd.long_desc(),
    )

def _get_crawler_process(settings: Settings, cmd) -> CrawlerProcess:
    if (
        settings["TWISTED_REACTOR"] == _asyncio_reactor_path
        and not settings.getbool("FORCE_CRAWLER_PROCESS")
    ) or not settings.getbool("TWISTED_REACTOR_ENABLED"):
        return AsyncCrawlerProcess(settings)
    return CrawlerProcess(settings)

def iterate_spider_output(self, result: Any) -> Iterable[Any] | Deferred[Any]:
    if inspect.isasyncgen(result) or inspect.iscoroutine(result):
        d = deferred_from_coro(
            collect_asyncgen(aiter_errback(result, self.handle_exception))
            if inspect.isasyncgen(result) else result
        )
        return d.addCallback(self.iterate_spider_output)
    return arg_to_iter(deferred_from_coro(result))

def ftp_makedirs_cwd(ftp: FTP, path: str, first_call: bool = True) -> None:
    """Set the current directory of the FTP connection given in the ``ftp``
    argument (as a ftplib.FTP object), creating all parent directories if they
    don't exist. The ftplib.FTP object must be already connected and logged in.
    """
    try:
        ftp.cwd(path)
    except error_perm:
        parent_path = dirname(path)
        ftp_makedirs_cwd(ftp, parent_path, False)
        ftp.mkd(path)
    if first_call:
        ftp.cwd(path)

def run(self, args: list[str], opts: argparse.Namespace) -> None:
    if len(args) != 1 or not is_url(args[0]):
        raise UsageError

    url = args[0]
    self.set_spidercls(url, opts)

    if self.spidercls and opts.depth > 0:
        self.start_parsing(url, opts)
        self.print_results(opts)

def _write_headers_and_set_fields_to_export(self, item: Any) -> None:
    if not self.include_headers_line:
        return

    if not self.fields_to_export:
        self.fields_to_export = ItemAdapter(item).field_names()
        self._autodetected_fields = True

    fields = self.fields_to_export.values() if isinstance(self.fields_to_export, Mapping) else self.fields_to_export
    row = list(self._build_row(fields))
    self.csv_writer.writerow(row)

def start_exporting(self) -> None:
    if not self._fileloaded:
        self._initialize_file()
        self._initialize_exporter()
        self._fileloaded = True

    if not self._exporting:
        self._start_exporter()

def _initialize_file(self) -> None:
    self.file = self.storage.open(self.spider)
    if "postprocessing" in self.feed_options:
        self.file = cast(
            "IO[bytes]",
            PostProcessingManager(
                self.feed_options["postprocessing"],
                self.file,
                self.feed_options,
            ),
        )

def _initialize_exporter(self) -> None:
    self.exporter = self._get_exporter(
        file=self.file,
        format_=self.feed_options["format"],
        fields_to_export=self.feed_options["fields"],
        encoding=self.feed_options["encoding"],
        indent=self.feed_options["indent"],
        **self.feed_options["item_export_kwargs"],
    )

def _start_exporter(self) -> None:
    assert self.exporter
    self.exporter.start_exporting()
    self._exporting = True

def _declared_encoding(self) -> str | None:
    for method in [self._encoding, self._bom_encoding, self._headers_encoding, self._body_declared_encoding]:
        encoding = method() if callable(method) else method
        if encoding:
            return encoding
    return None

def request_from_dict(d: dict[str, Any], *, spider: Spider | None = None) -> Request:
    """Create a :class:`~scrapy.Request` object from a dict.

    If a spider is given, it will try to resolve the callbacks looking at the
    spider for methods with the same name.
    """
    request_cls: type[Request] = load_object(d.get("_class", Request))
    kwargs = {key: value for key, value in d.items() if key in request_cls.attributes}

    for callback_type in ["callback", "errback"]:
        if d.get(callback_type) and spider:
            kwargs[callback_type] = _get_method(spider, d[callback_type])

    return request_cls(**kwargs)

def process_request(self, request: Request, spider: Spider | None = None) -> None:
    assert self.crawler.spider
    if self._should_process(request):
        return

    domain = urlparse_cached(request).hostname
    if domain and domain not in self.domains_seen:
        self._log_and_track_domain(domain, request)

    self.stats.inc_value("offsite/filtered")
    raise IgnoreRequest(f"Filtered offsite request to {domain!r}")

def _should_process(self, request: Request) -> bool:
    return (
        request.dont_filter
        or request.meta.get("allow_offsite")
        or self.should_follow(request, self.crawler.spider)
    )

def _log_and_track_domain(self, domain: str, request: Request) -> None:
    self.domains_seen.add(domain)
    logger.debug(
        "Filtered offsite request to %(domain)r: %(request)s",
        {"domain": domain, "request": request},
        extra={"spider": self.crawler.spider},
    )
    self.stats.inc_value("offsite/domains")

def _run_print_help(
    parser: argparse.ArgumentParser,
    func: Callable[_P, None],
    *a: _P.args,
    **kw: _P.kwargs,
) -> None:
    try:
        func(*a, **kw)
    except UsageError as e:
        if str(e):
            parser.error(str(e))
        if e.print_help:
            parser.print_help()
        sys.exit(2)

def iter_errback(
    iterable: Iterable[_T],
    errback: Callable[Concatenate[Failure, _P], Any],
    *a: _P.args,
    **kw: _P.kwargs,
) -> Iterable[_T]:
    """Wrap an iterable calling an errback if an error is caught while
    iterating it.
    """
    for item in iterable:
        try:
            yield item
        except Exception:
            errback(failure.Failure(), *a, **kw)

def _debug_set_cookie(self, response: Response) -> None:
    if not self.debug:
        return

    cookies_list = response.headers.getlist("Set-Cookie")
    if not cookies_list:
        return

    cookies = "\n".join(f"Set-Cookie: {to_unicode(c, errors='replace')}\n" for c in cookies_list)
    msg = f"Received cookies from: {response}\n{cookies}"
    logger.debug(msg, extra={"spider": self.crawler.spider})

async def close_spider(self, spider: Spider) -> None:
    for slot in self.slots:
        self._schedule_slot_close(slot, spider)

    if self._pending_close_tasks:  # pragma: no branch
        tasks = list(self._pending_close_tasks)
        if is_asyncio_available():
            await asyncio.wait(cast("list[asyncio.Task[None]]", tasks))
        else:
            await DeferredList(cast("list[Deferred[None]]", tasks))

    await self.crawler.signals.send_catch_log_async(signals.feed_exporter_closed)

def _check_name_duplicates(self) -> None:
    dupes = [
        f"  {cls} named {name!r} (in {mod})"
        for name, locations in self._found.items()
        for mod, cls in locations
        if len(locations) > 1
    ]

    if dupes:
        dupes_string = "\n\n".join(dupes)
        warnings.warn(
            "There are several spiders with the same name:\n\n"
            f"{dupes_string}\n\n  This can cause unexpected behavior.",
            stacklevel=2,
            category=UserWarning,
        )

async def download_async(self, request: Request) -> Response:
    """Return a coroutine which fires with a Response as result.

    Only downloader middlewares are applied.

    .. versionadded:: 2.14
    """
    if self.spider is None:
        raise RuntimeError(f"No open spider to crawl: {request}")

    while True:
        try:
            response_or_request = await maybe_deferred_to_future(
                self._download(request)
            )
        finally:
            assert self._slot is not None
            self._slot.remove_request(request)

        if isinstance(response_or_request, Request):
            request = response_or_request
        else:
            return response_or_request

def _select_value(
    ele: SelectElement, n: str | None, v: str | MultipleSelectOptions | None
) -> tuple[str | None, str | MultipleSelectOptions | None]:
    if v is None and not ele.multiple:
        options = ele.value_options
        return (n, options[0]) if options else (None, None)
    return n, v

def header_items(self) -> list[tuple[str, list[str]]]:
    def convert_to_unicode(item):
        return to_unicode(item, errors="replace")

    return [
        (convert_to_unicode(k), [convert_to_unicode(x) for x in v])
        for k, v in self.request.headers.items()
    ]

def _get_commands_from_entry_points(
    inproject: bool, group: str = "scrapy.commands"
) -> dict[str, ScrapyCommand]:
    def load_command(entry_point):
        obj = entry_point.load()
        if not (inspect.isclass(obj) and issubclass(obj, ScrapyCommand)):
            raise ValueError(f"Invalid entry point {entry_point.name}")
        return entry_point.name, obj()

    return dict(load_command(ep) for ep in entry_points(group=group))

def connectionMade(self) -> None:
    assert self.transport
    self._set_certificate()
    self._set_ip_address()

    if self._tls_verbose_logging:
        self._log_connection_info()

def _set_certificate(self) -> None:
    with suppress(AttributeError):
        self._certificate = ssl.Certificate(
            self.transport._producer.getPeerCertificate()
        )

def _set_ip_address(self) -> None:
    self._ip_address = ipaddress.ip_address(self.transport._producer.getPeer().host)

def _log_connection_info(self) -> None:
    connection = self.transport._producer.getHandle()
    hostname = urlparse_cached(self._request).hostname
    assert hostname is not None
    _log_ssl_conn_debug_info(hostname, connection)

def __init__(self, name: str | None = None, **kwargs: Any):
    self.name: str = name if name is not None else getattr(self, "name", None)
    if self.name is None:
        raise ValueError(f"{type(self).__name__} must have a name")
    self.__dict__.update(kwargs)
    self.start_urls: list[str] = getattr(self, "start_urls", [])

def __init__(self, settings: BaseSettings | None = None):  # pylint: disable=super-init-not-called
    self.default_policy: type[ReferrerPolicy] = DefaultReferrerPolicy
    self.policies: dict[str, type[ReferrerPolicy]] = self._initialize_policies()
    if settings is None:
        self._warn_deprecation()
        return
    self._update_policies_from_settings(settings)
    self.default_policy = self._load_policy_class(
        settings.get("REFERRER_POLICY"), allow_import_path=True
    )
    assert self.default_policy

def _initialize_policies(self) -> dict[str, type[ReferrerPolicy]]:
    policies = {
        p.name: p
        for p in (
            NoReferrerPolicy,
            NoReferrerWhenDowngradePolicy,
            SameOriginPolicy,
            OriginPolicy,
            StrictOriginPolicy,
            OriginWhenCrossOriginPolicy,
            StrictOriginWhenCrossOriginPolicy,
            UnsafeUrlPolicy,
            DefaultReferrerPolicy,
        )
    }
    policies[""] = NoReferrerWhenDowngradePolicy
    return policies

def _warn_deprecation(self):
    warn(
        "Instantiating RefererMiddleware without a 'settings' argument is "
        "deprecated.",
        ScrapyDeprecationWarning,
        stacklevel=2,
    )

def _update_policies_from_settings(self, settings: BaseSettings):
    setting_policies = settings.getdict("REFERRER_POLICIES")
    for policy_name, policy_class_import_path in setting_policies.items():
        if policy_class_import_path is None:
            del self.policies[policy_name]
        else:
            self.policies[policy_name] = load_object(policy_class_import_path)

def get_current_gpu_usage():
    """Get the current GPU memory usage."""
    if not (cfg.gpu_mem and cfg.device != 'cpu' and torch.cuda.is_available()):
        return -1

    result = subprocess.check_output([
        'nvidia-smi', '--query-compute-apps=pid,used_memory',
        '--format=csv,nounits,noheader'
    ], encoding='utf-8')

    current_pid = os.getpid()
    used_memory = sum(
        int(line.split(', ')[1])
        for line in result.strip().split('\n')
        if current_pid == int(line.split(', ')[0])
    )
    return used_memory

def process(self) -> None:
    import pandas as pd

    def load_csv_to_tensor(path, dtype, view_shape=None):
        values = pd.read_csv(path, compression='gzip', header=None, dtype=dtype).values
        tensor = torch.from_numpy(values)
        return tensor.view(view_shape) if view_shape else tensor

    data = HeteroData()

    data['paper'].x = load_csv_to_tensor(
        osp.join(self.raw_dir, 'node-feat', 'paper', 'node-feat.csv.gz'), np.float32
    )

    data['paper'].year = load_csv_to_tensor(
        osp.join(self.raw_dir, 'node-feat', 'paper', 'node_year.csv.gz'), np.int64, -1
    )

    data['paper'].y = load_csv_to_tensor(
        osp.join(self.raw_dir, 'node-label', 'paper', 'node-label.csv.gz'), np.int64
    ).flatten()

    if self.preprocess is None:
        num_nodes_df = pd.read_csv(
            osp.join(self.raw_dir, 'num-node-dict.csv.gz'), compression='gzip'
        )
        for node_type in ['author', 'institution', 'field_of_study']:
            data[node_type].num_nodes = num_nodes_df[node_type].tolist()[0]
    else:
        emb_dict = fs.torch_load(self.raw_paths[-1])
        for key, value in emb_dict.items():
            if key != 'paper':
                data[key].x = value

    edge_types = [
        ('author', 'affiliated_with', 'institution'),
        ('author', 'writes', 'paper'),
        ('paper', 'cites', 'paper'),
        ('paper', 'has_topic', 'field_of_study')
    ]

    for edge_type in edge_types:
        f = '___'.join(edge_type)
        path = osp.join(self.raw_dir, 'relations', f, 'edge.csv.gz')
        edge_index = load_csv_to_tensor(path, np.int64).t().contiguous()
        data[edge_type].edge_index = edge_index

    splits = [('train', 'train'), ('valid', 'val'), ('test', 'test')]
    for f, v in splits:
        path = osp.join(self.raw_dir, 'split', 'time', 'paper', f'{f}.csv.gz')
        idx = load_csv_to_tensor(path, np.int64).flatten()
        mask = torch.zeros(data['paper'].num_nodes, dtype=torch.bool)
        mask[idx] = True
        data['paper'][f'{v}_mask'] = mask

    if self.pre_transform is not None:
        data = self.pre_transform(data)

    self.save([data], self.processed_paths[0])

def processes_point_clouds(cls: str) -> bool:
    cls = importlib.import_module('torch_geometric.nn.conv').__dict__[cls]
    signature_str = str(inspect.signature(cls.forward))
    return 'pos' in signature_str or ('edge_index' not in signature_str and 'csc' not in signature_str)

def __getitem__(self, index: Union[Tensor, Any]) -> 'NodeSamplerInput':
    index = torch.tensor(index, dtype=torch.long) if not isinstance(index, Tensor) else index

    input_id = self.input_id[index] if self.input_id is not None else index
    time = self.time[index] if self.time is not None else None

    return NodeSamplerInput(input_id, self.node[index], time, self.input_type)

def forward(self, data: Data) -> Data:
    assert data.pos is not None
    device = data.pos.device
    num_pos = data.pos.size(0)

    if num_pos < 2:
        data.edge_index = torch.empty(2, 0, dtype=torch.long, device=device)
    elif num_pos == 2:
        data.edge_index = torch.tensor([[0, 1], [1, 0]], device=device)
    elif num_pos == 3:
        data.face = torch.tensor([[0], [1], [2]], device=device)
    else:
        data = self._transform.forward(data)

    return data

def torch_load(path: str, map_location: Any = None) -> Any:
    def load_with_weights_only():
        with fsspec.open(path, 'rb') as f:
            return torch.load(f, map_location, weights_only=True)

    def load_without_weights_only():
        with fsspec.open(path, 'rb') as f:
            return torch.load(f, map_location, weights_only=False)

    if torch_geometric.typing.WITH_PT24:
        try:
            return load_with_weights_only()
        except pickle.UnpicklingError as e:
            error_msg = str(e)
            if "add_safe_globals" in error_msg:
                warn_msg = ("Weights only load failed. Please file an issue "
                            "to make `torch.load(weights_only=True)` "
                            "compatible in your case.")
                match = re.search(r'add_safe_globals\(.*?\)', error_msg)
                if match:
                    warnings.warn(
                        f"{warn_msg} Please use "
                        f"`torch.serialization.{match.group()}` to "
                        f"allowlist this global.", stacklevel=2)
                else:
                    warnings.warn(warn_msg, stacklevel=2)
                return load_without_weights_only()
            else:
                raise e

    with fsspec.open(path, 'rb') as f:
        return torch.load(f, map_location)

def num_node_features(self) -> int:
    """Returns the number of features per node in the dataset."""
    data = self[0]

    # Do not fill cache for `InMemoryDataset`:
    if getattr(self, '_data_list', None) is not None:
        self._data_list[0] = None

    data = data[0] if isinstance(data, tuple) else data

    if hasattr(data, 'num_node_features'):
        return data.num_node_features

    raise AttributeError(f"'{type(data).__name__}' object has no attribute 'num_node_features'")

def reset_parameters(self):
    super().reset_parameters()
    if isinstance(self.g, torch.nn.UninitializedParameter):
        return
    glorot(self.g)
    glorot(self.mu)
    glorot(self.sigma)
    if self.root_weight:
        self.root.reset_parameters()
    zeros(self.bias)

def get_edge_features_iter(
    self,
    feature_name: str = EDGE_PID,
    pids: Optional[KnowledgeGraphLike] = None,
    index_only: bool = False,
) -> Iterator[Any]:
    """Iterator version of get_edge_features. If index_only is True,
    yields indices instead of values.
    """
    pids = pids or self.edge_attr[EDGE_PID]

    if feature_name in self._mapped_edge_features:
        feature_map_info = self.edge_attr[feature_name]
        from_feature_vals = self.get_unique_edge_features(feature_map_info.name)
        feature_mapping = {k: i for i, k in enumerate(from_feature_vals)}

        for pid in pids:
            idx = self._edges[pid]
            from_feature_val = self.edge_attr[feature_map_info.name][idx]
            to_feature_idx = feature_mapping[from_feature_val]
            yield to_feature_idx if index_only else feature_map_info.values[to_feature_idx]
    else:
        for pid in pids:
            idx = self._edges[pid]
            yield idx if index_only else self.edge_attr[feature_name][idx]

def validate_hop_context_time_ranges(
    pair: Dict[str, Any],
    local_ranges: List[Dict[str, Any]],
    cross_ranges: List[Dict[str, Any]],
) -> None:
    """Ensure hop contexts fall within known timestamp ranges. Adjust to the
    closest available match when possible and record validation warnings.
    """
    hop_contexts = pair.get('hop_contexts', [])
    if not hop_contexts:
        return

    warnings: List[str] = []
    all_ranges = local_ranges + cross_ranges

    for hop_entry in hop_contexts:
        start_ts = hop_entry.get('start_time')
        end_ts = hop_entry.get('end_time')
        start_seconds = parse_timestamp(start_ts) if start_ts else None
        end_seconds = parse_timestamp(end_ts) if end_ts else None

        target_range = find_target_range(start_seconds, end_seconds, local_ranges, cross_ranges)

        if target_range:
            hop_entry['source'] = target_range.get('source')
        else:
            adjust_hop_entry(hop_entry, start_seconds, all_ranges, warnings, start_ts, end_ts)

    if warnings:
        pair.setdefault('validation_warnings', []).extend(warnings)

def find_target_range(start_seconds, end_seconds, local_ranges, cross_ranges):
    if start_seconds is None or end_seconds is None:
        return None

    for candidate in local_ranges:
        if _range_contains(start_seconds, end_seconds, candidate):
            return {**candidate, 'source': candidate.get('source', 'local')}

    for candidate in cross_ranges:
        if _range_contains(start_seconds, end_seconds, candidate):
            return {**candidate, 'source': candidate.get('source', 'cross')}

    return None

def adjust_hop_entry(hop_entry, start_seconds, candidates, warnings, start_ts, end_ts):
    if start_seconds is not None and candidates:
        best_match = _find_best_matching_range(start_seconds, candidates)
    else:
        best_match = None

    if best_match and best_match.get('start') and best_match.get('end'):
        hop_entry['start_time'] = best_match['start']
        hop_entry['end_time'] = best_match['end']
        hop_entry['source'] = best_match.get('source')
        warnings.append(
            f'Hop {hop_entry.get("hop")} timestamps adjusted to nearest available range '
            f'({best_match.get("start")} - {best_match.get("end")}).')
    else:
        warnings.append(
            f'Hop {hop_entry.get("hop")} timestamps ({start_ts} - {end_ts}) do not map to known segments.')

def _fn_apply(self, args, fn, fn_inverse):
    if self.disable:
        return fn(*args)

    out = InvertibleFunction.apply(
        fn,
        fn_inverse,
        self.num_bwd_passes,
        len(args),
        *args,
        *tuple(p for p in self.parameters() if p.requires_grad),
    )

    return out[0] if isinstance(out, tuple) and len(out) == 1 else out

def lists_distance(l1, l2):
    assert len(l1) == len(l2)
    return sum(el1 != el2 for el1, el2 in zip(l1, l2))

def message_and_aggregate(self, edge_index: Adj, x: OptPairTensor, edge_weight: OptTensor) -> Tensor:
    if torch.jit.is_scripting() or not isinstance(edge_index, EdgeIndex):
        return spmm(edge_index, x[0], reduce=self.aggr)

    return edge_index.matmul(
        other=x[0],
        input_value=edge_weight,
        reduce=self.aggr,
        transpose=True,
    )

def forward(self, batch):
    batch = self.apply_layers(batch)
    if cfg.gnn.l2norm:
        batch.x = F.normalize(batch.x, p=2, dim=-1)
    return batch

def apply_layers(self, batch):
    for layer in self.children():
        batch = layer(batch)
    return batch

def run_inference(dataset, model, epochs, profiling, bf16, use_compile,
                  permute_masks=None, logger=None):
    data = dataset[0]
    if permute_masks:
        data = permute_masks(data, dataset.num_classes)
    data = data.to(device)

    model.to(device).reset_parameters()
    if use_compile:
        model = torch.compile(model)

    amp = torch.amp.autocast('cuda', enabled=False) if torch.cuda.is_available() else torch.cpu.amp.autocast(enabled=bf16)
    if bf16:
        data.x = data.x.to(torch.bfloat16)

    with amp:
        for epoch in range(1, epochs + 1):
            with timeit() if epoch == epochs else contextlib.nullcontext():
                inference(model, data)

        if profiling:
            with torch_profile():
                inference(model, data)

def reset_parameters(self):
    super().reset_parameters()
    reset(self.mlp)
    attributes = ['msg_norm', 'lin_src', 'lin_edge', 'lin_aggr_out', 'lin_dst']
    for attr in attributes:
        if hasattr(self, attr):
            getattr(self, attr).reset_parameters()

def size(self, dim: Optional[int] = None) -> Union[Tuple[Optional[int], Optional[int]], Optional[int]]:
    if self._key is None:
        raise NameError("Unable to infer 'size' without explicit '_key' assignment")

    parent = self._parent()
    size = (parent[self._key[0]].num_nodes, parent[self._key[-1]].num_nodes)

    return size if dim is None else size[dim]

def _calculate_base_loss(self, y_hat: Tensor, y: Tensor) -> Tensor:
    """Calculate base loss based on model configuration."""
    loss_functions = {
        ModelMode.binary_classification: self._loss_binary_classification,
        ModelMode.multiclass_classification: self._loss_multiclass_classification,
        ModelMode.regression: self._loss_regression
    }

    try:
        return loss_functions[self.model_config.mode](y_hat, y)
    except KeyError:
        raise ValueError(f"Unsupported model mode: {self.model_config.mode}")

def process(self) -> None:
    raw_dir = self._get_raw_directory()
    raw_files = fs.ls(raw_dir)
    data_list = self._read_data(raw_files)

    if len(data_list) > 1 and self.pre_filter is not None:
        data_list = filter(self.pre_filter, data_list)

    if self.pre_transform is not None:
        data_list = map(self.pre_transform, data_list)

    self.save(list(data_list), self.processed_paths[0])

def _get_raw_directory(self) -> str:
    filenames = fs.ls(self.raw_dir)
    if len(filenames) == 1 and fs.isdir(filenames[0]):
        return filenames[0]
    return self.raw_dir

def _read_data(self, raw_files: List[str]) -> Union[List[Data], List[EgoData]]:
    prefix = self.name.split('-')[0]
    if prefix == 'ego':
        return read_ego(raw_files, self.name[4:])
    elif prefix == 'soc':
        return read_soc(raw_files, self.name[:4])
    elif prefix == 'wiki':
        return read_wiki(raw_files, self.name[5:])
    else:
        raise NotImplementedError

def resolve(query: Any, *args: Any, **kwargs: Any) -> 'MotifGenerator':
    from torch_geometric.datasets import motif_generator as _motif_generators
    motif_generators = [
        gen for gen in vars(_motif_generators).values()
        if isinstance(gen, type) and issubclass(gen, MotifGenerator)
    ]
    return resolver(motif_generators, {}, query, MotifGenerator, 'Motif', *args, **kwargs)

def process(self) -> None:
    with open(self.raw_paths[1]) as f:
        manifest = json.load(f)

    total = manifest['full_train'] + manifest['full_test']
    partial = set(manifest[f'{self.task}_{self.split}'])
    raw_data = fs.torch_load(self.raw_paths[0])

    data_list = [
        self.pre_transform(Data(**raw_data[k])) if self.pre_transform else Data(**raw_data[k])
        for k, s in enumerate(total)
        if s in partial and (self.pre_filter is None or self.pre_filter(Data(**raw_data[k])))
    ]

    self.save(data_list, self.processed_paths[0])

def reset_parameters(self):
    r"""Resets all learnable parameters of the module."""
    def reset_if_possible(obj):
        if hasattr(obj, 'reset_parameters'):
            obj.reset_parameters()

    for conv in self.convs:
        reset_if_possible(conv)
    for norm in self.norms:
        reset_if_possible(norm)
    reset_if_possible(getattr(self, 'jk', None))
    reset_if_possible(getattr(self, 'lin', None))

def __getitem__(self, index: Union[Tensor, Any]) -> 'EdgeSamplerInput':
    index = torch.tensor(index, dtype=torch.long) if not isinstance(index, Tensor) else index

    input_id = self.input_id[index] if self.input_id is not None else index
    label = self.label[index] if self.label is not None else None
    time = self.time[index] if self.time is not None else None

    return EdgeSamplerInput(input_id, self.row[index], self.col[index], label, time, self.input_type)

def __init__(self, parameters: Optional[Mapping[Key, Parameter]] = None):
    if parameters:
        parameters = {self.to_internal_key(key): param for key, param in parameters.items()}
    super().__init__(parameters)

def slice_to_range(self, indices: slice) -> range:
    start = indices.start or 0
    stop = indices.stop if indices.stop is not None else len(self)
    step = indices.step or 1

    return range(start, stop, step)

def get_csr(self) -> Tuple[Tuple[Tensor, Tensor], Optional[Tensor]]:
    r"""Returns the compressed CSR representation
    :obj:`(rowptr, col), perm` in case :class:`EdgeIndex` is sorted.
    """
    if self.is_sorted_by_row:
        return (self.get_indptr(), self._data[1]), None

    assert self.is_sorted_by_col
    (row, col), perm = self._sort_by_transpose()

    if self._T_indptr is None:
        if self.is_undirected and self._indptr is not None:
            self._T_indptr = self._indptr
        else:
            self._T_indptr = index2ptr(row, self.get_num_rows())

    return (self._T_indptr, col), perm

def collate_fn(self, index):
    index = torch.tensor(index) if not isinstance(index, Tensor) else index

    if isinstance(self.data, Data):
        return self.data.subgraph(index)

    if isinstance(self.data, HeteroData):
        node_dict = {
            key: index[(index >= start) & (index < end)] - start
            for key, (start, end) in self.node_dict.items()
        }
        return self.data.subgraph(node_dict)

def _select(input: EdgeIndex, dim: int, index: int) -> Union[Tensor, Index]:
    out = aten.select.int(input._data, dim, index)

    if dim in {0, -2}:
        out = Index(out)
        is_row_select = index in {0, -2}
        out._dim_size = input.sparse_size(0 if is_row_select else 1)
        out._is_sorted = input.is_sorted_by_row if is_row_select else input.is_sorted_by_col

        if out._is_sorted:
            out._indptr = input._indptr

    return out

def forward(
    self,
    x: Union[Tensor, Dict[NodeType, Tensor]],
    edge_index: Union[Tensor, Dict[EdgeType, Tensor]],
    node_type: OptTensor = None,
    edge_type: OptTensor = None,
    **kwargs,
) -> Union[Tensor, Dict[NodeType, Tensor]]:

    if isinstance(x, dict) and isinstance(edge_index, dict):
        return self.dict_forward(x, edge_index, **kwargs)

    if isinstance(x, Tensor) and isinstance(edge_index, Tensor):
        if node_type is not None and edge_type is not None:
            if kwargs:
                raise ValueError("Additional forward arguments not yet supported in fused mode")
            return self.fused_forward(x, edge_index, node_type, edge_type)

    raise ValueError(f"Encountered invalid forward types in '{self.__class__.__name__}'")

def download(self) -> None:
    self._download_raw_files()
    if self.split == 'geom-gcn':
        self._download_geom_gcn_splits()

def _download_raw_files(self) -> None:
    for name in self.raw_file_names:
        fs.cp(f'{self.url}/{name}', self.raw_dir)

def _download_geom_gcn_splits(self) -> None:
    base_url = f'{self.geom_gcn_url}/splits/{self.name.lower()}'
    for i in range(10):
        fs.cp(f'{base_url}_split_0.6_0.2_{i}.npz', self.raw_dir)

def _bisection(edge_weights: Tensor, a: float, b: float, n_pert: int,
               eps=1e-5, max_iter=1e3) -> Tensor:
    """Bisection search for projection."""

    def shift(offset: float) -> float:
        return torch.clamp(edge_weights - offset, 0, 1).sum() - n_pert

    for _ in range(int(max_iter)):
        miu = (a + b) / 2
        shift_miu = shift(miu)

        if shift_miu == 0.0 or (b - a) <= eps:
            return miu

        if shift_miu * shift(a) < 0:
            b = miu
        else:
            a = miu

    return miu

def calc_pairwise(self, batch: Tensor, X_node: Tensor, adj_mask: Tensor, ppr_matrix: Tensor) -> Tensor:
    k_i, k_j = X_node[batch[0]], X_node[batch[1]]
    pairwise_feats = torch.cat((k_i, k_j), dim=-1)

    cn_info, onehop_info, non1hop_info = self.compute_node_mask(batch, adj_mask, ppr_matrix)

    all_mask = cn_info[0]
    if onehop_info is not None:
        all_mask = torch.cat((all_mask, onehop_info[0]), dim=-1)
    if non1hop_info is not None:
        all_mask = torch.cat((all_mask, non1hop_info[0]), dim=-1)

    pes = self.get_pos_encodings(cn_info[1:], onehop_info[1:], non1hop_info[1:])

    for att_layer in self.att_layers:
        pairwise_feats = att_layer(all_mask, pairwise_feats, X_node, pes)

    structure_counts = self.get_structure_cnts(batch, cn_info, onehop_info, non1hop_info)
    pairwise_feats = torch.cat((pairwise_feats, *structure_counts), dim=-1)

    return self.pairwise_lin(pairwise_feats)

def forward(self, batch):
    for i, layer in enumerate(self.children()):
        x = batch.x
        batch = layer(batch)
        if self.stage_type == 'skipsum':
            batch.x += x
        elif self.stage_type == 'skipconcat' and i < self.num_layers - 1:
            batch.x = torch.cat([x, batch.x], dim=1)

    if self.final_l2_norm:
        batch.x = F.normalize(batch.x, p=2, dim=-1)

    return batch

def forward(
    self,
    x: Union[OptTensor, PairOptTensor],
    pos: Union[Tensor, PairTensor],
    edge_index: Adj,
) -> Tensor:

    x = (x, None) if not isinstance(x, tuple) else x
    pos = (pos, pos) if isinstance(pos, Tensor) else pos

    if self.add_self_loops:
        edge_index = self._process_edge_index(edge_index, pos)

    out = self.propagate(edge_index, x=x, pos=pos)

    if self.global_nn is not None:
        out = self.global_nn(out)

    return out

def _process_edge_index(self, edge_index: Adj, pos: PairTensor) -> Adj:
    if isinstance(edge_index, Tensor):
        edge_index, _ = remove_self_loops(edge_index)
        edge_index, _ = add_self_loops(
            edge_index, num_nodes=min(pos[0].size(0), pos[1].size(0)))
    elif isinstance(edge_index, SparseTensor):
        edge_index = torch_sparse.set_diag(edge_index)
    return edge_index

def agg_dict_list(dict_list):
    """Aggregate a list of dictionaries: mean + std
    Args:
        dict_list: list of dictionaries.

    """
    dict_agg = {'epoch': dict_list[0]['epoch']}
    keys = dict_list[0].keys() - {'epoch'}

    for key in keys:
        values = np.array([d[key] for d in dict_list])
        dict_agg[key] = np.mean(values).round(cfg.round)
        dict_agg[f'{key}_std'] = np.std(values).round(cfg.round)

    return dict_agg

def _slice(
    input: EdgeIndex,
    dim: int,
    start: Optional[int] = None,
    end: Optional[int] = None,
    step: int = 1,
) -> Union[EdgeIndex, Tensor]:

    if ((start is None or start == 0 or start <= -input.size(dim))
            and (end is None or end > input.size(dim)) and step == 1):
        return input._shallow_copy()  # No-op.

    out = aten.slice.Tensor(input._data, dim, start, end, step)

    if dim in {1, -1}:
        if step != 1:
            out = out.contiguous()

        out = EdgeIndex(out)
        out._sparse_size = input.sparse_size()
        out._sort_order = (input._sort_order if step >= 0 else
                           SortOrder.COL if input._sort_order == SortOrder.ROW else
                           SortOrder.ROW)

    return out

def download(self) -> None:
    for index, f in enumerate(self.raw_file_names):
        subdir = 'new_data' if index < 2 else 'splits'
        download_url(f'{self.url}/{subdir}/{self.name}/{f}', self.raw_dir)

def _multi_get(self, indices: Union[Sequence[int], Tensor]) -> List[Any]:
    if isinstance(indices, Tensor):
        indices = indices.tolist()
    keys = map(self.to_key, indices)
    return [self._deserialize(data) for data in self.db[keys]]

def forward(
    self,
    x: Union[Tensor, PairTensor],
    edge_index: Adj,
    edge_attr: OptTensor = None,
) -> Tensor:

    x = (x, x) if isinstance(x, Tensor) else x

    if self.edge_dim is None:
        k, q, v = self.lin_key(x[1]), self.lin_query(x[0]), self.lin_value(x[0])
    else:
        k, q, v = x[1], x[0], x[0]

    out = self.propagate(edge_index, k=k, q=q, v=v, edge_attr=edge_attr)

    if self.root_weight:
        out += self.lin_skip(x[1])

    if self.bias is not None:
        out += self.bias

    return out

def edge_softmax(self):
    alpha, normalizer = self.softmax(self.g.edata['a'], self.g)
    self.g.ndata['z'] = normalizer
    if self.training and self.dropout > 0:
        alpha = F.dropout(alpha, p=self.dropout, training=True)
    self.g.edata['a'] = alpha

def __init__(
    self,
    metrics: Union[
        List[LinkPredMetric],
        Dict[str, LinkPredMetric],
    ],
) -> None:
    super().__init__()

    if isinstance(metrics, (list, tuple)):
        metrics = {
            f'{"Weighted" if getattr(metric, "weighted", False) else ""}'
            f'{metric.__class__.__name__}@{metric.k}': metric
            for metric in metrics
        }

    assert metrics and isinstance(metrics, dict)

    for name, metric in metrics.items():
        assert isinstance(metric, _LinkPredMetric)
        self[name] = metric

def split(data: Data, batch: Tensor) -> Tuple[Data, Dict[str, Tensor]]:
    node_slice = cumsum(torch.bincount(batch))
    assert data.edge_index is not None
    row, _ = data.edge_index
    edge_slice = cumsum(torch.bincount(batch[row]))

    # Edge indices should start at zero for every graph.
    data.edge_index -= node_slice[batch[row]].unsqueeze(0)

    slices = {'edge_index': edge_slice}

    if data.x is None:
        data._num_nodes = torch.bincount(batch).tolist()
        data.num_nodes = batch.numel()
    else:
        slices['x'] = node_slice

    if data.edge_attr is not None:
        slices['edge_attr'] = edge_slice

    if data.y is not None:
        assert isinstance(data.y, Tensor)
        slices['y'] = node_slice if data.y.size(0) == batch.size(0) else torch.arange(0, int(batch[-1]) + 2, dtype=torch.long)

    return data, slices

def is_torch_sparse_tensor(src: Any) -> bool:
    r"""Returns :obj:`True` if the input :obj:`src` is a
    :class:`torch.sparse.Tensor` (in any sparse layout).

    Args:
        src (Any): The input object to be checked.
    """
    return isinstance(src, Tensor) and src.layout in {
        torch.sparse_coo, torch.sparse_csr, torch.sparse_csc
    }

def __init__(
    self,
    in_channels: Union[int, Dict[str, int]],
    out_channels: int,
    metadata: Metadata,
    heads: int = 1,
    negative_slope=0.2,
    dropout: float = 0.0,
    **kwargs,
):
    super().__init__(aggr='add', node_dim=0, **kwargs)

    self.in_channels = (
        {node_type: in_channels for node_type in metadata[0]}
        if not isinstance(in_channels, dict) else in_channels
    )

    self.heads = heads
    self.out_channels = out_channels
    self.negative_slope = negative_slope
    self.metadata = metadata
    self.dropout = dropout
    self.k_lin = nn.Linear(out_channels, out_channels)
    self.q = nn.Parameter(torch.empty(1, out_channels))

    self.proj = nn.ModuleDict({
        node_type: Linear(in_ch, out_channels)
        for node_type, in_ch in self.in_channels.items()
    })

    dim = out_channels // heads
    self.lin_src = nn.ParameterDict({
        '__'.join(edge_type): nn.Parameter(torch.empty(1, heads, dim))
        for edge_type in metadata[1]
    })
    self.lin_dst = nn.ParameterDict({
        '__'.join(edge_type): nn.Parameter(torch.empty(1, heads, dim))
        for edge_type in metadata[1]
    })

    self.reset_parameters()

def __init__(self, dataset, num_layers, hidden, mode='cat'):
    super().__init__()
    self.conv1 = self._create_gin_conv(dataset.num_features, hidden)
    self.convs = torch.nn.ModuleList(
        [self._create_gin_conv(hidden, hidden) for _ in range(num_layers - 1)]
    )
    self.jump = JumpingKnowledge(mode)
    self.lin1 = Linear(num_layers * hidden if mode == 'cat' else hidden, hidden)
    self.lin2 = Linear(hidden, dataset.num_classes)

def _create_gin_conv(self, in_channels, out_channels):
    return GINConv(
        Sequential(
            Linear(in_channels, out_channels),
            ReLU(),
            BN(out_channels),
            Linear(out_channels, out_channels),
            ReLU(),
            BN(out_channels),
        ), train_eps=True
    )

def get_pair_wise_distance(
    ys: List,
    num_classes: int,
    dist_type: str = 'kl',
) -> np.ndarray:
    num_batches = len(ys)
    counts = np.zeros((num_batches, num_classes), dtype=np.int32)

    for i, y in enumerate(ys):
        unique, count = np.unique(y, return_counts=True)
        counts[i, unique] = count

    counts = (counts + 1) / counts.sum(axis=1, keepdims=True)
    pairwise_dist = np.zeros((num_batches, num_batches), dtype=np.float64)

    def kl_divergence(p: np.ndarray, q: np.ndarray) -> float:
        return np.sum(p * np.log(p / q))

    for i in range(num_batches - 1):
        for j in range(i + 1, num_batches):
            if dist_type == 'l1':
                dist = np.sum(np.abs(counts[i] - counts[j]))
            elif dist_type == 'kl':
                dist = kl_divergence(counts[i], counts[j]) + kl_divergence(counts[j], counts[i])
            else:
                raise ValueError("Unsupported distance type")
            pairwise_dist[i, j] = dist

    pairwise_dist += pairwise_dist.T
    pairwise_dist += 1e-5  # for numerical stability
    np.fill_diagonal(pairwise_dist, 0.)

    return pairwise_dist

def filter_edge_store_(store: EdgeStorage, out_store: EdgeStorage, row: Tensor,
                       col: Tensor, index: OptTensor, perm: OptTensor = None):
    def handle_edge_index(value):
        edge_index = torch.stack([row, col], dim=0).to(value.device)
        out_store.edge_index = edge_index

    def handle_adj_t(value):
        row_device, col_device = row.to(value.device()), col.to(value.device())
        edge_attr = value.storage.value()
        if edge_attr is not None and index is not None:
            index = index.to(edge_attr.device)
            edge_attr = index_select(edge_attr, index, dim=0)
        sparse_sizes = out_store.size()[::-1]
        out_store.adj_t = SparseTensor(row=col_device, col=row_device, value=edge_attr,
                                       sparse_sizes=sparse_sizes,
                                       is_sorted=False, trust_data=True)

    def handle_edge_attr(key, value):
        if index is None:
            out_store[key] = None
            return

        dim = store._parent().__cat_dim__(key, value, store)
        index_device = index.to(value.device) if isinstance(value, (Tensor, TensorFrame)) else index.cpu()
        if perm is None:
            out_store[key] = index_select(value, index_device, dim=dim)
        else:
            perm_device = perm.to(value.device) if isinstance(value, (Tensor, TensorFrame)) else perm.cpu()
            out_store[key] = index_select(value, perm_device[index_device.to(torch.int64)], dim=dim)

    for key, value in store.items():
        if key == 'edge_index':
            handle_edge_index(value)
        elif key == 'adj_t':
            handle_adj_t(value)
        elif store.is_edge_attr(key):
            handle_edge_attr(key, value)

def is_experimental_mode_enabled(options: Options = None) -> bool:
    r"""Returns :obj:`True` if the experimental mode is enabled. See
    :class:`torch_geometric.experimental_mode` for a list of (optional)
    options.
    """
    if torch.jit.is_scripting() or torch.jit.is_tracing():
        return False
    return all(__experimental_flag__[option] for option in get_options(options))

def __init__(self, property_name: str, ratios: List[float], ascending: bool = True):
    valid_properties = {'popularity', 'locality', 'density'}
    if property_name not in valid_properties:
        raise ValueError(f"Unexpected 'property_name' (got '{property_name}')")

    if len(ratios) != 5 or sum(ratios) != 1.0:
        raise ValueError(f"'ratios' must contain 5 values and sum to 1.0 "
                         f"(got {len(ratios)} values summing to {sum(ratios)})")

    self.property_name = property_name
    self.compute_fn = _property_name_to_compute_fn[property_name]
    self.ratios = ratios
    self.ascending = ascending

def get_indptr(self) -> Tensor:
    r"""Returns the compressed index representation in case
    :class:`EdgeIndex` is sorted.
    """
    if self._indptr is None:
        if self.is_undirected and self._T_indptr is not None:
            return self._T_indptr
        dim = 0 if self.is_sorted_by_row else 1
        self._indptr = index2ptr(self._data[dim], self.get_sparse_size(dim))

    return self._indptr

def download(self) -> None:
    def move_files(file_names, source_dir, target_dir):
        for file_name in file_names:
            shutil.move(osp.join(source_dir, file_name), target_dir)

    if not all(osp.exists(f) for f in self.raw_paths[:5]):
        path = download_url(self.url, self.raw_dir)
        extract_zip(path, self.raw_dir)

        move_files(['node-feat', 'node-label', 'relations'], osp.join(self.raw_dir, 'mag', 'raw'), self.raw_dir)
        shutil.move(osp.join(self.raw_dir, 'mag', 'split'), self.raw_dir)
        shutil.move(osp.join(self.raw_dir, 'mag', 'raw', 'num-node-dict.csv.gz'), self.raw_dir)

        fs.rm(osp.join(self.raw_dir, 'mag'))
        os.remove(osp.join(self.raw_dir, 'mag.zip'))

    if self.preprocess is not None:
        path = download_url(self.urls[self.preprocess], self.raw_dir)
        extract_zip(path, self.raw_dir)
        os.remove(path)

def load(self, pid: Optional[int] = None) -> RemoteGraphBackend:
    if self.datatype == RemoteDataType.DATA:
        return self._load_data()
    elif self.datatype == RemoteDataType.PARTITION:
        return self._load_partition(pid)
    else:
        raise NotImplementedError

def _load_data(self) -> RemoteGraphBackend:
    data_obj = torch.load(self.path, weights_only=False)
    graph_store = self.graph_store_type.from_data(
        edge_id=data_obj['edge_id'], edge_index=data_obj.edge_index,
        num_nodes=data_obj.num_nodes, is_sorted=True)
    feature_store = self.feature_store_type.from_data(
        node_id=data_obj['node_id'], x=data_obj.x,
        edge_id=data_obj['edge_id'], edge_attr=data_obj.edge_attr)
    return feature_store, graph_store

def _load_partition(self, pid: Optional[int]) -> RemoteGraphBackend:
    if pid is None:
        raise ValueError("Partition ID must be defined for loading from a partitioned store.")
    graph_store = self.graph_store_type.from_partition(self.path, pid)
    feature_store = self.feature_store_type.from_partition(self.path, pid)
    return feature_store, graph_store

def maybe_cast_to_tensor_info(value: Any) -> Union[Any, TensorInfo]:
    if isinstance(value, dict) and 1 <= len(value) <= 3 and 'dtype' in value:
        valid_keys = {'dtype', 'size', 'is_index', 'is_edge_index'}
        if set(value.keys()).issubset(valid_keys):
            return TensorInfo.cast(value)
    return value
